    .replace(/^(describe the payment schedule\/terms:|payment schedule:|payment terms:|fees:)\s*/i, "")
    .trim();
  if (scheduleTextForParsing.indexOf("%") !== -1 || /on\s|upon\s|due\s/i.test(scheduleTextForParsing)) {
