      // "50% after completing services…" lost its row entirely — and
      // stripped the connector from the rows it did keep.
      var desc = part.slice(m.index + m[0].length).replace(/^[\s:,\-–—]+/, "");
      var dateVal = _trimMilestoneTail(desc);
