}

// Stable-ish UUID v4 (crypto.randomUUID when available, else manual).

functions._bdAuditUuid:
function _bdAuditUuid() {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch (_e) {}
  try {
    if (typeof crypto !== "undefined" && crypto.getRandomValues) {
      var b = crypto.getRandomValues(new Uint8Array(16));
      b[6] = (b[6] & 0x0f) | 0x40; b[8] = (b[8] & 0x3f) | 0x80;
      var h = [];
      for (var i = 0; i < 16; i++) h.push((b[i] + 0x100).toString(16).slice(1));
      return h.slice(0, 4).join("") + "-" + h.slice(4, 6).join("") + "-" +
             h.slice(6, 8).join("") + "-" + h.slice(8, 10).join("") + "-" + h.slice(10).join("");
    }
  } catch (_e) {}
  // Last resort — not a true UUID but unique enough for a dedup key.
  return "r" + Math.abs((Date.now() ^ (Math.floor(Math.random() * 1e9))) >>> 0).toString(16) +
         Math.abs(Math.floor(Math.random() * 1e9)).toString(16);
}

// pako-deflate → base64 (chunked). Returns { z:bool, payload:string }.

functions._bdAuditPack:
function _bdAuditPack(json) {
