  return { z: false, payload: json };
}

// Compress + AES-encrypt an audit record for storage / CDN.
// SPLIT design (privacy gate): the sensitive Step 2 fills go into their OWN
// encrypted blob (_bdaFills) separate from the rest (_bdaEnc = metadata +
// Step 1 answers). The CDN push can drop _bdaFills WITHOUT decrypting when
// the per-user share setting is off — so withholding fills is a pure
// field-delete, never a re-encrypt. Local storage always keeps both, so the
// user's own viewer recreates fully.

functions._bdAuditEncode:
function _bdAuditEncode(eli, record) {
