  var fills = record.step2Fills || {};
  var core = {};
  Object.keys(record).forEach(function (k) { if (k !== "step2Fills") core[k] = record[k]; });
  var corePacked = _bdAuditPack(JSON.stringify(core));
  var fillsPacked = _bdAuditPack(JSON.stringify(fills));
  var coreEnv = { _bdaZ: corePacked.z, id: record.id, runId: record.runId, payload: corePacked.payload };
  var fillsEnv = { _bdaZ: fillsPacked.z, payload: fillsPacked.payload };
