    r[coreField.k] = coreField.v;
    r[fillsField.k] = fillsField.v;
    return r;
  }
  if (canEnc) {
    return Promise.all([
      window._eliEncryptForRepo(cipher, coreEnv),
      window._eliEncryptForRepo(cipher, fillsEnv),
    ]).then(function (encs) {
      return _row({ k: "_bdaEnc", v: encs[0] }, { k: "_bdaFills", v: encs[1] });
    }).catch(function () {
      try { eli.log.event("tool", "bd_audit_encrypt_failed", { id: record.id }); } catch (_e) {}
      return _row({ k: "_bdaCorePlain", v: coreEnv }, { k: "_bdaFillsPlain", v: fillsEnv });
    });
  }
  try { eli.log.event("tool", "bd_audit_no_cipher", { id: record.id }); } catch (_e) {}
  return Promise.resolve(_row({ k: "_bdaCorePlain", v: coreEnv }, { k: "_bdaFillsPlain", v: fillsEnv }));
}

// Reverse of _bdAuditEncode. Decrypts the core (metadata + Step 1) and, when
// present, the separate fills blob — re-merging step2Fills. Rows whose fills
// blob was withheld at push time decode fine with step2Fills = {} and a
// `_fillsWithheld: true` marker. Returns Promise<record|null>.

functions._bdAuditDecode:
function _bdAuditDecode(eli, row) {
