  else if (row._bdaEnc && typeof window._eliDecryptFromRepo === "function" && cipher) {
    coreP = window._eliDecryptFromRepo(cipher, row._bdaEnc).then(_unpack).catch(function () { return null; });
  } else coreP = Promise.resolve(null);
  // Resolve the fills envelope, if it's present on the row.
  var fillsP;
  if (row._bdaFillsPlain) fillsP = Promise.resolve(_unpack(row._bdaFillsPlain));
  else if (row._bdaFills && typeof window._eliDecryptFromRepo === "function" && cipher) {
    fillsP = window._eliDecryptFromRepo(cipher, row._bdaFills).then(_unpack).catch(function () { return null; });
  } else fillsP = Promise.resolve(undefined); // undefined = blob absent (withheld)
  return Promise.all([coreP, fillsP]).then(function (parts) {
    var core = parts[0]; var fills = parts[1];
    if (!core) return null;
    if (fills === undefined) { core.step2Fills = {}; core._fillsWithheld = true; }
    else { core.step2Fills = fills || {}; }
    return core;
