  function _str(a, b) { return (a != null && a !== "") ? a : (b || ""); }
  function _obj(a, b) { return (a && Object.keys(a).length) ? a : (b || {}); }
  var toolVersion = meta.toolVersion || (existing.provenance && existing.provenance.toolVersion) || "build_draft";
  // Per-step completion — which steps actually ran, OR'd across saves so a
  // step marked done stays done even when a later (resumed) save only knows
  // about the steps it touched. Distinguishes "reached 4 but skipped error
  // review" from a clean run, and "saved" from "emailed".
  var aSD = meta.stepsDone || {}, eSD = existing.stepsDone || {}, stepsDone = {};
  ["logic", "fill", "errorReview", "saved", "emailed"].forEach(function (k) {
    stepsDone[k] = !!(aSD[k] || eSD[k]);
  });
  // Per-step completion timestamps — earliest known wins (existing first, so a
  // recorded time never moves once set). Drives the hub's "completed at" line
  // and survives pause/resume since it lives in the persisted record.
  var aST = meta.stepTimes || {}, eST = existing.stepTimes || {}, stepTimes = {};
  ["logic", "fill", "errorReview", "saved", "emailed"].forEach(function (k) {
    stepTimes[k] = eST[k] || aST[k] || null;
  });
  return {
    id: _bdAuditConst().PREFIX + runId,
    runId: runId,
    schemaVersion: _bdAuditConst().SCHEMA,
    userId: existing.userId || (ident && ident.userId) || null,
    cpRef: _str(meta.cpRef, existing.cpRef),
    agreementType: _str(meta.agreementType, existing.agreementType),
    cpEntity: _str(meta.cpEntity, existing.cpEntity),
    thirdParty: _str(meta.thirdParty, existing.thirdParty),
    requesterName: _str(meta.requesterName, existing.requesterName),
    templateId: meta.templateId || existing.templateId || null,
    templateName: meta.templateName || existing.templateName || null,
    templateVersion: meta.templateVersion || existing.templateVersion || null,
    startedAt: existing.startedAt || meta.startedAt || null,
    completedAt: meta.completedAt || (eli.now ? eli.now() : Date.now()),
    stepsReached: Math.max(meta.stepsReached || 0, existing.stepsReached || 0),
    stepsDone: stepsDone,
    stepTimes: stepTimes,
    step1Answers: _obj(meta.step1Answers, existing.step1Answers),
    step2Fills: _obj(meta.step2Fills, existing.step2Fills),
    provenance: {
      kernelVersion: (eli && eli.kernelVersion) || "",
      toolVersion: toolVersion,
    },
  };
}

// Upsert an audit run into bd_history (compressed + encrypted). Progressive:
// re-saving the same runId with a higher stepsReached overwrites the row, so
// the final record reflects how far the run got. Never throws into the caller.

functions._bdAuditSave:
function _bdAuditSave(eli, meta) {
  try {
    var c = _bdAuditConst();
    var runId = (meta && meta.runId) || _bdAuditUuid();
    if (meta) meta.runId = runId;
    // Read + decode any prior record for this run so the save MERGES
    // (resume-safe). Decode needs the cipher; if it's unavailable or fails
    // we treat it as no prior record (meta-only) rather than block the save.
    return eli.storage.get(c.STORE, c.PREFIX + runId).then(function (existingRow) {
      if (!existingRow) return null;
      return _bdAuditDecode(eli, existingRow).catch(function () { return null; });
    }).then(function (existing) {
      var record = _bdAuditBuildRecord(eli, meta, existing);
      return _bdAuditEncode(eli, record).then(function (rowToStore) {
        return eli.storage.put(c.STORE, rowToStore).then(function () {
          try {
            eli.log.event("tool", "bd_audit_saved", {
              id: record.id, steps: record.stepsReached,
              s1: Object.keys(record.step1Answers).length,
              s2: Object.keys(record.step2Fills).length,
              merged: !!existing,
            });
          } catch (_e) {}
          return record;
        });
      });
    }).catch(function (e) {
      try { eli.log.event("tool", "bd_audit_save_failed", { msg: e && e.message }); } catch (_e) {}
      return null;
    });
  } catch (e) {
    try { eli.log.event("tool", "bd_audit_save_threw", { msg: e && e.message }); } catch (_e) {}
    return Promise.resolve(null);
  }
}

engine.evalLogicCondition:
function evalLogicCondition(condStr, answers, defs) {
  if (condStr === "true") return true;
  var op = condStr.indexOf("!=") !== -1 ? "!=" : "==";
  var parts = condStr.split(op);
  if (parts.length < 2) return false;
  var k = parts[0].trim();
  var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
  var actual = answers && answers[k];
  if (actual === undefined) return false;
  // "Other" in RHS matches any answer not in the DEF's predefined options
  var hasOtherRhs = rhs.some(function (v) { return /^other$/i.test(v); });
  if (hasOtherRhs && defs && defs[k] && defs[k].options) {
    var isCustom = defs[k].options.indexOf(actual) === -1 && !/^(other|__other__)$/i.test(actual);
    if (isCustom) {
      // Custom-typed value: treat as matching "Other"
      return op === "==";
    }
  }
  return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
}

// Extract unique placeholders from text. Mirrors v2 runTemplateScan
// regex pair (line 6440) PLUS single-bracket marker forms used widely
// in ELI templates ($![Payment], $[Currency], ![Terms]). Pure unmarked
// [X] is intentionally NOT caught — that path is the bracket-cleaner
// for citations / cross-refs / author tags.

engine.extractTemplatePlaceholders:
function extractTemplatePlaceholders(text) {
  var src = String(text || "");
  var found = {};
  // Double brackets with optional $!/$/! prefix.
  var doubleBracketRe = /(\$!|\$|!)?\[\[(.*?)\]\]/g, dm;
  while ((dm = doubleBracketRe.exec(src))) if (dm[0].length > 2) found[dm[0]] = true;
  // Curly braces (template-fill markers, post-Step-1).
  var curlyRe = /\{\{([^}]+)\}\}(\*)?/g, cm;
  while ((cm = curlyRe.exec(src))) if (cm[0].length > 4) found[cm[0]] = true;
  // 2026-06-12: single-bracket forms ($[X] / $![X] / ![X]) are NOT fill
  // markers — SOW sample text uses single-bracket prompts ("$[Insert Fee]")
  // that were getting flagged. Step 2 fills double brackets only; residual
  // single brackets belong to the bracket cleaner that runs after fill.
  return Object.keys(found);
}

engine.analyze:
async function analyze(input, providers) {
  function _esc(s) { return String(s == null ? "" : s); }

  // Load persisted state from Office settings (set by v2 persistAgreementState).
  function _readPersistedAgreement() {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return null;
      var name = s.get("AgreementDataName");
      var type = s.get("AgreementDataType");
      var details = s.get("AgreementDataDetails");
      if (!name && !type && !details) return null;
      return {
        name: name || null,
        type: type || null,
        details: typeof details === "object" ? details : null,
      };
    } catch (e) {
      if (window.eli && window.eli.log) {
        window.eli.log.event("tool", "build_draft_persist_read_failed", { msg: e && e.message });
      }
      return null;
    }
  }

  // First-instance scan for whole-word OARS anywhere in body
  // (case-insensitive). Matches kernel's _eliCheckOarsAndLaunch.
  function _hasOarsAnywhere(bodyText) {
    if (!bodyText) return false;
    return /\bOARS\b/i.test(String(bodyText));
  }

  // Best-effort agreement-type extraction from OARS-formatted body text.
  // OARS docs have "Agreement Type: <type>" lines near the top.
  function _extractAgreementType(bodyText) {
    if (!bodyText) return null;
    var m = String(bodyText).match(/Agreement\s+Type\s*[:=]\s*([^\n\r]+)/i);
    return m ? m[1].trim() : null;
  }

  // Extract key/value pairs. Anchors on first OARS line if present,
  // otherwise parses the whole text. "Field: value" or "Field = value".
  function _extractFields(bodyText) {
    if (!bodyText) return {};
    var lines = String(bodyText).split(/\r?\n/);
    var startIdx = 0;
    for (var j = 0; j < lines.length; j++) {
      if (/\bOARS\b/i.test(lines[j])) { startIdx = j; break; }
    }
    var fields = {};
    var stop = false;
    for (var i = startIdx; i < lines.length && !stop; i++) {
      var ln = lines[i].trim();
      if (!ln) {
        if (Object.keys(fields).length) stop = true;
        continue;
      }
      var m = ln.match(/^([A-Za-z][A-Za-z0-9 _\-]+?)\s*[:=]\s*(.+)$/);
      if (m) fields[m[1].trim()] = m[2].trim();
    }
    return fields;
  }

  // Three OARS data sources (priority order):
  //   1. footerFile — manually uploaded via kernel's DATA loader
  //   2. doc body — auto-scanned
  //   3. doc headers — fallback
  // Highest-priority source with OARS marker wins. Sources are
  // concatenated for fallback field extraction.
  var bodyText   = (input && input.bodyText) || "";
  var headerText = (input && input.headerText) || "";
  var footerText = (input && input.footerFile && input.footerFile.text) || "";
  var footerName = (input && input.footerFile && input.footerFile.name) || null;

  var sourceText = "";
  var source = "none";
  if (_hasOarsAnywhere(footerText))      { sourceText = footerText; source = "footer_file"; }
  else if (_hasOarsAnywhere(bodyText))   { sourceText = bodyText;   source = "doc_body"; }
  else if (_hasOarsAnywhere(headerText)) { sourceText = headerText; source = "doc_header"; }
  else if (footerText)                   { sourceText = footerText; source = "footer_file_no_marker"; }

  var hasOars = source !== "none" && source !== "footer_file_no_marker";
  var persisted = _readPersistedAgreement();
  var detectedType = (persisted && persisted.type) || _extractAgreementType(sourceText);
  var fields = sourceText ? _extractFields(sourceText) : {};

  var releasedAt = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools && window.eli.tools._loaded
        && window.eli.tools._loaded["build_draft"]) {
      releasedAt = window.eli.tools._loaded["build_draft"].releasedAt || "unknown";
    }
  } catch (e) {
    if (window.eli && window.eli.log) {
      window.eli.log.event("tool", "build_draft_releasedat_lookup_failed", { msg: e && e.message });
    }
  }

  // FROM v2 runDocumentScannerBuild (line 21358) — count {{...}} markers.
  // Read-only; the actual logic builder runs as wizard step 1.
  function _scanLogicMarkers(text) {
    var counts = { IF: 0, ELSEIF: 0, ELSE: 0, ENDIF: 0, DEF: 0, TITLE: 0, DELETE_LINE: 0, ENTER: 0, otherCurly: 0 };
    var defKeys = [];
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(String(text || "")))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) counts.IF++;
      else if (t.indexOf("ELSEIF:") === 0) counts.ELSEIF++;
      else if (t.indexOf("ELSE") === 0) counts.ELSE++;
      else if (t.indexOf("ENDIF") === 0) counts.ENDIF++;
      else if (t.indexOf("DEF:") === 0) {
        counts.DEF++;
        var kv = t.substring(4).split("|")[0].split("=")[0].trim();
        if (kv) defKeys.push(kv);
      }
      else if (t.indexOf("TITLE:") === 0) counts.TITLE++;
      else if (t === "DELETE_LINE") counts.DELETE_LINE++;
      else if (t === "ENTER") counts.ENTER++;
      else counts.otherCurly++;
    }
    var total = 0;
    for (var k in counts) total += counts[k];
    return { counts: counts, total: total, defKeys: defKeys };
  }

  // [Placeholder text] — square brackets used as fill targets (FROM v2
  // showBracketCleaner line 22706). Skips obvious false-positives like
  // citation refs ([1], [Author]).
  function _scanBrackets(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\[([^\[\]\n]{2,80})\]/g, m;
    while ((m = re.exec(src))) {
      var inner = m[1].trim();
      // Skip pure-numeric refs ([1], [42]), single-word author cites,
      // and Word's tracked-change markers.
      if (/^\d+$/.test(inner)) continue;
      if (/^\[Comment[ \d]/i.test(m[0])) continue;
      matches.push({ text: m[0], inner: inner, index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // $ amounts in body — financial review trigger.
  function _scanFinancial(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\$\s*[\d,]+(?:\.\d+)?/g, m;
    while ((m = re.exec(src))) {
      matches.push({ text: m[0].replace(/\s+/g, ""), index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // Full DEF parser — mirrors v2 parseLogicDefinition (line 21405).
  // Walks {{IF/ELSEIF/ELSE/ENDIF}} stack and records {{DEF:k=default|opts|warning}}
  // entries with their parent IF expressions as visibility dependencies.
  function _parseLogicDefs(text) {
    var src = String(text || "");
    var defs = {};
    var deps = {};
    var stack = [];
    var title = null;
    var titleGuidance = [];
    var titleMatch = src.match(/\{\{TITLE:\s*([^{}]+)\}\}/i);
    if (titleMatch) {
      // {{TITLE: NDA | Guidance: tip one; tip two; tip three}}
      // Pipe-separated segments after the name. Any segment matching
      // /^\s*guidance\s*:/i becomes a SEMICOLON-split bullet list on the
      // Step 1 first-render premium dialog. Semicolon (not comma) so
      // bullets can contain commas / periods / other punctuation freely.
      // Non-guidance pipe segments are ignored (reserved for extensions).
      var parts = String(titleMatch[1]).split("|");
      title = parts[0].trim();
      for (var ti = 1; ti < parts.length; ti++) {
        var seg = parts[ti].trim();
        var gm = seg.match(/^guidance\s*:\s*(.+)$/i);
        if (gm) {
          gm[1].split(";").forEach(function (b) {
            var t = String(b).trim();
            if (t) titleGuidance.push(t);
          });
        }
      }
    }
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(src))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) stack.push(t.substring(3).trim());
      else if (t.indexOf("ELSEIF:") === 0) {
        if (stack.length) { stack.pop(); stack.push(t.substring(7).trim()); }
      }
      else if (t.indexOf("ELSE") === 0) {
        if (stack.length) { stack.pop(); stack.push("true"); }
      }
      else if (t.indexOf("ENDIF") === 0) {
        if (stack.length) stack.pop();
      }
      else if (t.indexOf("DEF:") === 0 && t.indexOf("|") !== -1) {
        // 2026-05-21 v2: DEF format —
        //   {{DEF: key = default | options | extra1 | extra2 | …}}
        //              pipe[0]    pipe[1]   pipe[2+]
        //
        //   pipe[0]: "key = default" (default is optional)
        //   pipe[1]: comma-separated choices, OR "*placeholder" for text
        //   pipe[2..N]: any number of EXTRA segments. Each one is
        //               classified by its prefix:
        //
        //     "lookup:Counterparty Name" → OARS lookup term. Triggers
        //                                the 🔎 OARS button on the
        //                                question. Case-insensitive
        //                                search inside the OARS viewer.
        //                                (Legacy alias "oars:" still
        //                                accepted during the migration
        //                                window — drop after every
        //                                template is re-pushed.)
        //     anything else            → warning / admin guidance, shown
        //                                inline below the label with a
        //                                ⚠️ icon. Preserves backward-
        //                                compatibility with existing
        //                                templates that put warnings in
        //                                pipe[2].
        //
        //   Order-independent. Either or both can be present. If you
        //   want both: `{{DEF: x = | a, b | warning text | lookup:Field}}`
        //   or the reverse order — parser sorts by prefix.
        //
        // 2026-05-22: switched primary keyword from "oars:" to "lookup:"
        // so the in-doc marker stops triggering the false-positive OARS
        // banner (the engine's _hasOarsAnywhere broad-word scan was
        // matching the "OARS" substring inside DEF segments). Dual-
        // detect during transition. Internal field name stays
        // `oarsLookup` because the button still opens the OARS viewer
        // and renaming variables touches every reference.
        var clean = t.substring(4).trim();
        var pipe = clean.split("|");
        var defPart = pipe[0].trim();
        var optionsPart = pipe.length > 1 ? pipe[1].trim() : null;
        var oarsLookup = null;
        var warning = null;
        var guidance = null;
        for (var pi = 2; pi < pipe.length; pi++) {
          var seg = String(pipe[pi] || "").trim();
          if (!seg) continue;
          if (/^(lookup|oars)\s*:/i.test(seg)) {
            // Strip the prefix; remainder is the search term. Both
            // keywords map to the same oarsLookup field.
            if (!oarsLookup) oarsLookup = seg.replace(/^(lookup|oars)\s*:\s*/i, "").trim() || null;
          } else if (/^guidance\s*:/i.test(seg)) {
            // 2026-05-21: "guidance:" prefix opens a premium dialog
            // showing the body text. For longer instructional content
            // that doesn't fit as an inline warning chip.
            if (!guidance) guidance = seg.replace(/^guidance\s*:\s*/i, "").trim() || null;
          } else if (/^other$/i.test(seg)) {
            // Reserved keyword — handled after parsing
          } else {
            if (!warning) warning = seg;
          }
        }
        if (!optionsPart) continue;
        var defSplit = defPart.split("=");
        var key = defSplit[0].trim();
        var explicitDefault = defSplit.length > 1 ? defSplit[1].trim() : "";
        var isText = optionsPart.charAt(0) === "*";
        var textDefault = isText ? optionsPart.substring(1).trim() : "";
        var _rawOpts = isText ? [] : optionsPart.split(",").map(function (o) { return o.trim(); });
        // OTHER can appear as a comma option OR as a pipe segment
        var _hasOther = _rawOpts.some(function (o) { return /^other$/i.test(o); }) ||
          pipe.some(function (s, i) { return i >= 2 && /^other$/i.test(String(s || "").trim()); });
        if (_hasOther) _rawOpts = _rawOpts.filter(function (o) { return !/^other$/i.test(o); });
        defs[key] = {
          default: explicitDefault || textDefault,
          isText: isText,
          options: _rawOpts,
          hasOther: _hasOther,
          oarsLookup: oarsLookup,
          guidance: guidance,
          warning: warning,
        };
        if (stack.length > 0) deps[key] = stack.slice();
      }
    }
    return { defs: defs, deps: deps, count: Object.keys(defs).length, title: title, titleGuidance: titleGuidance };
  }

  var logicScan = _scanLogicMarkers(bodyText);
  var bracketScan = _scanBrackets(bodyText);
  var financialScan = _scanFinancial(bodyText);
  var logicDefs = _parseLogicDefs(bodyText);
  // Fill-candidate count: what Step 2 will actually offer to fill. Same
  // regex set as the top-level extractTemplatePlaceholders fn (inlined
  // because each engine fn is eval'd in its own scope and can't call
  // siblings directly). Body-only — Step 2's own scan extends to
  // headers + footers, so this can undercount slightly.
  function _scanFillCandidates(text) {
    // 2026-05-29: Hub "Fill Fields" count = Step 2 targets only. The raw
    // doc (pre-Step-1) still has {{IF}}/{{DEF}}/{{TITLE}} logic markers —
    // those belong to Step 1 (Build Logic) and are counted there, so
    // counting {{ }} here double-counts and inflates the fill total. Step 2
    // fills [[ ]] (optionally $!/$/! prefixed) only; {{ }} is resolved away
    // in Step 1. 2026-06-12: single-bracket $[ ]/$![ ]/![ ] dropped — SOW
    // sample prompts use single brackets and were getting counted.
    var src = String(text || "");
    var found = {};
    var dRe = /(\$!|\$|!)?\[\[(.*?)\]\]/g, dm;
    while ((dm = dRe.exec(src))) if (dm[0].length > 2) found[dm[0]] = true;
    return Object.keys(found);
  }
  var fillCandidates = _scanFillCandidates(bodyText);

  var sourceLabel = source === "footer_file" ? ("File: " + (footerName || "uploaded"))
                  : source === "footer_file_no_marker" ? ("File: " + (footerName || "uploaded"))
                  : source === "doc_body"   ? "Document body"
                  : source === "doc_header" ? "Document header"
                  : null;
  return {
    items: [],
    overview: hasOars
      ? ("OARS · " + (sourceLabel || "detected") + (detectedType ? " · " + detectedType : ""))
      : (footerText ? ("File loaded · " + (footerName || "—"))
        : persisted ? ("Saved · " + (persisted.type || persisted.name || "—")) : "Standard mode"),
    hasOars: hasOars,
    source: source,
    sourceLabel: sourceLabel,
    footerFile: input && input.footerFile ? { name: footerName, size: input.footerFile.size } : null,
    persisted: persisted,
    detectedType: detectedType,
    fieldCount: Object.keys(fields).length,
    fields: fields,
    logicScan: logicScan,
    bracketScan: bracketScan,
    financialScan: financialScan,
    fillScan: { items: fillCandidates, total: fillCandidates.length },
    logicDefs: logicDefs,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: releasedAt,
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

view.renderHub:
function renderHub(opts) {
  var result = opts.result || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var onClose = opts.onClose || function () {};
  var onRunAll = opts.onRunAll || function () {};
  var onTemplates = opts.onTemplates || function () {};
  var onStep = opts.onStep || function () {};
  var onClearOars = opts.onClearOars || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";

  // Header bar — dark navy banner with gold accent rule (matches the
  // standard tool-hub header style). Right side carries a small
  // 📂 Templates button (replaces the old big TEMPLATES tile).
  var bar = document.createElement("div");
  bar.className = "_eli3_bd_bar";
  bar.innerHTML =
    '<button class="_eli3_bd_back" title="Back">←</button>' +
    '<div class="_eli3_bd_title">⚡ Build Draft Hub</div>' +
    '<button class="_eli3_bd_bar_templates" title="Templates library">📂</button>';
  bar.querySelector("._eli3_bd_back").onclick = onClose;
  bar.querySelector("._eli3_bd_bar_templates").onclick = onTemplates;
  root.appendChild(bar);

  // OARS status banner — shown when ANY source has data: OARS-marked
  // body/header, persisted state, or a footer-uploaded file.
  if (result.hasOars || result.persisted || result.footerFile) {
    var banner = document.createElement("div");
    banner.className = "_eli3_bd_oars_banner";
    var typeLabel = (result.detectedType || (result.persisted && result.persisted.type) || "—");
    // Only append a name suffix when there's a REAL filename to show.
    // `persisted.name` gets set to the literal sentinel "OARS DATA" in
    // init.js when OARS data is loaded without an associated file — and
    // we don't want to render that sentinel here (the eyebrow already
    // says "OARS DATA"). Strip known sentinel placeholder names.
    var rawName = (result.persisted && result.persisted.name)
               || (result.footerFile && result.footerFile.name)
               || "";
    var SENTINELS = ["OARS DATA", "OARS data", "OARS document", "OARS"];
    var nameLabel = SENTINELS.indexOf(String(rawName).trim()) !== -1 ? "" : rawName;
    // Detect the empty-banner case: banner renders (hasOars / persisted /
    // footerFile triggered it) but every useful field is missing —
    // typeLabel is the em-dash fallback, no filename, no requester, no
    // fieldCount. Show a clear "No OARS data attached" message so the
    // user doesn't see a lone "—" above the eyebrow.
    var hasUsefulOarsInfo = (typeLabel !== "—") || nameLabel || result.requesterName || result.fieldCount;
    // Two skins, one structure: populated = navy-gradient premium header
    // (gold eyebrow lead in the meta row, serif white headline); empty =
    // quiet dashed "waiting slot" card. Modifier class flips the CSS.
    if (!hasUsefulOarsInfo) banner.classList.add("_eli3_bd_oars_banner_empty");
    var metaHtml;
