        ? '<span class="_eli3_bd_logic_label_btns">' + guidanceBtnHtml + oarsBtnHtml + '</span>'
        : "";
      var labelHtml = '<span class="_eli3_bd_logic_label_text">' + _esc(key) + '</span>' +
        (def.warning ? '<span class="_eli3_bd_logic_warning">⚠️ ' + _esc(def.warning) + '</span>' : '') +
        btnGroup;
      group.innerHTML = '<label class="_eli3_bd_logic_label">' + labelHtml + '</label>';
      if (def.isText) {
        var hint = document.createElement("div");
        hint.className = "_eli3_bd_logic_hint";
        hint.textContent = "Free Form Entry — leave as 'Don't know' if not sure.";
        group.appendChild(hint);
        // 2026-05-20: wrap text inputs in a leading-icon container so
        // free-text questions are visually distinct from dropdowns.
        // The icon + cream-amber tint signal "type here" vs "pick one"
        // at a glance, while preserving the gold-rail premium look.
        var wrap = document.createElement("div");
        wrap.className = "_eli3_bd_logic_text_wrap";
        var icon = document.createElement("span");
        icon.className = "_eli3_bd_logic_text_icon";
        icon.textContent = "✍️";
        icon.setAttribute("aria-hidden", "true");
        wrap.appendChild(icon);
