      gen.classList.remove("_eli3_bd_apply_working");
      gen.innerHTML = "🚀 GENERATE DOCUMENT";
    });
  };
  actions.appendChild(gen);
  root.appendChild(actions);

  mount.appendChild(root);
  _updateVisibility();

  // Premium guidance dialog — fires when the template's {{TITLE}} tag
  // carried a "| Guidance: …" pipe segment. One bullet per comma-split
