// buildOarsSummarizeBar — premium "Summarize" bar pinned at the very top of
// the OARS data column. opts.onSummarize() → Promise<string> (the AI call
// lives in init). Renders the result in a premium dialog. Returns a DOM
// element the caller inserts above the OARS table.

view.buildOarsSummarizeBar:
function buildOarsSummarizeBar(opts) {
  opts = opts || {};
  var onSummarize = opts.onSummarize || function () { return Promise.reject(new Error("Summarize unavailable")); };
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Lightweight markdown → HTML: **bold**, bullet lines, paragraphs.
  function _fmt(text) {
    var safe = _esc(text).replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    var lines = safe.split(/\r?\n/);
    var html = "", inList = false;
    lines.forEach(function (ln) {
      var t = ln.trim();
      var mb = t.match(/^[\*\-•]\s+(.*)$/);
      if (mb) {
        if (!inList) { html += '<ul style="margin:4px 0 12px;padding-left:20px;color:#334155;">'; inList = true; }
        html += '<li style="margin:3px 0;">' + mb[1] + "</li>";
      } else {
        if (inList) { html += "</ul>"; inList = false; }
        if (t) html += '<p style="margin:0 0 9px;color:#1e293b;">' + t + "</p>";
      }
    });
    if (inList) html += "</ul>";
    return html;
  }
  function _showResult(text) {
    if (typeof showEliDialog !== "function") return;
    showEliDialog({
      variant: "info",
      tier: "premium",
      size: "wide",
      icon: "✨",
      title: "Agreement Summary",
      paragraphs: [
        '<div style="font:400 14px/1.65 Inter,sans-serif;">' + _fmt(text) + "</div>",
      ],
      primary: { label: "Close" },
    });
  }
  // Compact header pill — inserted into the OARS column header to the left
  // of the magnifying-glass filter toggle.
  var btn = document.createElement("button");
  btn.type = "button";
  btn.className = "_eli3_bd_oars_sumbtn";
  btn.title = "AI summary of this agreement from the OARS data";
  btn.innerHTML = '<span class="_eli3_bd_oars_sumic">✨</span><span class="_eli3_bd_oars_sumlbl">Summarize</span>';
  btn.onclick = function () {
    if (btn.disabled) return;
    var _orig = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<span class="_eli3_bd_oars_sumspin"></span><span class="_eli3_bd_oars_sumlbl">Summarize</span>';
    function _reset() { btn.disabled = false; btn.innerHTML = _orig; }
    Promise.resolve().then(function () { return onSummarize(); }).then(function (text) {
      _reset();
      if (text && String(text).trim()) { _showResult(String(text).trim()); return; }
      if (typeof eli !== "undefined" && eli.ui && eli.ui.alert) eli.ui.alert({ title: "Summary", message: "No summary could be generated from the OARS data." });
    }).catch(function (err) {
      _reset();
      var msg = (err && err.message) || "Could not generate a summary.";
      if (typeof eli !== "undefined" && eli.ui && eli.ui.alert) eli.ui.alert({ title: "Summary unavailable", message: msg });
    });
  };
  return btn;
}

// renderGuidedLogicForm — Step 1 guided mode. One question at a time with
