// Setting: build_draft.guidedMode (off by default).
// Shared AI recommendation dialog — draggable + resizable, used by both
// Step 1 (guidance Ask ELI) and Step 2 (| ai: inline lookup).
// opts: { title, body (HTML), onUseAnswer?, answerText? }

view.showAiRecommendationDialog:
function showAiRecommendationDialog(opts) {
  var _esc2 = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); };
  var overlay = document.createElement("div");
  overlay.style.cssText = "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,.4);z-index:9999;display:flex;align-items:center;justify-content:center;";
  var dlg = document.createElement("div");
  dlg.style.cssText = "position:absolute;width:380px;min-width:260px;max-width:95vw;min-height:180px;max-height:90vh;background:#fff;border-radius:12px;border:1px solid #e2e8f0;box-shadow:0 24px 60px rgba(15,23,42,.35);display:flex;flex-direction:column;overflow:hidden;resize:both;";
  // Header — draggable
  var hdr = document.createElement("div");
  hdr.style.cssText = "background:linear-gradient(135deg,#0d1b2a,#1b263b);padding:12px 16px;border-bottom:2px solid #c9a227;cursor:move;display:flex;align-items:center;gap:10px;flex:0 0 auto;user-select:none;";
  hdr.innerHTML = '<span style="font-size:18px;">💬</span><span style="font:800 14px/1.15 Georgia,serif;color:#fff;">' + _esc2(opts.title || "ELI Recommendation") + '</span>';
  // Close button
  var closeBtn = document.createElement("button");
  closeBtn.style.cssText = "margin-left:auto;background:none;border:none;color:#94a3b8;font-size:18px;cursor:pointer;padding:0 4px;";
  closeBtn.innerHTML = "&times;";
  closeBtn.onclick = function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); };
  hdr.appendChild(closeBtn);
  dlg.appendChild(hdr);
  // Drag logic
  hdr.addEventListener("mousedown", function (e) {
    if (e.target === closeBtn) return;
    e.preventDefault();
    var rect = dlg.getBoundingClientRect();
    var offX = e.clientX - rect.left, offY = e.clientY - rect.top;
    function onMove(ev) { dlg.style.left = (ev.clientX - offX) + "px"; dlg.style.top = (ev.clientY - offY) + "px"; }
    function onUp() { document.removeEventListener("mousemove", onMove); document.removeEventListener("mouseup", onUp); }
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
  });
  // Body
  var body = document.createElement("div");
  body.style.cssText = "flex:1 1 auto;overflow-y:auto;padding:16px 18px;font:500 13px/1.6 Inter,sans-serif;color:#1e293b;";
  body.innerHTML = opts.body || "";
  dlg.appendChild(body);
  // Footer
  var footer = document.createElement("div");
  footer.style.cssText = "flex:0 0 auto;padding:10px 16px;background:linear-gradient(180deg,#fff,#f8fafc);border-top:1px solid #e2e8f0;display:flex;gap:8px;justify-content:flex-end;";
  if (opts.onUseAnswer && opts.answerText) {
    var useBtn = document.createElement("button");
    useBtn.type = "button";
    useBtn.style.cssText = "padding:8px 18px;border:none;border-radius:8px;background:linear-gradient(135deg,#c9a227,#dbb846);color:#fff;font:700 12px/1 Inter,sans-serif;cursor:pointer;";
    useBtn.textContent = "✓ Use This Answer";
    useBtn.onclick = function () {
      opts.onUseAnswer(opts.answerText);
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    };
    footer.appendChild(useBtn);
  }
  var dismissBtn = document.createElement("button");
  dismissBtn.type = "button";
  dismissBtn.style.cssText = "padding:8px 18px;border:1px solid #cbd5e1;border-radius:8px;background:linear-gradient(180deg,#fff,#f1f5f9);color:#475569;font:600 12px/1 Inter,sans-serif;cursor:pointer;";
  dismissBtn.textContent = opts.onUseAnswer ? "Dismiss" : "Got it";
  dismissBtn.onclick = function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); };
  footer.appendChild(dismissBtn);
  dlg.appendChild(footer);
  overlay.appendChild(dlg);
  // Click outside to close
  overlay.addEventListener("click", function (e) { if (e.target === overlay) { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); } });
  document.body.appendChild(overlay);
}

view.renderGuidedLogicForm:
function renderGuidedLogicForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var defs = opts.defs || {};
  var deps = opts.deps || {};
  var docTitle = opts.title || "Document Builder";
  var titleGuidance = opts.titleGuidance || [];
  var onGenerate = opts.onGenerate || function () {};
  var onBack = opts.onBack || function () {};
  var onOarsLookup = opts.onOarsLookup || function () {};
  var onGuidance = opts.onGuidance || function () {};
  var onProgress = opts.onProgress || function () {};
  var onEmailRequester = opts.onEmailRequester || function () {};
  var oarsFields = opts.oarsFields || {};
  var oarsTablesData = opts.oarsTablesData || [];
  var summarizeFactory = opts.summarizeFactory || null;
  // Questions flagged (by key) for the "Email Requester" batch — persists across
  // question navigation, mirrors Step 2's _gfEmailLabels.
  var _glEmailLabels = new Set();
  // True when an OARS value is effectively empty — blank, dashes, or a common
  // placeholder ("--", "—", "N/A", "TBD", "None"). A present-but-empty field is
  // treated as "no answer" so the warning + Email Requester box still show.
  function _glIsBlankOars(v) {
    var s = String(v == null ? "" : v).trim();
    if (!s) return true;
    if (/^[-–—._ \s]+$/.test(s)) return true;
    return /^(n\/?a|tbd|none|null)$/i.test(s);
  }

  // Render full OARS tables (same structure as the Unprocessed tab in the
  // OARS viewer). Each table is a 2D array; first row = header.
  function _renderOarsTables() {
    if (!oarsTablesData.length) return '<div class="_eli3_bd_guided_ctx_empty">No raw OARS table data available.</div>';
    return oarsTablesData.map(function (tbl) {
      if (!tbl || !tbl.length) return "";
      var headerCells = tbl[0] || [];
      var bodyRows = tbl.slice(1);
      var headerText = headerCells.filter(function (c) { return c != null && String(c).trim(); })
        .map(function (c) { return String(c).trim(); }).join(" · ");
      var maxCols = headerCells.length;
      bodyRows.forEach(function (r) { if (r && r.length > maxCols) maxCols = r.length; });
      maxCols = Math.max(1, maxCols);
      var html = '<table class="_eli3_bd_guided_oars_tbl">' +
        '<thead><tr><th colspan="' + maxCols + '" class="_eli3_bd_guided_oars_tbl_th">' + _esc(headerText) + '</th></tr></thead><tbody>';
      bodyRows.forEach(function (row) {
        html += '<tr>';
        for (var ci = 0; ci < maxCols; ci++) {
          var v = (row && row[ci] != null) ? String(row[ci]) : "";
          html += '<td class="_eli3_bd_guided_oars_tbl_td' + (v.trim() ? '' : ' _eli3_bd_guided_oars_tbl_empty') + '">' +
            (v.trim() ? _esc(v) : '<span style="color:#cbd5e1;">—</span>') + '</td>';
        }
        html += '</tr>';
      });
      html += '</tbody></table>';
      return html;
    }).join("");
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Render OARS fields inline as a key-value grid, highlighting rows that
  // match the search term (case-insensitive substring). Returns HTML string.
  function _renderOarsInline(searchTerm) {
    var keys = Object.keys(oarsFields);
    if (!keys.length) return '<div class="_eli3_bd_guided_ctx_empty">No OARS data loaded.</div>';
    var term = String(searchTerm || "").toLowerCase().trim();
    return '<div class="_eli3_bd_guided_oars_grid">' + keys.map(function (k) {
      var v = String(oarsFields[k] || "");
      var kl = k.toLowerCase(), vl = v.toLowerCase();
      var hit = term && (kl.indexOf(term) !== -1 || vl.indexOf(term) !== -1);
      return '<div class="_eli3_bd_guided_oars_row' + (hit ? ' _eli3_bd_guided_oars_hit' : '') + '">' +
        '<span class="_eli3_bd_guided_oars_k">' + _esc(k) + '</span>' +
        '<span class="_eli3_bd_guided_oars_v">' + _esc(v) + '</span>' +
      '</div>';
    }).join("") + '</div>';
  }

  var _evalCondition = opts.evalCondition || function (cond, ans, _defs) {
    if (cond === "true") return true;
    var op = cond.indexOf("!=") !== -1 ? "!=" : "==";
    var parts = cond.split(op);
    if (parts.length < 2) return false;
    var k = parts[0].trim();
    var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
    var actual = ans && ans[k];
    if (actual === undefined) return false;
    var hasOtherRhs = rhs.some(function (v) { return /^other$/i.test(v); });
    if (hasOtherRhs && _defs && _defs[k] && _defs[k].options) {
      if (_defs[k].options.indexOf(actual) === -1 && !/^(other|__other__)$/i.test(actual)) return op === "==";
    }
    return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
  };

  // Persist answers + touched + currentIdx to the document so going home
  // and returning resumes where the user left off. Uses Office doc settings
  // (same mechanism as OARS data / audit run ID — travels with the .docx).
  function _saveProgress() {
    try {
      var s = Office.context.document.settings;
      s.set("BdGuidedProgress", { answers: answers, touched: touched, idx: currentIdx });
      if (typeof s.saveAsync === "function") s.saveAsync(function () {});
    } catch (_e) {}
    var vis = _visibleKeys();
    var c = _countAnswered();
    var curKey = currentIdx < vis.length ? vis[currentIdx] : null;
    onProgress({ answered: c.answered, total: c.total, currentIdx: currentIdx, currentKey: curKey });
  }
  function _loadProgress() {
    try {
      var s = Office.context.document.settings;
      var saved = s.get("BdGuidedProgress");
      if (saved && saved.answers) return saved;
    } catch (_e) {}
    return null;
  }

  // Build the ordered list of visible question keys, respecting deps.
  var allKeys = Object.keys(defs);
  var answers = {};
  var touched = {}; // tracks which questions the user explicitly answered
  allKeys.forEach(function (k) { answers[k] = defs[k].default || (defs[k].isText ? "" : (defs[k].options && defs[k].options[0]) || ""); });

  // Restore prior progress — doc settings first, IDB fallback second.
  var _prior = _loadProgress() || (opts.idbProgress || null);
  if (_prior) {
    if (_prior.answers) { Object.keys(_prior.answers).forEach(function (k) { if (allKeys.indexOf(k) !== -1) answers[k] = _prior.answers[k]; }); }
    if (_prior.touched) { Object.keys(_prior.touched).forEach(function (k) { if (_prior.touched[k]) touched[k] = true; }); }
  }

  function _visibleKeys() {
    return allKeys.filter(function (k) {
      var rules = deps[k] || [];
      return rules.every(function (r) { return _evalCondition(r, answers, defs); });
    });
  }

  var currentIdx = (_prior && typeof _prior.idx === "number") ? _prior.idx : 0;
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_guided_root";

  // Header bar
  root.innerHTML =
    '<div class="_eli3_bd_guided_header">' +
      '<button class="_eli3_bd_guided_back" title="Back to hub">←</button>' +
      '<div class="_eli3_bd_guided_header_text">' +
        '<div class="_eli3_bd_guided_eyebrow">GUIDED MODE</div>' +
        '<div class="_eli3_bd_guided_title">🏗️ ' + _esc(docTitle) + '</div>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_bd_guided_body" id="_eli3_bd_guided_body"></div>';
  root.querySelector("._eli3_bd_guided_back").onclick = onBack;
  mount.appendChild(root);

  var bodyEl = root.querySelector("#_eli3_bd_guided_body");

  function _countAnswered() {
    var vis = _visibleKeys();
    var answered = 0;
    vis.forEach(function (k) {
      if (touched[k]) answered++;
    });
    return { answered: answered, total: vis.length };
  }

  function _updateProgress() {
    var c = _countAnswered();
    var pct = c.total ? Math.round((c.answered / c.total) * 100) : 0;
    var fillEl = bodyEl.querySelector("#_eli3_bd_guided_fill");
    var plabelEl = bodyEl.querySelector("#_eli3_bd_guided_plabel");
    if (fillEl) fillEl.style.width = pct + "%";
    if (plabelEl) plabelEl.textContent = c.answered + " of " + c.total + " answered · " + (c.total - c.answered) + " remaining";
  }

  function _renderQuestion() {
    var vis = _visibleKeys();
    if (currentIdx < 0) currentIdx = 0;

    // Generate screen — shown after the last question is answered
    if (currentIdx >= vis.length) {
      bodyEl.innerHTML = "";
      var card = document.createElement("div");
      card.className = "_eli3_bd_guided_card";

      // Left column — summary + actions
      var left = document.createElement("div");
      left.className = "_eli3_bd_guided_left";
      var leftContent = document.createElement("div");
      leftContent.className = "_eli3_bd_guided_left_content";
      leftContent.style.cssText = "display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:18px;padding:32px 24px;";

      var c = _countAnswered();
      var statusIcon = document.createElement("div");
      statusIcon.style.cssText = "font-size:48px;line-height:1;";
      statusIcon.textContent = c.answered >= c.total ? "✅" : "⚠️";
      leftContent.appendChild(statusIcon);

      var statusTitle = document.createElement("div");
      statusTitle.style.cssText = "font-size:18px;font-weight:700;color:#1e293b;letter-spacing:-.3px;";
      statusTitle.textContent = c.answered >= c.total ? "All Questions Answered" : c.answered + " of " + c.total + " Answered";
      leftContent.appendChild(statusTitle);

      var statusSub = document.createElement("div");
      statusSub.style.cssText = "font-size:13px;color:#64748b;max-width:280px;line-height:1.5;";
      statusSub.textContent = c.answered >= c.total
        ? "Your answers are ready. Click Generate to create the document."
        : "Some questions are unanswered. You can still generate, but the document may use defaults for missing answers.";
      leftContent.appendChild(statusSub);

      // Summary chips — answered count
      var chips = document.createElement("div");
      chips.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:6px 0;";
      chips.innerHTML =
        '<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:10px;background:#f0fdf4;color:#16a34a;font-size:11px;font-weight:600;">✓ ' + c.answered + ' answered</span>' +
        (c.total - c.answered > 0
          ? '<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:10px;background:#fef3c7;color:#92400e;font-size:11px;font-weight:600;">— ' + (c.total - c.answered) + ' using defaults</span>'
          : '');
      leftContent.appendChild(chips);

      // Generate button
      var genBtn = document.createElement("button");
      genBtn.type = "button";
      genBtn.style.cssText = "margin-top:12px;padding:14px 36px;border:none;border-radius:10px;background:linear-gradient(135deg,#c9a227 0%,#dbb846 100%);color:#fff;font-size:15px;font-weight:700;letter-spacing:.3px;cursor:pointer;box-shadow:0 2px 8px rgba(201,162,39,.35);transition:filter .15s;";
      genBtn.textContent = "🚀 Generate Document";
      genBtn.onmouseover = function () { if (!genBtn.disabled) genBtn.style.filter = "brightness(1.08)"; };
      genBtn.onmouseout = function () { if (!genBtn.disabled) genBtn.style.filter = ""; };
      // 2026-06-12: double-click guard + animated working state (same
      // treatment as the guided form's Fill All Fields button).
      genBtn.onclick = function () {
        if (genBtn.disabled) return;
        genBtn.disabled = true;
        var prevCss = genBtn.style.cssText;
        genBtn.style.cssText = prevCss + "display:inline-flex;align-items:center;gap:8px;cursor:progress;filter:none;";
        genBtn.classList.add("_eli3_bd_apply_working");
        var phrases = ["Generating your document…", "Resolving IF/ELSE logic…", "Removing unused clauses…", "Cleaning up scaffolding…", "Finishing touches…"];
        var pi = 0;
        genBtn.innerHTML =
          '<span class="_eli3_bd_work_spin"></span>' +
          '<span class="_eli3_bd_work_phrase _eli3_bd_work_phrase_in">' + phrases[0] + '</span>';
        var phraseEl = genBtn.querySelector("._eli3_bd_work_phrase");
        var timer = setInterval(function () {
          pi = (pi + 1) % phrases.length;
          phraseEl.classList.remove("_eli3_bd_work_phrase_in");
          void phraseEl.offsetWidth;
          phraseEl.textContent = phrases[pi];
          phraseEl.classList.add("_eli3_bd_work_phrase_in");
        }, 1800);
        onGenerate(answers, function () {
          clearInterval(timer);
          genBtn.disabled = false;
          genBtn.classList.remove("_eli3_bd_apply_working");
          genBtn.style.cssText = prevCss;
          genBtn.textContent = "🚀 Generate Document";
        });
      };
      leftContent.appendChild(genBtn);

      left.appendChild(leftContent);

      // Nav — Back + Start Over
      var nav = document.createElement("div");
      nav.className = "_eli3_bd_guided_nav";
      var backBtn = document.createElement("button");
      backBtn.type = "button";
      backBtn.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_prev";
      backBtn.textContent = "← Back";
      backBtn.onclick = function () { currentIdx = vis.length - 1; _renderQuestion(); };
      nav.appendChild(backBtn);
      var soBtn = document.createElement("button");
      soBtn.type = "button";
      soBtn.className = "_eli3_bd_guided_nav_btn _eli3_bd_guided_nav_startover";
      soBtn.textContent = "↺ Start Over";
      soBtn.onclick = function () {
        allKeys.forEach(function (k) {
          answers[k] = defs[k].default || (defs[k].isText ? "" : (defs[k].options && defs[k].options[0]) || "");
          delete touched[k];
        });
        currentIdx = 0;
        _saveProgress();
        _renderQuestion();
      };
      nav.appendChild(soBtn);
      left.appendChild(nav);

      // Progress bar — full
      var progWrap = document.createElement("div");
      progWrap.className = "_eli3_bd_guided_progress_bar";
      var pct = c.total ? Math.round((c.answered / c.total) * 100) : 100;
      progWrap.innerHTML =
        '<div class="_eli3_bd_guided_progress_fill" style="width:' + pct + '%"></div>' +
        '<div class="_eli3_bd_guided_progress_label">' + c.answered + ' of ' + c.total + ' answered</div>';
      left.appendChild(progWrap);

      card.appendChild(left);

      // Right column — answer summary
      var right = document.createElement("div");
      right.className = "_eli3_bd_guided_right";
      var colHeader = document.createElement("div");
      colHeader.className = "_eli3_bd_guided_col_header";
      colHeader.innerHTML = '<span class="_eli3_bd_guided_col_icon">📋</span><span>YOUR ANSWERS</span>';
      right.appendChild(colHeader);

      var rightBody = document.createElement("div");
      rightBody.className = "_eli3_bd_guided_right_body";
      var summaryHtml = '<div style="padding:12px 16px;display:flex;flex-direction:column;gap:8px;">';
      vis.forEach(function (k, i) {
        var val = answers[k] || "(default)";
        var isTouched = touched[k];
        summaryHtml +=
          '<div style="display:flex;align-items:baseline;gap:8px;padding:6px 10px;border-radius:6px;background:' + (isTouched ? '#f8fafc' : '#fefce8') + ';border:1px solid ' + (isTouched ? '#e2e8f0' : '#fde68a') + ';cursor:pointer;" data-goto="' + i + '">' +
          '<span style="font-size:10px;font-weight:700;color:#94a3b8;min-width:20px;">' + (i + 1) + '</span>' +
          '<span style="font-size:12px;font-weight:600;color:#334155;flex:1;">' + _esc(k) + '</span>' +
          '<span style="font-size:11px;color:' + (isTouched ? '#16a34a' : '#92400e') + ';font-weight:500;max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(val) + '</span>' +
          '</div>';
      });
      summaryHtml += '</div>';
      rightBody.innerHTML = summaryHtml;
      // Click a row to jump back to that question
      rightBody.querySelectorAll("[data-goto]").forEach(function (row) {
        row.onclick = function () {
          currentIdx = parseInt(row.getAttribute("data-goto"), 10);
          _renderQuestion();
        };
      });
      right.appendChild(rightBody);
      card.appendChild(right);
      bodyEl.appendChild(card);
      return;
    }

    var key = vis[currentIdx];
    var def = defs[key];
    var isLast = currentIdx === vis.length - 1;
    var isFirst = currentIdx === 0;

    bodyEl.innerHTML = "";
    var card = document.createElement("div");
    card.className = "_eli3_bd_guided_card";

    // Left column — split into scrollable question area + pinned nav/progress
    var left = document.createElement("div");
    left.className = "_eli3_bd_guided_left";
    var leftContent = document.createElement("div");
    leftContent.className = "_eli3_bd_guided_left_content";
    var qNum = document.createElement("div");
    qNum.className = "_eli3_bd_guided_qnum";
    qNum.textContent = "Question " + (currentIdx + 1) + " of " + vis.length;
    leftContent.appendChild(qNum);
    // Broadcast the current guided question so the training tour can react to a
    // specific one (e.g. surface the "not every question is in OARS" tip on the
    // payment-terms question). Cross-tool, fire-and-forget.
    try { if (window.eli && eli.bus && eli.bus.emit) eli.bus.emit("build_draft:guided_question", { key: key, idx: currentIdx, total: vis.length }); } catch (_e) {}

    var qTitle = document.createElement("div");
    qTitle.className = "_eli3_bd_guided_qtitle";
    qTitle.textContent = key;
    leftContent.appendChild(qTitle);

    if (def.warning) {
      var warn = document.createElement("div");
      warn.className = "_eli3_bd_guided_warning";
      warn.textContent = "⚠️ " + def.warning;
      leftContent.appendChild(warn);
    }

    if (def.isText) {
      var hint = document.createElement("div");
      hint.className = "_eli3_bd_guided_text_hint";
      hint.textContent = "Free Form Entry — leave as ‘Don’t know’ if not sure.";
      leftContent.appendChild(hint);
      var inp = document.createElement("input");
      inp.type = "text";
      inp.className = "_eli3_bd_guided_text_input";
      inp.value = answers[key] || "";
      inp.placeholder = "Type your answer…";
      inp.oninput = function () {
        answers[key] = inp.value;
        if (inp.value.trim()) touched[key] = true;
        _updateProgress();
        _saveProgress();
      };
      leftContent.appendChild(inp);
    } else {
      var btnGrid = document.createElement("div");
      btnGrid.className = "_eli3_bd_guided_btn_grid";
      (def.options || []).forEach(function (opt) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "_eli3_bd_guided_choice" + (answers[key] === opt ? " _eli3_bd_guided_choice_on" : "");
        btn.textContent = opt;
        btn.onclick = function () {
          answers[key] = opt;
          touched[key] = true;
          btnGrid.querySelectorAll("._eli3_bd_guided_choice").forEach(function (b) {
            b.classList.remove("_eli3_bd_guided_choice_on");
          });
          btn.classList.add("_eli3_bd_guided_choice_on");
          _updateProgress();
          // Re-evaluate deps — selecting this answer may show/hide downstream questions
          // which changes the visible count + progress. Also auto-advance after a short
          // delay so the gold highlight is visible before the card transitions.
          _saveProgress();
          setTimeout(function () {
            currentIdx++;
            _renderQuestion();
          }, 250);
        };
        btnGrid.appendChild(btn);
      });
      // "Other" option — button with underline showing current value; click opens dialog
      if (def.hasOther) {
