    else if (name === "naming") _renderNaming();
    else _renderTemplates();
  }
  root.querySelectorAll("._eli3_bd_tpl_tab").forEach(function (t) {
    t.onclick = function () { _setActiveTab(t.getAttribute("data-tab")); };
  });

  // OTHER tab — behavior toggles that don't belong to naming/templates.
  // Saves immediately on change via onToggleRefreshFields (no save button).
  function _renderOther() {
    body.innerHTML =
      '<label class="_eli3_bd_tpl_check">' +
        '<input type="checkbox" id="_eli3_bd_chk_refresh_fields"' + (refreshFieldsAuto ? " checked" : "") + '>' +
        '<span>🔄 Auto-update document fields after Fill All Fields</span>' +
      '</label>' +
      '<div class="_eli3_bd_tpl_other_note">' +
        'Refreshes every Word field — TOC, page numbers, cross-references, dates — right after Step 2 applies your values (the programmatic version of select-all + F9). ' +
        'Turn it off if a template\'s fields misbehave; you can always refresh manually in Word with select-all + F9.' +
      '</div>' +
      '<label class="_eli3_bd_tpl_check">' +
        '<input type="checkbox" id="_eli3_bd_chk_trim_trailing"' + (trimTrailingBlanks ? " checked" : "") + '>' +
        '<span>🧹 Remove blank pages at the end of the draft</span>' +
      '</label>' +
      '<div class="_eli3_bd_tpl_other_note">' +
        'After Step 1 generates and Step 2 fills, deletes leftover empty paragraphs and page breaks at the end of the document — the cause of trailing pages whose only content is the header/footer. ' +
        'Only the final section is touched, so exhibit and signature-page section breaks are never affected.' +
      '</div>' +
      // Quiet, per-document maintenance action — resets the saved OARS so
      // ELI re-reads it fresh from the doc on reload (handled by oars_loader).
      '<div style="margin-top:18px;border-top:1px solid #eef2f7;padding-top:14px;">' +
        '<button type="button" id="_eli3_bd_clear_oars" style="background:#fff;border:1px solid #e2e8f0;border-radius:6px;padding:7px 12px;font:600 12px/1 \'Inter\',sans-serif;color:#64748b;cursor:pointer;">🔄 Reset OARS data for this document</button>' +
        '<div style="margin-top:8px;color:#94a3b8;font:500 11.5px/1.45 \'Inter\',sans-serif;">Clears the saved OARS so ELI re-reads it fresh from the document on the next reload. Use this if the saved OARS is stale or wrong.</div>' +
      '</div>';
    body.querySelector("#_eli3_bd_chk_refresh_fields").onchange = function () {
      refreshFieldsAuto = this.checked;
      onToggleRefreshFields(this.checked);
    };
    body.querySelector("#_eli3_bd_chk_trim_trailing").onchange = function () {
      trimTrailingBlanks = this.checked;
      onToggleTrimTrailing(this.checked);
    };
    var _clrOars = body.querySelector("#_eli3_bd_clear_oars");
    if (_clrOars) _clrOars.onclick = function () { onClearOars(); };
  }

  function _renderNaming() {
    body.innerHTML =
      '<div class="_eli3_bd_tpl_hint">' +
        '<b>Tokens:</b> <code>[Ref]</code> <code>[Party]</code> <code>[Type]</code> <code>[Date]</code>' +
      '</div>' +
      '<label class="_eli3_bd_tpl_label">Colgate Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_colgate" class="_eli3_bd_tpl_input" value="' + _esc(patterns.colgate) + '">' +
      '<label class="_eli3_bd_tpl_label">Hill\'s Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_hills" class="_eli3_bd_tpl_input" value="' + _esc(patterns.hills) + '">' +
      '<label class="_eli3_bd_tpl_check">' +
        '<input type="checkbox" id="_eli3_bd_chk_highlight"' + (highlightFill ? " checked" : "") + '>' +
        '<span>🖊️ Highlight filled fields</span>' +
      '</label>' +
      '<button class="_eli3_bd_tpl_save_btn" id="_eli3_bd_save_naming">💾 Save Patterns</button>' +
      // Revised-draft naming explainer — documents the entity-aware
      // edits suffix used by the OARS Copy Filename button in the
      // session-feed header. Suffix follows the entity prefix in the
      // pattern above: Colgate → "CP edits", Hill's → "HPN edits".
      '<div class="_eli3_bd_tpl_naming_explain">' +
        '<div class="_eli3_bd_tpl_naming_explain_head">📋 REVISED-DRAFT NAMING</div>' +
        '<div class="_eli3_bd_tpl_naming_explain_body">' +
          'When you open a doc that already has OARS data attached and click <strong>Copy Filename</strong> in the session-feed header, ELI generates a filename using the patterns above but swaps the <code>DRAFT</code> label inside the parenthetical for <code>edits</code> — keeping the entity tag. So <code>(CP DRAFT …)</code> becomes <code>(CP edits …)</code> and <code>(HPN DRAFT …)</code> becomes <code>(HPN edits …)</code>. Dates use <code>m.dd.yy</code> (the month is two digits only for October–December).' +
          '<div class="_eli3_bd_tpl_naming_explain_examples">' +
            '<div><span class="_eli3_bd_naming_eg_label">New draft (Colgate):</span> <code>12345 Acme Corp - MSA <strong>(CP Draft 5.16.26)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">CP edits:</span> <code>12345 Acme Corp - MSA <strong>(CP edits 5.16.26)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">New draft (Hill\'s):</span> <code>12345 Acme Corp - MSA <strong>(HPN Draft 5.16.26)</strong>.docx</code></div>' +
            '<div><span class="_eli3_bd_naming_eg_label">HPN edits:</span> <code>12345 Acme Corp - MSA <strong>(HPN edits 5.16.26)</strong>.docx</code></div>' +
          '</div>' +
          'The signal is clear at a glance: <code>Draft</code> = first version out the door, <code>CP edits</code> / <code>HPN edits</code> = your team\'s response to a counterparty draft. Both honor whatever patterns you set above; only the <code>Draft</code>/<code>edits</code> word differs. If a filename would exceed 92 characters, the third-party name is shortened to fit.' +
        '</div>' +
      '</div>';
    body.querySelector("#_eli3_bd_save_naming").onclick = function () {
      onSavePatterns({
        patterns: {
          colgate: body.querySelector("#_eli3_bd_pat_colgate").value,
          hills: body.querySelector("#_eli3_bd_pat_hills").value,
        },
        highlightFill: body.querySelector("#_eli3_bd_chk_highlight").checked,
      });
    };
  }

  function _renderTemplates() {
    body.innerHTML =
      // 2026-05-26: Agreement Type is a DROPDOWN of existing template
      // types (deduped, alphabetized) + an "+ Add new type…" option.
      // Picking from the list prevents typo drift (e.g. "NDA" vs "Nda"
      // vs "N.D.A" stored as separate types). Selecting "+ Add new"
      // reveals a text input for a brand-new type name.
      // Party Name stays free-text (it's a per-agreement value, not a
      // shared taxonomy — every prior agreement has a unique party).
      (function () {
        // 2026-05-26 fix: the agreement type (NDA, MSA, etc.) lives in
        // `t.name` (case-preserved, e.g. "MSA - Acme Corp") or
        // `t.agreementType` (lowercased fallback). `t.type` holds the
        // CATEGORY ("MasterXML" / "PriorAgreement") and is not useful
        // for this dropdown. Dedup case-insensitively, preserve the
        // first-seen capitalization for display.
        var uniqueTypesMap = {};
        (templates || []).forEach(function (t) {
          if (!t) return;
          var typeName = "";
          if (t.name) {
            // "MSA - Acme Corp" → "MSA"; "MSA" → "MSA"
            typeName = String(t.name).split(/\s+-\s+/)[0].trim();
          }
          if (!typeName && t.agreementType) {
            typeName = String(t.agreementType).trim();
          }
          if (typeName) {
            var k = typeName.toLowerCase();
            if (!uniqueTypesMap[k]) uniqueTypesMap[k] = typeName;
          }
        });
        var sortedTypes = Object.keys(uniqueTypesMap)
          .map(function (k) { return uniqueTypesMap[k]; })
          .sort(function (a, b) { return a.toLowerCase().localeCompare(b.toLowerCase()); });
        var optionsHtml = '<option value="">— Pick existing type —</option>';
        sortedTypes.forEach(function (t) {
          optionsHtml += '<option value="' + _esc(t) + '">' + _esc(t) + '</option>';
        });
        optionsHtml += '<option value="__NEW__">+ Add new type…</option>';

        // 2026-05-27: Party dropdown for Prior/Other Agreement category.
        // Dedup parties across all prior templates, case-insensitive,
        // first-seen capitalization preserved. Same UX as type dropdown:
        // pick existing OR "+ Add new..." to type a fresh party name.
        //
        // Detection: anything that ISN'T a master is treated as a prior
        // here — same convention the grouped render uses. The old check
        // (`type === "PriorAgreement" || /__prior__/i`) missed rows whose
        // type is undefined AND whose id encoded "prioragreement" without
        // the trailing-double-underscore form. E.g.
        // `..._prioragreement__letter_...` contains `__prior` but not
        // `__prior__`, so the strict regex failed.
        function _isMasterLocal(t) {
          return t.type === "MasterXML" || /__masterxml__/i.test(t.id || "");
        }
        var uniquePartiesMap = {};
        (templates || []).forEach(function (t) {
          if (!t) return;
          if (_isMasterLocal(t)) return;
          var partyName = String(t.party || "").trim();
          if (!partyName) return;
          var pk = partyName.toLowerCase();
          if (!uniquePartiesMap[pk]) uniquePartiesMap[pk] = partyName;
        });
        var sortedParties = Object.keys(uniquePartiesMap)
          .map(function (k) { return uniquePartiesMap[k]; })
          .sort(function (a, b) { return a.toLowerCase().localeCompare(b.toLowerCase()); });
        var partyOptionsHtml = '<option value="">— Pick existing party —</option>';
        sortedParties.forEach(function (p) {
          partyOptionsHtml += '<option value="' + _esc(p) + '">' + _esc(p) + '</option>';
        });
        partyOptionsHtml += '<option value="__NEW__">+ Add new party…</option>';

        return '<div class="_eli3_bd_tpl_hint">Save the active document as a reusable template per agreement type.</div>' +
          '<div class="_eli3_bd_tpl_save">' +
            '<div class="_eli3_bd_tpl_save_label">FROM ACTIVE DOCUMENT</div>' +
            '<div class="_eli3_bd_tpl_save_radios">' +
              '<label><input type="radio" name="_eli3_bd_cat" value="MasterXML" checked> 🏗️ Core Template</label>' +
              '<label><input type="radio" name="_eli3_bd_cat" value="PriorAgreement"> 📂 Prior/Other Agreement</label>' +
            '</div>' +
            '<select id="_eli3_bd_tpl_type_select" class="_eli3_bd_tpl_input">' + optionsHtml + '</select>' +
            '<input type="text" id="_eli3_bd_tpl_type_new" class="_eli3_bd_tpl_input _eli3_bd_tpl_hidden" placeholder="New agreement type (e.g. MSA Template)">' +
            '<select id="_eli3_bd_tpl_party_select" class="_eli3_bd_tpl_input _eli3_bd_tpl_hidden">' + partyOptionsHtml + '</select>' +
            '<input type="text" id="_eli3_bd_tpl_party_new" class="_eli3_bd_tpl_input _eli3_bd_tpl_hidden" placeholder="New party name (e.g. Acme Corp)">' +
            '<button class="_eli3_bd_run_all" id="_eli3_bd_tpl_save_btn">💾 Save Active Doc as Template</button>' +
            '<button type="button" class="_eli3_bd_lint_link" id="_eli3_bd_tpl_check_btn">🔍 Check placeholders first</button>' +
            '<div class="_eli3_bd_lint_out" id="_eli3_bd_tpl_check_out"></div>' +
          '</div>';
      })() +
      '<div class="_eli3_bd_tpl_label" style="display:flex;justify-content:space-between;align-items:center;">' +
        '<span>Saved Templates</span>' +
        '<span style="display:inline-flex;gap:4px;align-items:center;font:600 9.5px Inter,sans-serif;color:#64748b;text-transform:none;letter-spacing:0;">' +
          'Sort:' +
          '<button id="_eli3_bd_tpl_sort_az" data-sort="alpha" style="padding:3px 8px;border:1px solid #cbd5e1;background:#fff;cursor:pointer;font:700 9.5px Inter,sans-serif;color:#475569;border-radius:3px;">A–Z</button>' +
          '<button id="_eli3_bd_tpl_sort_date" data-sort="date" style="padding:3px 8px;border:1px solid #cbd5e1;background:#fff;cursor:pointer;font:700 9.5px Inter,sans-serif;color:#475569;border-radius:3px;">Date</button>' +
        '</span>' +
      '</div>' +
      '<div class="_eli3_bd_tpl_list" id="_eli3_bd_tpl_list"></div>' +
      '<div class="_eli3_bd_tpl_bulk">' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_import">⬆️ Import JSON</button>' +
        '<input type="file" id="_eli3_bd_tpl_import_file" accept=".json" hidden>' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_export">⬇️ Export All</button>' +
      '</div>' +
      (onPullLazy
        ? '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_pull" ' +
            'style="width:100%;margin-top:8px;">☁ Pull All Templates from CDN</button>' +
          '<div class="_eli3_bd_tpl_hint" style="margin-top:4px;">' +
            'Downloads every template published to the CDN that isn\'t already on this machine ' +
            '(including lazy templates that don\'t auto-download).</div>'
        : '');

    var partySelectEl = body.querySelector("#_eli3_bd_tpl_party_select");
    var partyNewEl    = body.querySelector("#_eli3_bd_tpl_party_new");
    body.querySelectorAll('input[name="_eli3_bd_cat"]').forEach(function (radio) {
      radio.addEventListener("change", function () {
        var isPrior = this.value === "PriorAgreement";
        // Show the party dropdown when Prior/Other selected. The
        // "+ Add new party…" input stays hidden until that option is picked.
        partySelectEl.classList.toggle("_eli3_bd_tpl_hidden", !isPrior);
        if (!isPrior) {
          partyNewEl.classList.add("_eli3_bd_tpl_hidden");
        } else if (partySelectEl.value === "__NEW__") {
          partyNewEl.classList.remove("_eli3_bd_tpl_hidden");
        }
      });
    });
    // 2026-05-26: dropdown change → show new-type input only when
    // "+ Add new type…" is picked. Auto-focus the input so the user
    // can start typing immediately.
    var typeSelectEl = body.querySelector("#_eli3_bd_tpl_type_select");
    var typeNewEl    = body.querySelector("#_eli3_bd_tpl_type_new");
    typeSelectEl.addEventListener("change", function () {
      var isNew = this.value === "__NEW__";
      typeNewEl.classList.toggle("_eli3_bd_tpl_hidden", !isNew);
      if (isNew) { typeNewEl.value = ""; setTimeout(function () { typeNewEl.focus(); }, 0); }
    });
    // 2026-05-27: party dropdown change → show new-party input only
    // when "+ Add new party…" picked. Same pattern as the type dropdown.
    partySelectEl.addEventListener("change", function () {
      var isNew = this.value === "__NEW__";
      partyNewEl.classList.toggle("_eli3_bd_tpl_hidden", !isNew);
      if (isNew) { partyNewEl.value = ""; setTimeout(function () { partyNewEl.focus(); }, 0); }
    });
    body.querySelector("#_eli3_bd_tpl_save_btn").onclick = function () {
      // Resolve agreement type from EITHER the dropdown (existing type
      // picked) OR the new-type text input (when "+ Add new type…"
      // selected). Empty / placeholder → error.
      var selectVal = typeSelectEl.value;
      var typeVal = "";
      if (selectVal === "__NEW__") {
        typeVal = typeNewEl.value.trim();
      } else if (selectVal) {
        typeVal = selectVal;
      }
      // 2026-05-27: Party also goes through the dropdown / +Add new pattern.
      // Only required when category is PriorAgreement.
      var partySelectVal = partySelectEl.value;
      var partyVal = "";
      if (partySelectVal === "__NEW__") {
        partyVal = partyNewEl.value.trim();
      } else if (partySelectVal) {
        partyVal = partySelectVal;
      }
      var category = body.querySelector('input[name="_eli3_bd_cat"]:checked').value;
      if (!typeVal) {
        if (typeof showToast === "function") {
          showToast(selectVal === "__NEW__"
            ? "Type a name for the new Agreement Type"
            : "Pick an Agreement Type from the dropdown (or '+ Add new type…')", "warn");
        }
        return;
      }
      if (category === "PriorAgreement" && !partyVal) {
        if (typeof showToast === "function") {
          showToast(partySelectVal === "__NEW__"
            ? "Type a name for the new party"
            : "Pick a party from the dropdown (or '+ Add new party…')", "warn");
        }
        return;
      }
      this.disabled = true;
      this.innerText = "⏳ Scanning…";
      onSaveActiveDoc({ type: typeVal, party: partyVal, category: category });
    };
    body.querySelector("#_eli3_bd_tpl_import").onclick = function () {
      body.querySelector("#_eli3_bd_tpl_import_file").click();
    };
    body.querySelector("#_eli3_bd_tpl_import_file").onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (f) onBulkImport(f);
    };
    body.querySelector("#_eli3_bd_tpl_export").onclick = function () {
      var json = JSON.stringify(templates, null, 2);
      try {
        navigator.clipboard.writeText(json);
        if (typeof showToast === "function") showToast("📋 " + templates.length + " templates copied to clipboard", "ok");
      } catch (err) {
        if (typeof showToast === "function") showToast("Copy failed: " + (err && err.message), "err");
      }
    };
    var pullBtn = body.querySelector("#_eli3_bd_tpl_pull");
    if (pullBtn && onPullLazy) {
      pullBtn.onclick = function () {
        pullBtn.disabled = true;
        var orig = pullBtn.textContent;
        pullBtn.textContent = "☁ Pulling…";
