    if (_dirRef) _dirRef.textContent = refInp.value.trim() || "___";
    if (_dirParty) _dirParty.textContent = partyInp.value.trim() || "___";
  }

  typeSel.onchange = function () {
    typeManual.classList.toggle("_eli3_bd_save_hidden", typeSel.value !== "Other");
    _updatePreview();
  };
  [entitySel, typeManual, partyInp, refInp].forEach(function (el) {
    el.addEventListener("input", _updatePreview);
    el.addEventListener("change", _updatePreview);
  });
  if (execChk) execChk.addEventListener("change", _updatePreview);
  _updatePreview();

  // Copy-to-clipboard with success acknowledgement. Falls back to a
  // selection-based execCommand("copy") on browsers where the async
  // clipboard API isn't available (Script Lab iframe quirks).
  function _copyFilename(showAck) {
    var name = _genName();
    var ackEl = root.querySelector("#_eli3_bd_save_copy_ack");
    function _onCopied() {
      // Report the copy back so the audit can mark the save step — in this
      // copy-paste flow, copying the filename IS the user's save action.
      try { if (opts && typeof opts.onCopyName === "function") opts.onCopyName({ filename: name }); } catch (_e) {}
      if (!showAck || !ackEl) return;
      ackEl.style.display = "block";
      setTimeout(function () { if (ackEl) ackEl.style.display = "none"; }, 4000);
    }
    if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      return navigator.clipboard.writeText(name).then(_onCopied).catch(function () {
        _copyViaSelection(name, _onCopied);
      });
    }
    _copyViaSelection(name, _onCopied);
    return Promise.resolve();
  }
  function _copyViaSelection(text, done) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (_e) {}
    document.body.removeChild(ta);
    if (typeof done === "function") done();
  }
  // Click the filename block itself to copy (large target).
  var fnValueEl = root.querySelector("#_eli3_bd_save_preview");
  if (fnValueEl) fnValueEl.onclick = function () {
    // Visually-select the text first (matches the "click to select"
    // tooltip + works as a fallback if clipboard write fails).
    var range = document.createRange();
    range.selectNodeContents(fnValueEl);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    _copyFilename(true);
  };
  var copyBtn = root.querySelector("#_eli3_bd_save_copy");
  if (copyBtn) copyBtn.onclick = function () { _copyFilename(true); };

  // Primary action — copy + continue to email composer. Preserves the
  // formData hand-off (the email composer reads entity/type/party to
  // seed subject + body), just skips the .docx-write step.
  root.querySelector("#_eli3_bd_save_btn").onclick = function () {
    _copyFilename(true);
    // Brief delay so the user sees the "✓ Copied" ack before the
    // panel transitions out into the email step.
    setTimeout(function () {
      onSkip();  // → _runStep5Email — uses same hand-off as Skip path
    }, 300);
  };
  root.querySelector("#_eli3_bd_save_skip").onclick = onSkip;

  mount.appendChild(root);
}

view.renderStepStub:
function renderStepStub(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var step = opts.step || {};
  var onBack = opts.onBack || function () {};
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back" title="Back">←</button>' +
      '<div class="_eli3_bd_title">' + (step.icon || "🛠️") + ' ' + (step.label || "Step") + '</div>' +
    '</div>' +
    '<div class="_eli3_bd_step_body">' +
      '<div class="_eli3_bd_step_pending">' +
        '<div class="_eli3_bd_step_pending_icon">🛠️</div>' +
        '<div class="_eli3_bd_step_pending_title">' + (step.label || "Step") + ' — pending v3 migration</div>' +
        '<div class="_eli3_bd_step_pending_desc">' +
          'This wizard step still runs in v2 mode. Migration to v3 lands once the engine ' +
          'logic is ported. For now, use Templates or Run All to invoke the v2 wizard.' +
        '</div>' +
      '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  // Magic-string constants — single source of truth across this tool.
  var SETTINGS_NAME = "AgreementDataName";
  var SETTINGS_TYPE = "AgreementDataType";
  var SETTINGS_DETAILS = "AgreementDataDetails";
  var BUS_OARS_FILE = "oars:file_selected";
  var BUS_OARS_CLEARED = "oars:cleared";
  var BUS_OARS_DETECTED = "oars:detected";
  var HF_TYPES = ["Primary", "FirstPage", "EvenPages"];
  var STEP2_APPLY_BATCH = 4; // keys per runRaw to keep under 100ms.

  // Wizard mode flag: when true, Step 1 → Step 2 → preSave → Step 3
  // chain auto-advances. Toggled by Run-All; cleared after Step 3 fires.
  var _wizardMode = false;

  // Kernel guarantees eli.events; if it's missing the kernel itself is
  // broken — fail loudly rather than paper over with a no-op shim.
  if (!eli.events || !eli.events.guard || !eli.events.safeAsync) {
    if (eli.log) eli.log.event("tool", "build_draft_missing_events", {});
    if (typeof showToast === "function") showToast("Build Draft failed: kernel events missing", "err");
    return;
  }
  var bundle = eli.tools._loaded["build_draft"];
  if (!bundle) return;
  var engineFns = bundle._eliEngineFns || {};
  var viewFns = bundle._eliViewFns || {};
  var analyze = engineFns.analyze;
  var evalLogicCondition = engineFns.evalLogicCondition;
  var extractTemplatePlaceholders = engineFns.extractTemplatePlaceholders;
  var renderHub = viewFns.renderHub;
  var renderStepStub = viewFns.renderStepStub;
  var renderBracketCleaner = viewFns.renderBracketCleaner;
  var renderSowHelper = viewFns.renderSowHelper;
  var renderLogicForm = viewFns.renderLogicForm;
  var renderGuidedLogicForm = viewFns.renderGuidedLogicForm;
  var renderTemplateFillForm = viewFns.renderTemplateFillForm;
  var renderGuidedFillForm = viewFns.renderGuidedFillForm;
  var buildOarsSummarizeBar = viewFns.buildOarsSummarizeBar;
  var renderTemplatesView = viewFns.renderTemplatesView;
  var renderSavePanel = viewFns.renderSavePanel;
  if (!analyze || !renderHub) {
    eli.log.event("tool", "build_draft_load_failed", { hasEngine: !!analyze, hasView: !!renderHub });
    return;
  }

  var providers = { host: eli.host, ai: eli.ai };

  // ─── Multi-line fill insertion (2026-05-27) ──────────────────────────
  // Step 2 fill values can contain newlines (OARS multi-line fields,
  // user-typed bullets, etc.). Default insertText collapses to single
  // line. _bdInsertText uses insertHtml with <br> soft line breaks for
  // multi-line values — proved as method 4 in inserter_lab (single
  // paragraph, no autoformat triggers, inherits surrounding formatting).
  // Kill switch: build_draft.multilineInsert (default ON). Flip OFF in
  // user settings to fall back to single-line insertText for every fill.
  try {
    eli.settings.register("build_draft.multilineInsert", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftMultilineInsert" },
      adminPushable: true,
      describe: "Build Draft: render multi-line fill values as <br> soft breaks (off = single-line insertText fallback)",
    });
  } catch (_e) {}
  // Pre-insert host-style normalization (2026-06-12). insertOoxml keeps
  // the HOST document's style table and Word resolves style-name
  // collisions in the destination's favor — so an OARS document whose
  // Normal / List Paragraph deviate from factory reformats every
  // template loaded into it (templates render fine on blank docs because
  // blank docs carry factory styles; proven by the MSA-OARS-into-SA-
  // template experiment). Resetting those styles to factory BEFORE the
  // insert reproduces the blank-doc condition for any host. Unlike the
  // reverted Phase D repair (post-insert per-paragraph fixes that
  // over-corrected), this touches only the style table.
  try {
    eli.settings.register("build_draft.normalize_host_styles", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "bdNormalizeHostStyles" },
      adminPushable: true,
      describe: "Build Draft: reset the host document's Normal/List Paragraph styles to factory before template load (stops OARS-document styles reformatting the template)",
    });
  } catch (_e) {}
  function _normalizeHostStylesEnabled() {
    try { return eli.settings.get("build_draft.normalize_host_styles") !== false; }
    catch (_e) { return true; }
  }
  // Custom-style isolation (2026-06-12). Word maps inserted content to
  // host styles BY NAME — templates and OARS exports both descend from
  // Colgate house styles, so they share custom style names ("Colgate
  // H2", "...JAIN HEADING 3 + 11pt Char") with DIFFERENT definitions,
  // and the host's (e.g. bold) version hijacks every span bound to it.
  // Renaming the template's custom styles (Eli-prefixed id + name) and
  // rewriting their references makes every name unique → Word imports
  // the template's own definitions verbatim. Built-ins (Normal, Heading
  // 1…) are left alone — those are handled by _normalizeHostStyles.
  try {
    eli.settings.register("build_draft.isolate_template_styles", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "bdIsolateTemplateStyles" },
      adminPushable: true,
      describe: "Build Draft: rename the template's custom styles on load so host-document styles with the same name (OARS exports) can't hijack their formatting",
    });
  } catch (_e) {}
  function _isolateStylesEnabled() {
