    catch (_e) { return true; }
  }
  function _isolateTemplateStyles(ooxml) {
    var s = String(ooxml || "");
    if (!s || s.indexOf('w:customStyle="1"') === -1) return ooxml;
    // Pass 1 — walk style definitions: collect custom styleIds and
    // prefix their display names ("Eli " + name). Names live only in
    // the definitions; runtime references use ids.
    var ids = [];
    s = s.replace(/<w:style ([^>]*)>([\s\S]*?)<\/w:style>/g, function (whole, attrs, body) {
      if (attrs.indexOf('w:customStyle="1"') === -1) return whole;
      var idm = attrs.match(/w:styleId="([^"]+)"/);
      if (!idm || idm[1].indexOf("Eli") === 0) return whole; // idempotent
      ids.push(idm[1]);
