      if (!dd) return null;
      var out = { spaceAfter: 0, lineSpacing: 12, alignment: "Left" };
      function _pull(block) {
        var fonts = block.match(/<w:rFonts[^>]*w:ascii="([^"]+)"/);
        if (fonts) out.fontName = fonts[1];
        var sz = block.match(/<w:sz w:val="(\d+)"/);
        if (sz) out.fontSize = parseInt(sz[1], 10) / 2;
        var sp = block.match(/<w:spacing([^>]*)\/>/);
