      if (normal) _pull(normal[0]);
      return out;
    } catch (_e) { return null; }
  }
  // Fail-open everywhere: styles API missing (needs WordApi 1.5), style
  // not found, or any setter throwing → skip silently, prior behavior.
  function _normalizeHostStyles(templateOoxml) {
    if (!_normalizeHostStylesEnabled()) return Promise.resolve("off");
    var base = _deriveTemplateBaseline(templateOoxml);
    return eli.host.runRaw("build_draft:normalize_host_styles", function (context) {
      var doc = context.document;
      if (typeof doc.getStyles !== "function") return Promise.resolve("unsupported");
      var styles = doc.getStyles();
