      // the host's empty/deviant Normal stops falling through to its
      // docDefaults — e.g. OARS exports carry after=200/line=276 there).
      // Factory constants only as fallback.
      var normalSpec = base
        ? { font: { name: base.fontName || "Calibri", size: base.fontSize || 11, bold: false, italic: false, color: "#000000" },
            para: { lineSpacing: base.lineSpacing, spaceAfter: base.spaceAfter, spaceBefore: 0,
                    leftIndent: 0, rightIndent: 0, firstLineIndent: 0, alignment: base.alignment } }
        : { font: { name: "Calibri", size: 11, bold: false, italic: false, color: "#000000" },
            para: { lineSpacing: 12.95, spaceAfter: 8, spaceBefore: 0, leftIndent: 0, rightIndent: 0, firstLineIndent: 0, alignment: "Left" } };
      var targets = [
        { name: "Normal", font: normalSpec.font, para: normalSpec.para },
        { name: "List Paragraph",
          font: null,
          para: { leftIndent: 36, spaceBefore: 0, firstLineIndent: 0 } },
      ];
