      // styles (the JAIN/Colgate family) are basedOn these, so a host
      // whose Heading 2 is bold leaks bold into every span riding those
      // chains even after custom-style isolation. Factory headings are
      // NOT bold; reset only the bold/italic toggles (fonts and sizes
      // are owned by the template's own style definitions).
      for (var hl = 1; hl <= 6; hl++) {
        targets.push({ name: "Heading " + hl, font: { bold: false, italic: false }, para: null });
