      });
    }).then(function (r) {
      eli.log.event("tool", "build_draft_styles_normalized", {
        result: String(r),
        derived: !!base,
        lineSpacing: base ? base.lineSpacing : null,
        spaceAfter: base ? base.spaceAfter : null,
        font: base ? base.fontName : null,
      });
      return r;
    }).catch(function (e) {
      eli.log.event("tool", "build_draft_styles_normalize_failed", { msg: e && e.message });
      return null;
    });
  }
  // Review-Changes nav: drop a bookmark on every body fill so the
  // post-fill dialog can walk the user through them in document order.
  // Bookmarks are session-prefixed so multiple builds in the same doc
