      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftRefreshFieldsAfterStep2" },
      adminPushable: true,
      describe: "Build Draft: auto-refresh all Word fields (TOC, page numbers, cross-refs, etc.) after Step 2 fill (toggle in Build Draft Settings > Other)",
    });
  } catch (_e) {}
  // Trailing blank-page cleanup after Step 1 / Step 2 — see
  // _trimTrailingBlanks. Toggle lives in Build Draft Settings → OTHER.
  try {
    eli.settings.register("build_draft.trimTrailingBlanks", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftTrimTrailingBlanks" },
      adminPushable: true,
      describe: "Build Draft: delete blank paragraphs at the end of the draft (removes empty last pages) after Step 1/Step 2 (toggle in Build Draft Settings > Other)",
    });
  } catch (_e) {}
