  // loading the detected template (lets user confirm / pick different /
  // skip). OFF: silent auto-load (legacy behavior). Flip OFF if you want
  // ELI to load templates without asking on every OARS document.
  try {
    eli.settings.register("build_draft.confirmOarsAutoLoad", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftConfirmOarsAutoLoad" },
      adminPushable: true,
      describe: "Build Draft: show confirmation dialog when OARS detection auto-matches a template (off = silent auto-load)",
    });
  } catch (_e) {}
