      default: false,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftShareStep2FillsToCdn" },
      adminPushable: true,
      describe: "Build Draft audit: upload Step 2 fill values (third-party names, amounts) to the shared CDN audit. OFF = fills stay local-only; metadata + Step 1 choices still upload. Admin enables per person.",
    });
  } catch (_e) {}
