    eli.settings.register("build_draft.requireAllSteps", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftRequireAllSteps" },
      adminPushable: true,
      describe: "Build Draft: warn before Save/Send if Logic, Fill, or Error Review wasn't completed (off = no warning). Only applicable steps are required.",
    });
  } catch (_e) {}
  // Guided mode for Step 1 logic — one question at a time with button
  // choices (left) and OARS/guidance context (right) instead of the
  // all-at-once dropdown form. Premium step-by-step UX.
  try {
    eli.settings.register("build_draft.guidedMode", {
      default: true,
      type: "boolean",
      storage: { type: "ls_blob_field", key: "eli_user_settings", field: "buildDraftGuidedMode" },
      adminPushable: true,
      describe: "Build Draft: step-by-step guided mode for Step 1 logic (one question at a time with button choices + OARS context). Off = classic all-at-once dropdown form.",
    });
  } catch (_e) {}
  // Filename patterns — admin-pushable so a single canonical naming
  // convention can be enforced fleet-wide via admin-overrides.json.
  // Tokens: [Ref] [Party] [Type] [Date]. Stored as flat top-level fields
  // on eli_user_settings (the settings registry doesn't support nested
