  // captured template. Returns a Promise resolving to the resolved
  // OOXML (with &[…] boundaries consumed + #[…] clause refs replaced).
  // Uses DOMParser for namespace-correct XML manipulation. If parsing
  // fails (or DOMParser unavailable), returns the input unchanged so
  // the load can proceed — fail-open, never block.
  function _resolveSkeleton(bodyOoxml, detectedType, opts) {
    opts = opts || {};
    if (typeof DOMParser === "undefined") return Promise.resolve(bodyOoxml);
    var parser, xmlDoc;
    try {
      parser = new DOMParser();
      xmlDoc = parser.parseFromString(bodyOoxml, "text/xml");
      if (xmlDoc.getElementsByTagName("parsererror").length) {
        eli.log.event("tool", "build_draft_skeleton_xml_parse_failed", {});
        return Promise.resolve(bodyOoxml);
      }
    } catch (_e) {
      return Promise.resolve(bodyOoxml);
    }
    var W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
