            '<button type="button" onclick="window._bdReviewPrev()" ' +
              'style="background:linear-gradient(180deg,#fafaf8,#e9e6da);border:1px solid #c4bea8;border-radius:6px;padding:4px 12px;font-size:16px;cursor:pointer;color:#3a3528;" ' +
