              '<div id="_bd_review_key" style="font-family:Consolas,monospace;font-size:13px;color:#1d3a8a;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + firstKey + '</div>' +
              '<div id="_bd_review_val" style="font-size:12px;color:#3a3528;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;">' + firstVal + '</div>' +
            '</div>' +
