  // Cleanup pass for $![...] payment-trigger tags. Body-only (these
  // never live in headers/footers).
  function _step2_cleanupTags(tagsToKill) {
    return eli.host.runRaw("build_draft:step2_cleanup", function (context) {
      var body = context.document.body;
      var uniq = tagsToKill.filter(function (v, i, a) { return a.indexOf(v) === i; });
      var chain = Promise.resolve();
      uniq.forEach(function (tag) {
        chain = chain.then(function () {
          var r = body.search(tag, { matchCase: false, matchWildcards: false });
          r.load("items");
          return context.sync().then(function () {
            for (var k = r.items.length - 1; k >= 0; k--) {
              try { r.items[k].delete(); }
              catch (e) { eli.log.event("tool", "build_draft_cleanup_delete_skip", { msg: e && e.message }); }
            }
          });
        });
      });
      return chain;
    });
  }

  // Render Step 1 panel directly (used by reminder dialog fallback).
  function _renderLogicPanel() {
    if (!renderLogicForm) { showToast("Logic form not loaded.", "err"); return; }
    eli.events.safeAsync(_scanDocForOars(), "build_draft.oars_scan_logic")
      .then(function (scan) {
        return eli.events.safeAsync(analyze({
          bodyText: (scan && scan.bodyText) || "",
          headerText: (scan && scan.headerText) || "",
          footerFile: _footerFile,
        }, providers), "build_draft.analyze_logic");
      })
      .then(function (result) {
        if (!result) return;
        // Load IDB-backed guided progress — per-document ring, fallback for doc settings
        var _idbProgPromise;
        try { _idbProgPromise = eli.storage.get("config", "_bd_guided_ring"); } catch (_e) { _idbProgPromise = Promise.resolve(null); }
        return (_idbProgPromise || Promise.resolve(null)).then(function (_idbRow) {
        var _idbProgress = null;
        try {
          var _docUrl = Office.context.document.url || "";
          var ring = (_idbRow && Array.isArray(_idbRow.value)) ? _idbRow.value : [];
          var match = ring.filter(function (e) { return e.docId === _docUrl; });
          if (match.length) _idbProgress = match[0].progress;
        } catch (_e) {}
        var mount = document.getElementById("_eli3_dashboard_root");
        var _useGuided = false;
        try { _useGuided = eli.settings.get("build_draft.guidedMode") === true; } catch (_e) {}
        var _logicRenderer = (_useGuided && renderGuidedLogicForm) ? renderGuidedLogicForm : renderLogicForm;
        var _guidedActivityId = null;
        // Store defs so _step1a_executePlans can pass them to evalLogicCondition
        // for "Other" matching in IF conditions
        _bdCurrentLogicDefs = (result.logicDefs && result.logicDefs.defs) || {};
        var _guidedDocTitle = (result.logicDefs && result.logicDefs.title) || (result.detectedType || "Document Builder");
        _logicRenderer({
          mount: mount,
          idbProgress: _idbProgress,
          defs: (result.logicDefs && result.logicDefs.defs) || {},
          deps: (result.logicDefs && result.logicDefs.deps) || {},
          title: _guidedDocTitle,
          titleGuidance: (result.logicDefs && result.logicDefs.titleGuidance) || [],
          evalCondition: evalLogicCondition,
          summarizeFactory: (buildOarsSummarizeBar
            ? function () { return buildOarsSummarizeBar({ onSummarize: _summarizeOarsAgreement }); }
            : null),
          oarsFields: (function () {
            try {
              var st = eli.dispatch ? eli.dispatch("oars", "getState") : null;
              if (!st || !st.text) return {};
              var oarsBundle = eli.tools._loaded["oars_loader"];
              var parseFn = oarsBundle && oarsBundle._eliEngineFns && oarsBundle._eliEngineFns.parseOarsFields;
              var extractFn = oarsBundle && oarsBundle._eliEngineFns && oarsBundle._eliEngineFns.extractFieldsFromTablesData;
              if (extractFn && st.tablesData && st.tablesData.length) {
                var f = extractFn(st.tablesData);
                if (f && Object.keys(f).length) return f;
              }
              if (parseFn) return parseFn(st.text) || {};
            } catch (_e) {}
            return {};
          })(),
          oarsTablesData: (function () {
            try {
              var st = eli.dispatch ? eli.dispatch("oars", "getState") : null;
              return (st && st.tablesData && st.tablesData.length) ? st.tablesData : [];
            } catch (_e) { return []; }
          })(),
          onBack: function () { _show({}); },
          onScanForOars: function () {
            if (eli.bus) eli.bus.emit(BUS_OARS_DETECTED, {});
            else _show({});
          },
          onProgress: function (info) {
            if (!_useGuided) return;
            // IDB backup of guided progress — per-document ring, last 10
            try {
              var _docUrl = "";
              try { _docUrl = Office.context.document.url || ""; } catch (_ue) {}
              if (_docUrl) {
                var s = Office.context.document.settings;
                var prog = s.get("BdGuidedProgress");
                if (prog) {
                  eli.storage.get("config", "_bd_guided_ring").then(function (row) {
                    var ring = (row && Array.isArray(row.value)) ? row.value : [];
                    ring = ring.filter(function (e) { return e.docId !== _docUrl; });
                    ring.unshift({ docId: _docUrl, progress: prog, savedAt: Date.now() });
                    if (ring.length > 10) ring.length = 10;
                    eli.storage.put("config", { key: "_bd_guided_ring", value: ring });
                  });
                }
              }
            } catch (_e) {}
            var summ = info.answered + " of " + info.total + " answered";
            if (info.currentKey) summ += " · Q: " + info.currentKey;
            if (!_guidedActivityId && eli.activity && typeof eli.activity.add === "function") {
              try {
                var entry = eli.activity.add({
                  type: "build-draft",
                  icon: "🏗️",
