                  payload: { phase: "step1-guided", title: _guidedDocTitle },
                  restoreChannel: "activity_restore",
                  restoreKey: "build-draft",
                });
                _guidedActivityId = (entry && entry.id) || null;
              } catch (_e) {}
            } else if (_guidedActivityId && eli.activity && typeof eli.activity.update === "function") {
              try {
                eli.activity.update(_guidedActivityId, {
                  summary: summ,
                  payload: { phase: "step1-guided", title: _guidedDocTitle },
                });
              } catch (_e) {}
            }
          },
          onGenerate: eli.events.guard(function (answers, done) {
            // Settle the generation chain into the view's done callback so
            // the working button restores on success, failure, or no-op.
            Promise.resolve(_runStep1Generation(answers)).then(
              function () { if (typeof done === "function") done(); },
              function () { if (typeof done === "function") done(); }
            );
          }, "build_draft.step1_generate"),
          // 2026-05-21: DEF tags with `| guidance:<text>` show a 📘
          // GUIDANCE button next to the question. Click opens a
          // premium dialog showing the guidance text — for longer
          // instructional content that doesn't fit as an inline
          // warning chip.
          onGuidance: eli.events.guard(function (guidanceText, defKey) {
            var body = String(guidanceText || "").trim();
            if (!body) return;
            // Convert plain-text line breaks to <br>, preserve other
            // characters via escape. Two consecutive newlines become a
            // paragraph break.
