          onEmailRequester: _emailRequesterAboutFields,
        });
      }); // close IDB progress .then
      })
      .catch(function (err) {
        eli.log.event("tool", "build_draft_logic_panel_failed", { msg: err && err.message });
        showToast("Logic panel failed: " + (err && err.message), "err");
