  // _openTemplatesPicker — premium nested picker. Folder button in the
  // header opens this; gear/settings still routes to _renderTemplatesPanel.
  // Templates grouped by agreementType. Within each group: MasterXML (core)
  // template first, then PriorAgreement rows nested underneath. Click a row
  // to load the template via the same _loadTemplateToWord flow.
  function _openTemplatesPicker() {
    if (typeof showEliDialog !== "function") {
      // No dialog primitive available — fall back to settings panel.
      _renderTemplatesPanel();
      return;
    }
    eli.events.safeAsync(_bdGetAll(), "build_draft.picker_list")
      .then(function (templates) {
        var all = (templates || []).filter(function (t) {
          // Skip metadata rows (id starts with "_") and rows with no usable identity.
          if (!t || typeof t !== "object") return false;
          if (t.id != null && String(t.id).charAt(0) === "_") return false;
          var hasIdentity = (t.name && String(t.name).trim()) ||
            (t.agreementType && String(t.agreementType).trim()) ||
            (t.id && String(t.id).trim());
          return !!hasIdentity;
        });

        function _isMaster(t) {
          return t.type === "MasterXML" || /__masterxml__/i.test(t.id || "");
        }
        // 2026-05-27: more permissive grouping. Strips " - party" suffix
        // from names (priors are saved as "Type - Party"), then normalizes
        // to lowercase alphanumeric so "Grant Agreement", "grant-agreement",
        // "GrantAgreement", "grant_agreement" all hash to the same group.
        // Was failing because priors with agreementType="" fell back to
        // their full name (including party) and never matched the master.
        function _typeRaw(t) {
          var raw = String(t.agreementType || "").trim();
          if (!raw && t.name) {
            raw = String(t.name).split(/\s+-\s+/)[0].trim();
          }
          return raw || "Other";
        }
        function _typeKey(t) {
          return _typeRaw(t).toLowerCase().replace(/[^a-z0-9]+/g, "") || "other";
        }
        function _typeLabel(t) {
          var s = _typeRaw(t);
          // Title-case for display: "msa template" → "MSA Template"
          return s.replace(/\b\w/g, function (c) { return c.toUpperCase(); });
        }
        function _esc(s) {
          return String(s == null ? "" : s)
            .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
        }
        function _shortDate(raw) {
          if (!raw) return "";
          try {
            var d = new Date(raw);
            if (isNaN(d.getTime())) return "";
            return d.toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric" });
          } catch (_e) { return ""; }
        }

        // Group templates by normalized agreement type.
        var groups = {};
        all.forEach(function (t) {
          var key = _typeKey(t);
          if (!groups[key]) {
            groups[key] = { key: key, label: _typeLabel(t), master: null, priors: [] };
          }
          if (_isMaster(t)) {
            // Prefer the first master encountered; if multiple, the rest
            // become "additional cores" stored in priors so they're still
            // reachable.
            if (!groups[key].master) groups[key].master = t;
            else groups[key].priors.push(t);
          } else {
            groups[key].priors.push(t);
          }
        });
        var groupList = Object.keys(groups).map(function (k) { return groups[k]; });
        groupList.sort(function (a, b) { return a.label.localeCompare(b.label); });
        // Within each group, sort priors by party name (case-insensitive).
        groupList.forEach(function (g) {
          g.priors.sort(function (a, b) {
            var an = String(a.party || a.name || "").toLowerCase();
            var bn = String(b.party || b.name || "").toLowerCase();
            return an.localeCompare(bn);
          });
        });

        // Late-bound reference so row onclick can close the dialog even
        // though _makeRow is invoked during initial render (before
        // showEliDialog returns the overlay below).
        var overlayRef = { el: null };

        var body = document.createElement("div");
        body.className = "_eli3_bd_picker";
        body.style.cssText = "display:flex;flex-direction:column;gap:10px;font-family:Inter,'Segoe UI',system-ui,sans-serif;";

        if (!groupList.length) {
          body.innerHTML =
            '<div style="padding:32px 18px;text-align:center;color:#64748b;font-size:13px;">' +
              '<div style="font-size:36px;margin-bottom:8px;opacity:0.6;">📂</div>' +
              '<div style="font-weight:600;color:#1e293b;margin-bottom:4px;">No templates yet</div>' +
              '<div>Save the current document as a template, or wait for a colleague to publish one.</div>' +
            '</div>';
        } else {
          // Search bar — useful once there are more than a handful.
          var searchHtml =
            '<div style="position:relative;flex:0 0 auto;">' +
              '<input id="_eli3_bd_picker_search" type="text" placeholder="Filter templates…" ' +
                'style="width:100%;padding:8px 10px 8px 30px;border:1px solid #cbd5e1;border-radius:6px;font:13px Inter,sans-serif;background:#fff;box-sizing:border-box;">' +
              '<span style="position:absolute;left:9px;top:50%;transform:translateY(-50%);font-size:13px;color:#94a3b8;pointer-events:none;">🔎</span>' +
            '</div>';
          body.insertAdjacentHTML("beforeend", searchHtml);

          var listEl = document.createElement("div");
          listEl.id = "_eli3_bd_picker_list";
          listEl.style.cssText = "display:flex;flex-direction:column;gap:14px;flex:1 1 auto;min-height:0;overflow-y:auto;padding-right:4px;";
          body.appendChild(listEl);

          function _renderGroups(filterText) {
            var q = String(filterText || "").trim().toLowerCase();
            listEl.innerHTML = "";
            var shown = 0;
            groupList.forEach(function (g) {
              // 2026-05-27: picker now shows CORE templates only. Priors
              // moved behind a per-group button that opens a sub-dialog.
              // Filter logic: group matches if label matches OR the master
              // matches OR any prior matches by name/party/agreementType.
              function _match(t) {
                if (!q) return true;
                var hay = ((t.name || "") + " " + (t.party || "") + " " + (t.agreementType || "")).toLowerCase();
                return hay.indexOf(q) !== -1;
              }
              var groupMatches = !q || g.label.toLowerCase().indexOf(q) !== -1;
              var visiblePriors = g.priors.filter(_match);
              var masterMatches = g.master && (groupMatches || _match(g.master));
              if (!masterMatches && !visiblePriors.length && !groupMatches) return;
              shown++;

              var groupEl = document.createElement("div");
              groupEl.style.cssText =
                "border:1px solid #e2e8f0;border-radius:8px;background:#fff;overflow:hidden;" +
                "box-shadow:0 1px 2px rgba(15,23,42,0.04);";

              // Group header — type label + per-group Prior/Other button.
              var hdr = document.createElement("div");
              hdr.style.cssText =
                "padding:10px 14px;background:linear-gradient(180deg,#f8fafc,#f1f5f9);" +
                "border-bottom:1px solid #e2e8f0;font:700 11px Inter,sans-serif;" +
                "color:#0f172a;text-transform:uppercase;letter-spacing:0.6px;" +
                "display:flex;align-items:center;justify-content:space-between;gap:10px;";
              var totalPriorCount = (g.priors || []).length;
              // Build header as: [label] [Prior/Other button if any] [CORE badge]
              var labelSpan = document.createElement("span");
              labelSpan.style.cssText = "flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;";
              labelSpan.textContent = g.label;
              hdr.appendChild(labelSpan);

              // Prior/Other Agreements button — sits LEFT of the CORE badge
              // so the user can glance at the badge as the rightmost anchor.
              if (totalPriorCount) {
                var priorBtn = document.createElement("button");
                priorBtn.type = "button";
                // Gold-accented chip so it pops as the alternative-path
                // CTA next to the muted CORE badge. Project accent is
                // #c9a227 (CLAUDE.md "three colors per surface").
                priorBtn.style.cssText =
                  "flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;" +
                  "padding:5px 12px;border:1px solid #c9a227;" +
                  "background:linear-gradient(180deg,#fdf6dc,#f0e2a8);" +
