  function _pickerLoadTemplate(tpl) {
    if (!tpl || !tpl.content) { showToast("Template has no content.", "err"); return; }
    showToast("⏳ Loading " + (tpl.name || "template") + "…", "info");
    if (tpl.agreementType) _setSkeletonVariant(tpl.agreementType);
    // 2026-05-25: stash active draft meta so Step 2 Apply can emit
    // the draft:created bus event with proper agreementType + templateId.
    // Reset _bdCompleted.templates so the new draft session counts as
    // a separate built draft (otherwise switching templates mid-session
    // silently drops the new build from telemetry).
    try {
      window._bdActiveDraftMeta = {
        draftType: tpl.agreementType || tpl.draftType || tpl.type || null,
        templateId: tpl.id || null,
        templateName: tpl.name || null,
        isCustomTemplate: !!tpl.userCustomized,
      };
      // Audit: OPEN the run here, at template load — not in Step 1 generation.
      // Drafts whose template has no {{DEF}} logic skip Step 1 entirely, so a
      // runId created only in _runStep1Generation would never exist and the
      // Step 3/4 bumps (which early-return on a missing runId) would no-op,
      // leaving the run stuck at "Step 2." Seeding here guarantees every
      // template load is one trackable run from step 1 → 4.
      try {
        var _adm0 = window._bdActiveDraftMeta;
