      // (not just templates) so the hub doesn't carry a prior run's progress.
      // The meta object was just replaced above, so step times/answers are
      // already clean. Also allow hydration to re-run for the new context.
      if (_bdCompleted) { _bdCompleted.logic = false; _bdCompleted.templates = false; _bdCompleted.error_review = false; _bdCompleted.save = false; }
      _bdHydrated = true; // fresh build is authoritative; don't hydrate over it
