              // existing row.
              if (existing) {
                if (existing.publishedAt != null) rec.publishedAt = existing.publishedAt;
                if (existing.publishedSize != null) rec.publishedSize = existing.publishedSize;
                if (existing.core != null) rec.core = existing.core;
                if (existing.defaultForType != null) rec.defaultForType = existing.defaultForType;
                if (Array.isArray(existing.audienceEmails)) rec.audienceEmails = existing.audienceEmails;
                if (Array.isArray(existing.audienceGroups)) rec.audienceGroups = existing.audienceGroups;
                if (Array.isArray(existing.aliases)) rec.aliases = existing.aliases;
                if (existing.cachedFromCdn != null) rec.cachedFromCdn = existing.cachedFromCdn;
              }
              // Store the new content hash so the next upload can compare
              rec._contentHash = _newHash;
              return _bdPut(rec);
              }); // close _guardGate.then
            }).then(function () {
              showToast("✅ Template Saved", "ok");
              _renderTemplatesPanel();
            });
          }).catch(function (err) {
            if (err && err.message === "Upload cancelled by user") {
              showToast("Upload cancelled.", "info");
              return;
            }
            eli.log.event("tool", "build_draft_tpl_capture_failed", { msg: err && err.message });
            showToast("Capture failed: " + (err && err.message), "err");
            _renderTemplatesPanel();
          });
        }, "build_draft.tpl_save_active"),
        // Lint the OPEN document — no save, no library write. Rides the scan
        // Step 2 already runs, so it costs one existing pass and no AI.
        onCheckActiveDoc: function () {
          return _scanForFill().then(function (text) {
            var phs = extractTemplatePlaceholders(text);
            if (!phs.length) throw new Error("No placeholders found in the active document.");
            return _bdLintPlaceholders(phs);
          });
        },
        // Lint a STORED template — never touches Word.
        onCheckTemplate: function (tpl) {
          if (!tpl || !tpl.content) return Promise.reject(new Error("Template has no content."));
          var phs = extractTemplatePlaceholders(String(tpl.content));
          if (!phs.length) throw new Error("No placeholders in this template.");
          return Promise.resolve(_bdLintPlaceholders(phs));
        },
        onLoadTemplate: eli.events.guard(function (tpl) {
          if (!tpl || !tpl.content) { showToast("Template has no content.", "err"); return; }
          // Destructive — loading a template replaces the entire active
          // document. Confirm first (eli.ui.confirm; native confirm() is
          // blocked in the Script Lab iframe).
          eli.events.safeAsync(eli.ui.confirm({
            title: "Load template into document?",
            message: "Are you sure you want to load \"" + (tpl.name || "this template") +
              "\" into the document? This will REPLACE the current document content.",
            confirmText: "Load Template",
            cancelText: "Cancel",
          }), "build_draft.tpl_load_confirm").then(function (ok) {
            if (!ok) return;
          showToast("⏳ Loading " + (tpl.name || "template") + "…", "info");
          // 2026-05-21: stash the template's saved agreementType so the
          // skeleton resolver can pick the right variant. For non-
          // skeleton templates this is harmless (resolver is a no-op
          // unless &[…] markers are present in the body).
          if (tpl.agreementType) _setSkeletonVariant(tpl.agreementType);
          _loadTemplateToWord(tpl.content)
            .then(function () {
              // 2026-05-19 v8: convert baked-in old party name (from save)
              // into a [[Counterparty Name]] placeholder. Otherwise step 2
              // fill leaves the original drafter's plain-text name in
              // headers, producing "Zymo researchZymoResearch" doubling.
              // Reads tpl.party — empty / legacy templates skip the pass.
              return _scrubOldPartyAsPlaceholder(tpl.party).then(function (n) {
                if (n > 0) {
                  eli.log.event("tool", "build_draft_tpl_load_party_scrubbed", {
                    occurrences: n,
                    oldParty: tpl.party,
                  });
                }
              });
            })
            .then(function () {
              showToast("✅ Template loaded", "ok");
              // Same as auto-launch path: mark as converted so reloads
              // don't re-flash the OARS overlay.
              if (eli.get && typeof eli.get("oars", "setTemplateLoaded") === "function") {
                eli.dispatch("oars", "setTemplateLoaded", true);
              }
            })
            .catch(function (err) {
              eli.log.event("tool", "build_draft_tpl_load_failed", { msg: err && err.message });
              showToast("Load failed: " + (err && err.message), "err");
            });
          }); // end confirm().then
        }, "build_draft.tpl_load"),
        onDeleteTemplate: eli.events.guard(function (tpl) {
          eli.events.safeAsync(eli.ui.confirm({
            title: "Delete template?",
            message: "Delete '" + (tpl.name || "this template") + "'? This cannot be undone.",
          }), "build_draft.tpl_delete_confirm").then(function (ok) {
            if (!ok) return;
            return _bdDelete(tpl.id).then(function () {
              showToast("🗑️ Deleted: " + (tpl.name || tpl.id), "ok");
              _renderTemplatesPanel();
            });
          }).catch(function (err) {
            eli.log.event("tool", "build_draft_tpl_delete_failed", { msg: err && err.message });
          });
        }, "build_draft.tpl_delete"),
        onBulkImport: eli.events.guard(function (file) {
          var reader = new FileReader();
          reader.onload = function () {
            var imported;
            try { imported = JSON.parse(reader.result); }
            catch (e) { showToast("Invalid JSON file", "err"); return; }
            if (!Array.isArray(imported)) { showToast("Expected an array", "err"); return; }
            // 2026-05-19: merge via deterministic id from
            // (agreementType, type, party). Replaces the old "bd_imp_"
            // + timestamp scheme so an imported template that matches
            // an existing one updates in place — and a future admin
            // push of the same template also UPSERTs cleanly. Counts
            // new vs updated based on whether the id was already
            // present in the local store.
            _bdGetAll().then(function (current) {
              var existingIds = {};
              (current || []).forEach(function (item) {
                if (item && item.id) existingIds[item.id] = true;
              });
              var countNew = 0, countUpd = 0;
              var chain = Promise.resolve();
              imported.forEach(function (newItem) {
                var atype = String(newItem.agreementType || "").toLowerCase();
                var ttype = newItem.type || "";
                var party = String(newItem.party || "").trim();
                newItem.agreementType = atype;
                newItem.party = party;
                newItem.id = _bd_templateId(atype, ttype, party);
                if (existingIds[newItem.id]) countUpd++; else countNew++;
                chain = chain.then(function () { return _bdPut(newItem); });
              });
              return chain.then(function () {
                showToast("✅ Import: " + countNew + " new, " + countUpd + " updated", "ok");
                _renderTemplatesPanel();
              });
            });
          };
          reader.readAsText(file);
        }, "build_draft.tpl_import"),
        // 2026-05-29: manual "pull every CDN template not yet local" — incl.
        // lazy templates that never auto-download. Refreshes the manifest,
        // lists what's available, fetches each un-cached id (URL built from
        // the manifest id, so no 404), then re-renders the panel.
        onPullLazy: eli.events.guard(function () {
          showToast("☁ Checking CDN for templates…", "info");
          return eli.dispatch("build_draft", "fetchManifest")
            .then(function () { return eli.dispatch("build_draft", "listAvailableTemplates"); })
            .then(function (list) {
              var missing = (list || []).filter(function (t) { return t && t.fromManifest && !t.cached; });
              if (!missing.length) {
                showToast("✅ All CDN templates already downloaded.", "ok");
                return 0;
              }
              showToast("📥 Downloading " + missing.length + " template" + (missing.length === 1 ? "" : "s") + "…", "info");
              var chain = Promise.resolve();
              var done = 0, failed = 0;
              missing.forEach(function (t) {
                chain = chain.then(function () {
                  return eli.dispatch("build_draft", "fetchTemplate", t.id)
                    .then(function () { done++; })
                    .catch(function (err) {
                      failed++;
                      eli.log.event("tool", "build_draft_pull_lazy_failed", { id: t.id, msg: err && err.message });
                    });
                });
              });
              return chain.then(function () {
                showToast("📥 Downloaded " + done + " template" + (done === 1 ? "" : "s") +
                  (failed ? " (" + failed + " failed)" : "") + ".", failed ? "warn" : "ok");
                return done;
              });
            })
            .then(function () { _renderTemplatesPanel(); })
            .catch(function (err) {
              eli.log.event("tool", "build_draft_pull_lazy_error", { msg: err && err.message });
              showToast("Pull failed: " + (err && err.message || "unknown"), "err");
            });
        }, "build_draft.tpl_pull_lazy"),
      });
    });
  }

  // Step 3 — Error Review. Dispatches to the error_review tool's tile
  // dispatch channel (registered by the error_review bundle); falls back
  // to the v2 global if v3 hasn't loaded the tool yet. Wizard mode ends
  // here — error_review and showSaveAsManager are end-points, not auto-
  // advancing. Mounts a floating "← Build Draft Hub" pill so the user
  // can return without dashboard → tile re-click roundtrip.
  function _runStep3ErrorReview() {
    _wizardMode = false; // wizard chain ends; user owns the flow now
    // Probe existence — error_review's tileHandler is async and returns
    // undefined, so the dispatch return value isn't a reliable signal.
    // eli.get tells us whether the channel is registered without invoking it.
    var hasHandler = !!(eli.get && typeof eli.get("tile", "app_error_review") === "function");
    if (hasHandler) {
      try {
        eli.dispatch("tile", "app_error_review");
        _bdCompleted.error_review = true;
        _bdStampStepTime("errorReview");
        _bdAuditBumpStep(3);
        _mountReturnToHubPill();
      } catch (e) {
        eli.log.event("tool", "build_draft_step3_dispatch_failed", { msg: e && e.message });
        showToast("Error Review failed: " + (e && e.message), "err");
      }
      return;
    }
    if (typeof window.runInteractiveErrorCheck === "function") {
      try {
        window.runInteractiveErrorCheck(function () { _show({}); });
        _bdCompleted.error_review = true;
        _bdStampStepTime("errorReview");
        _bdAuditBumpStep(3);
        _mountReturnToHubPill();
      } catch (e) { showToast("Error Review failed: " + (e && e.message), "err"); }
      return;
    }
    showToast("Error Review tool not installed.", "warn");
  }

  // Floating "← Build Draft Hub" pill, fixed bottom-right. Removed on
  // click + on next render of build_draft hub. Survives dashboard nav
  // until manually dismissed or build_draft is re-entered.
  function _mountReturnToHubPill() {
    _removeReturnToHubPill(); // dedupe
    var pill = document.createElement("button");
    pill.id = "_eli3_bd_return_pill";
    pill.className = "_eli3_bd_return_pill";
    pill.innerHTML = "← Back to Build Draft Hub";
    pill.onclick = function () {
      _removeReturnToHubPill();
      _show({});
    };
    document.body.appendChild(pill);
  }
  function _removeReturnToHubPill() {
    var existing = document.getElementById("_eli3_bd_return_pill");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
  }

  // Step 4 — Save and/or Send. FROM v2 showSaveAsManager (line 18930).
  // Renders prefill form, scans doc with AI in background to fill third-
  // party / ref / type, then saves the .docx via Office.context.document.
  // Falls back to v2 global if the v3 render fn isn't bundled yet.
  // Which required steps (1-3) are still incomplete, given the scan result.
  // A step is required ONLY if it applies to this template: Logic needs
  // {{DEF}} questions; Fill needs placeholders; Error Review always applies.
  // Returns an array of human labels, e.g. ["Error Review"].
  function _bdMissingRequiredSteps(result) {
    var missing = [];
    var defCount = (result && result.logicScan && result.logicScan.counts && result.logicScan.counts.DEF) || 0;
    var fillTotal = (result && result.fillScan && result.fillScan.total) || 0;
    if (defCount > 0 && !_bdCompleted.logic) missing.push("Customize Template");
    if (fillTotal > 0 && !_bdCompleted.templates) missing.push("Fill Fields");
    if (!_bdCompleted.error_review) missing.push("Error Review");
    return missing;
  }
  // Entry to Step 4 with the soft requirement gate. When the setting is ON and
  // applicable steps 1-3 aren't done, warn + let the user continue anyway.
  function _runStep4Gated(result) {
    var enforce = true;
    try { enforce = eli.settings.get("build_draft.requireAllSteps") !== false; } catch (_e) {}
    var missing = enforce ? _bdMissingRequiredSteps(result) : [];
    if (!missing.length) { _runStep4SaveSend(); return; }
    var list = missing.map(function (m) { return "• " + m; }).join("\n");
    eli.events.safeAsync(eli.ui.confirm({
      title: "Finish without completing every step?",
      message: "These required step(s) haven't been completed for this draft:\n\n" + list +
        "\n\nYou can go back and finish them, or continue to Save / Send anyway.",
      confirmText: "Continue anyway",
      cancelText: "Go back",
      variant: "danger",
    }), "build_draft.require_steps_warn").then(function (ok) {
      if (ok) _runStep4SaveSend();
      // Cancel → stay in the hub; user picks the missing step.
    });
  }

  function _runStep4SaveSend() {
    if (!renderSavePanel) {
      if (typeof window.showSaveAsManager === "function") {
        try { window.showSaveAsManager(); return; }
        catch (e) { showToast("Save manager failed: " + (e && e.message), "err"); return; }
      }
      showToast("Save / Send not yet migrated to v3.", "warn");
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");

    // Filename patterns from the settings registry (admin-pushable
    // via admin-overrides.json; user pref fallback; default fallback).
    var patterns = {
      colgate: eli.settings.get("build_draft.fileNamePattern.colgate"),
      hills:   eli.settings.get("build_draft.fileNamePattern.hills"),
    };

    // Pull agreement-type list from IDB (data bundle). Store name is
    // snake_case `agreement_types` (v2 compat — STORE_AGREEMENT_TYPES).
    // Filter out pseudo entries (matches v2 getAgreementTypes line 2992).
    eli.events.safeAsync(eli.storage.getAll("agreement_types"), "build_draft.ag_types").then(function (rows) {
      var agTypes = [];
      var agTypeRows = Array.isArray(rows) ? rows.filter(function (r) { return r && !r.pseudo; }) : [];
      agTypes = agTypeRows
        .map(function (r) { return r.label || r.name || r.id; })
        .filter(Boolean);
      // Render with scanning=true; AI prefill flows in async.
      _renderSavePanelWith({ prefill: {}, agTypes: agTypes, agTypeRows: agTypeRows, patterns: patterns, scanning: true, mount: mount });
      // Kick off prefill scan; re-render on completion with prefill data.
      _runSavePrefillScan().then(function (prefill) {
        _renderSavePanelWith({ prefill: prefill || {}, agTypes: agTypes, agTypeRows: agTypeRows, patterns: patterns, scanning: false, mount: mount });
      }).catch(function (err) {
        eli.log.event("tool", "build_draft_save_prefill_failed", { msg: err && err.message });
        _renderSavePanelWith({ prefill: {}, agTypes: agTypes, agTypeRows: agTypeRows, patterns: patterns, scanning: false, mount: mount });
      });
    });
  }

  function _renderSavePanelWith(state) {
    // Tell the training tour that Step 4's save panel is up (once the scan
    // settles, so the tip doesn't pop over a still-loading panel).
    if (!state.scanning) { try { if (eli.bus && eli.bus.emit) eli.bus.emit("build_draft:step4_shown", {}); } catch (_e) {} }
    renderSavePanel({
      mount: state.mount,
      prefill: state.prefill,
      agTypes: state.agTypes,
      agTypeRows: state.agTypeRows,
      patterns: state.patterns,
      scanning: state.scanning,
      onBack: function () { _show({}); },
      onSettings: function () { _renderTemplatesPanel(); },
      // FROM v2 line 18980 "Skip (Go to Email)" — matches the v2 pattern.
      // Skip-without-save still hands off to the emailer (no formData to
      // seed entity/type, so the composer reads doc-settings prefill).
      onSkip: function () {
        showToast("⏩ Skipping save → opening email", "info");
        _runStep5Email(null);
      },
      // Audit: in the copy-paste save flow, clicking "Copy filename" IS the
      // user's save action (they paste it into Word's native Save As). ELI
      // can't see the disk write, so this is the truest "saved" signal —
      // mark step 4. Fired by renderSavePanel's _copyFilename on success.
      onCopyName: function (info) {
        _bdCompleted.save = true; // hub reads this for the ✓
        try {
          if (typeof _bdAuditEnsureRun === "function") _bdAuditEnsureRun();
          if (window._bdActiveDraftMeta) window._bdActiveDraftMeta.auditNameCopied = true;
          _bdStampStepTime("saved");
          _bdAuditBumpStep(4);
        } catch (_e) {}
        // Version snapshot — same as the legacy _writeBlob path, but
        // triggered by the copy-paste save (the current primary flow).
        try {
          if (eli.get && typeof eli.get("version_history", "snapshot") === "function") {
            var fn = (info && info.filename) || "draft";
            eli.dispatch("version_history", "snapshot", {
              label: "CP Version: " + fn,
            });
          }
        } catch (_snapErr) {}
      },
      onSave: eli.events.guard(function (formData) {
        _runSaveAsDocx(formData);
      }, "build_draft.save"),
    });
  }

  // FROM v2 runAiEmailScanner (line 19980). Three-step prefill ordering,
  // matches v2 exactly:
  //   1. Restore from persisted Office.context.document.settings prefill
  //      (per-doc cache; survives reload, machine, and user). Skipped on
  //      forceFresh.
  //   2. AI-extract from OARS data when loaded (_footerFile.text or
  //      AGREEMENT_DATA-equivalent). OARS is structured + minimal noise →
  //      best signal.
  //   3. Fallback: AI-extract from the Word document body + headers +
  //      footers. Used when no OARS is loaded.
  //
  // Prompt mirrors v2's email-scanner JSON schema so the same payload can
  // feed the email helper later (proceedToEmail). Persists the result back
  // to Office settings so subsequent opens skip steps 2/3.
  function _runSavePrefillScan(opts) {
    opts = opts || {};
    var forceFresh = !!opts.forceFresh;

    // Step 1 — persisted per-doc cache.
    if (!forceFresh) {
      try {
        var docSettings = Office.context.document.settings;
        var cached = docSettings.get("EliEmailerPrefill");
        if (cached && typeof cached === "object") {
          var hasUseful = !!(cached.third_party_entity || cached.contact_email ||
                             cached.requester_email || cached.cp_ref || cached.type);
          if (hasUseful) {
            eli.log.event("tool", "build_draft_save_prefill_doc_cache_hit", {});
            return Promise.resolve(_normalizeAiPrefill(cached));
          }
        }
      } catch (e) {
        // Settings may not be ready in some hosts — fall through to AI.
        eli.log.event("tool", "build_draft_save_prefill_settings_read_failed", { msg: e && e.message });
      }
    }

    var prompt =
      "You are a Senior Legal Assistant.\n" +
      "TASK: Scan the document below to populate metadata for a draft cover-email.\n" +
      "EXTRACT THESE FIELDS:\n" +
      "1. Agreement Type (e.g. NDA, MSA, SOW).\n" +
      "2. Entities: Colgate / Hill's vs The Third Party.\n" +
      "3. Contact Info: primary Third Party Contact (Name & Email) from Notices section or signature block.\n" +
      "4. Requester: Colgate / Hill's employee requesting the agreement (Name & Email).\n" +
      "5. CP Ref #: in headers/footers, look for 'CP Ref', 'Ref #', or codes like 'A-12345'.\n" +
      "RETURN RAW JSON:\n" +
      "{\n" +
      '  "type": "Agreement Type",\n' +
      '  "colgate_entity": "Colgate|Hills",\n' +
      '  "third_party_entity": "Company Name",\n' +
      '  "contact_full_name": "Full Name",\n' +
      '  "contact_email": "email@address.com",\n' +
      '  "requester_name": "Colgate Employee",\n' +
      '  "requester_email": "employee@colpal.com",\n' +
      '  "cp_ref": "A-2025-12345-US"\n' +
      "}\n" +
      "Use empty string for any field not found.\n\n";

    // Step 2 — OARS data (structured, primary). FROM v2 line 20015-20021.
    var oarsPayload = _footerFile;
    if (oarsPayload && (oarsPayload.text || oarsPayload.data)) {
      eli.log.event("tool", "build_draft_save_prefill_from_oars", {
        name: oarsPayload.name, isBase64: !!oarsPayload.isBase64,
      });
      var aiOpts = { maxTokens: 1500 };
      if (oarsPayload.isBase64 && oarsPayload.data && oarsPayload.mime) {
        aiOpts.inlineData = { mimeType: oarsPayload.mime, data: oarsPayload.data };
      }
      var aiPrompt = oarsPayload.isBase64
        ? prompt + "DOCUMENT FILE attached as inline data."
        : prompt + "--- OARS DATA ---\n" + String(oarsPayload.text).substring(0, 500000);
      return eli.events.safeAsync(eli.ai.completeJSON(aiPrompt, null, aiOpts), "build_draft.save_prefill_oars")
        .then(function (json) {
          var normalized = _normalizeAiPrefill(json);
          _persistDocPrefill(normalized);
          return normalized;
        })
        .catch(function (err) {
          eli.log.event("tool", "build_draft_save_prefill_oars_failed", { msg: err && err.message });
          // Fall through to step 3 by returning null; caller retries.
          return _runSavePrefillScanFromDoc(prompt);
        });
    }

    // Step 3 — AI scan of the Word document directly.
    return _runSavePrefillScanFromDoc(prompt);
  }

  // Shared step-3 helper: pull body + headers + footers from the doc and
  // hand them to the AI. FROM v2 runAiEmailScanner else-branch (line 20176).
  function _runSavePrefillScanFromDoc(prompt) {
    return eli.host.runRaw("build_draft:save_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var ranges = [body];
        for (var i = 0; i < sections.items.length; i++) {
          var sec = sections.items[i];
          ["Primary", "FirstPage", "EvenPages"].forEach(function (kind) {
            try { ranges.push(sec.getFooter(kind)); } catch (e) {}
            try { ranges.push(sec.getHeader(kind)); } catch (e) {}
          });
        }
        ranges.forEach(function (r) { try { r.load("text"); } catch (e) {} });
        return context.sync().then(function () {
          var combined = ranges.map(function (r) { return r.text || ""; }).join("\n\n").trim();
          return combined.substring(0, 500000);
        });
      });
    }).then(function (docText) {
      if (!docText) return null;
      return eli.events.safeAsync(
        eli.ai.completeJSON(prompt + "--- DOCUMENT TEXT ---\n" + docText, null, { maxTokens: 1500 }),
        "build_draft.save_prefill_doc"
      ).then(function (json) {
        var normalized = _normalizeAiPrefill(json);
        _persistDocPrefill(normalized);
        return normalized;
      }).catch(function (err) {
        eli.log.event("tool", "build_draft_save_prefill_doc_failed", { msg: err && err.message });
        return null;
      });
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_save_prefill_scan_failed", { msg: err && err.message });
      return null;
    });
  }

  // Normalize AI JSON. v2's prompt returns `colgate_entity` ("Colgate" |
  // "Hills" | "Hill's"); v3's save form binds to `entity` for the dropdown
  // (Colgate|Hills only). Map across.
  function _normalizeAiPrefill(json) {
    if (!json || typeof json !== "object") return null;
    var out = {
      type: json.type || "",
      third_party_entity: json.third_party_entity || "",
      cp_ref: json.cp_ref || "",
      contact_full_name: json.contact_full_name || "",
      contact_email: json.contact_email || "",
      requester_name: json.requester_name || "",
      requester_email: json.requester_email || "",
    };
    var ent = String(json.colgate_entity || json.entity || "").toLowerCase();
    out.entity = ent.indexOf("hill") !== -1 ? "Hills" : (ent ? "Colgate" : "");
    return out;
  }

  // Persist back to Office.context.document.settings so the next open of
  // this same document skips the AI roundtrip. FROM v2 setOpts +
  // settings.saveAsync pattern.
  function _persistDocPrefill(prefill) {
    if (!prefill) return;
    try {
      var s = Office.context.document.settings;
      s.set("EliEmailerPrefill", prefill);
      if (typeof s.saveAsync === "function") {
        s.saveAsync(function (res) {
          if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
            eli.log.event("tool", "build_draft_save_prefill_persist_failed", {
              msg: res.error && res.error.message,
            });
          }
        });
      }
    } catch (e) {
      eli.log.event("tool", "build_draft_save_prefill_persist_threw", { msg: e && e.message });
    }
  }

  // FROM v2 saveFileWithDialog (line 19174). Pulls the doc via
  // Office.context.document.getFileAsync (slice loop) then writes via
  // showSaveFilePicker (modern browsers) or anchor-download fallback.
  //
  // Known Office.js limitation (2026-05-10): Office.context.document
  // .settings (AgreementDataText / Name / Source / BuildDraftTemplateLoaded)
  // live in a host-side cache NOT included in getFileAsync's output.
  // Word only flushes them into the .docx file on a host-initiated save
  // (Ctrl+S, AutoSave). Two pre-flush attempts (Word.run save and
  // settings.saveAsync re-flush) had no effect. Until OARS moves to a
  // custom XML part, the exported .docx won't carry OARS data unless
  // the user manually saves the SOURCE doc first.
  function _runSaveAsDocx(formData) {
    showToast("⏳ Generating .docx…", "info");
    return new Promise(function (resolve, reject) {
      try {
        Office.context.document.getFileAsync(Office.FileType.Compressed, { sliceSize: 65536 }, function (result) {
          if (result.status !== Office.AsyncResultStatus.Succeeded) {
            reject(new Error(result.error && result.error.message || "getFileAsync failed"));
            return;
          }
          var myFile = result.value;
          var sliceCount = myFile.sliceCount;
          var received = 0;
          var docdata = [];
          function _getSlice(i) {
            myFile.getSliceAsync(i, function (sr) {
              if (sr.status !== Office.AsyncResultStatus.Succeeded) {
                myFile.closeAsync();
                reject(new Error("Slice " + i + " failed"));
                return;
              }
              if (sr.value && sr.value.data) {
                var d = sr.value.data;
                docdata = docdata.concat(Array.isArray(d) ? d : Array.from(new Uint8Array(d)));
              }
              received++;
              if (received === sliceCount) {
                myFile.closeAsync();
                var blob = new Blob([new Uint8Array(docdata)], {
                  type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                });
                _writeBlob(blob, formData.filename).then(resolve).catch(reject);
              } else {
                _getSlice(received);
              }
            });
          }
          _getSlice(0);
        });
      } catch (e) { reject(e); }
    }).then(function () {
      _bdCompleted.save = true;
      _bdStampStepTime("saved");
      _bdAuditBumpStep(4);
      showToast("✅ Saved: " + formData.filename, "ok");
      if (eli.activity && eli.activity.add) {
        eli.activity.add({
          type: "build-draft", icon: "💾", label: "Build Draft · Save",
          summary: "Saved " + formData.filename +
            (formData.executionMode ? " (EXECUTION COPY)" : ""),
          payload: {
            filename: formData.filename,
            entity: formData.entity,
            type: formData.type,
            // Execution-mode boolean carried in payload + provenance so
            // a wrong "EXECUTION COPY" file is post-hoc traceable. The
            // for-signature email subject/body swap is also driven by
            // this flag — capturing it on save lets us replay the chain.
            executionMode: !!formData.executionMode,
          },
          provenance: {
            timestamp: Date.now(),
            executionMode: !!formData.executionMode,
          },
        });
      }
      // draftsCreated stat is now incremented at templates-apply (the
      // "build complete" moment in Word). Save-as-docx is an optional
      // export step and shouldn't double-count.
      // Event-based trophy evaluator: Full Portfolio (t176 — drafted all
      // 4 core types: NDA, Service, MSA, SOW).
      try {
        if (eli.trophies && typeof eli.trophies.evaluate === "function") {
          eli.trophies.evaluate("draft_completed", {
            draftType: String(formData.draftType || formData.templateType || formData.type || ""),
          });
        }
      } catch (_) {}
      // FROM v2 line 19121 — createSnapshot after save. Captures the
      // saved-as-draft state to version_history so the user has a
      // recoverable point. No-ops if version_history isn't installed.
      try {
        if (eli.get && typeof eli.get("version_history", "snapshot") === "function") {
          eli.dispatch("version_history", "snapshot", {
            label: "CP Version: " + formData.filename +
              (formData.executionMode ? " [EXECUTION COPY]" : " [Original Version]"),
          });
        }
      } catch (e) {
        eli.log.event("tool", "build_draft_snapshot_failed", { msg: e && e.message });
      }
      // FROM v2 line 19119 — proceedToEmail. Auto-launch the emailer with
      // the same form data the user just confirmed during save. User can
      // hit Home to skip; no forced flow.
      setTimeout(function () { _runStep5Email(formData); }, 600);
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_save_failed", { msg: err && err.message });
      showToast("Save failed: " + (err && err.message), "err");
    });
  }

  // ─── Step 5 — Email composer ─────────────────────────────────────────
  // The composer lives in its own tool now (auto_emailer). Build Draft
  // dispatches into it with the user-confirmed save-form data as a seed.
  // The auto_emailer tool layers Office.context.document.settings prefill
  // (EliEmailerPrefill) on top for any field the seed does not carry —
  // contact name/email, requester, etc.
  //
  // Shape mapping: save panel uses entity (Colgate|Hills); v2 emailer
  // expects colgate_entity (Colgate|Hill's). Map across here so the
  // auto_emailer tool stays v2-compatible.
  function _runStep5Email(seed) {
    // Resume-safe: recover the run from the doc if memory was lost, so the
    // emailer carries the right runId and "Open Gmail draft" stamps step 4
    // on the original record.
    if (typeof _bdAuditEnsureRun === "function") _bdAuditEnsureRun();
    // Always mark dispatches from build_draft as requester-default —
    // the user is sending to the internal requester after generating
    // the draft. Standalone auto_emailer tile defaults to "tp" instead.
    // _dest is a launch-context flag (not a prefill field) and is
    // explicitly excluded from EliEmailerPrefill persistence by the
    // auto_emailer's whitelist.
    // Carry the active build run's audit id so auto_emailer can report
    // "Open Gmail draft" back here as step 4 (sent out). Underscore-prefixed
    // launch flag — auto_emailer reads it from the seed, never persists it.
    var _auditRunId = (window._bdActiveDraftMeta && window._bdActiveDraftMeta.auditRunId) || null;
    var seedShape = seed ? {
      _dest: "req",
      _executionMode: !!seed.executionMode,
      _fromBuildDraft: true,
      _bdAuditRunId: _auditRunId,
      colgate_entity: seed.entity === "Hills" ? "Hill's" : (seed.entity === "CPSH" ? "CPSH" : seed.entity),
      entity: seed.entity,
      type: seed.type,
      agreement_type: seed.type,
      third_party_entity: seed.third_party_entity || "",
      cp_ref: seed.cp_ref || "",
    } : { _dest: "req", _fromBuildDraft: true, _bdAuditRunId: _auditRunId };
    var hasHandler = !!(eli.get && typeof eli.get("auto_emailer", "compose") === "function");
    if (!hasHandler) {
      showToast("Auto Emailer not installed.", "warn");
      return;
    }
    try {
      eli.dispatch("auto_emailer", "compose", seedShape);
      // Tell the training tour the contract emailer is opening.
      try { if (eli.bus && eli.bus.emit) eli.bus.emit("build_draft:emailer_opening", {}); } catch (_e) {}
    } catch (e) {
      eli.log.event("tool", "build_draft_step5_dispatch_failed", { msg: e && e.message });
      showToast("Email failed: " + (e && e.message || "unknown"), "err");
    }
  }

  // Browser-side blob write. Modern browsers get the system Save dialog
  // via showSaveFilePicker; older paths fall back to <a download>.
  function _writeBlob(blob, fileName) {
    if (window.showSaveFilePicker) {
      return window.showSaveFilePicker({
        suggestedName: fileName,
        types: [{
          description: "Word Document",
          accept: { "application/vnd.openxmlformats-officedocument.wordprocessingml.document": [".docx"] },
        }],
      }).then(function (handle) {
        return handle.createWritable().then(function (w) {
          return w.write(blob).then(function () { return w.close(); });
        });
      });
    }
    return new Promise(function (resolve) {
      var link = document.createElement("a");
      link.href = window.URL.createObjectURL(blob);
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      // Revoke after a tick so the browser actually fetches the blob.
      setTimeout(function () { window.URL.revokeObjectURL(link.href); }, 1000);
      resolve();
    });
  }

  // Declarative step→handler map. Adding a new step is one line:
  //   STEP_HANDLERS["foo"] = function (result, mount, opts, step) { ... };
  // Keep handlers small — extract to _render<Foo>Panel above if they grow.
  var STEP_HANDLERS = {
    logic: function () { _renderLogicPanel(); },
    templates: function () { _runStep2(); },
    error_review: function () { _runStep3ErrorReview(); },
    // "Save and/or Send" — save panel handles both: Save → save+email,
    // Skip → email-only. The standalone Auto Emailer tile is the way
    // to email without going through Build Draft at all.
    save: function (result) { _runStep4Gated(result); },
  };

  function _show(opts) {
    opts = opts || {};
    var mount = document.getElementById("_eli3_dashboard_root");
    // If the floating return-pill is still up from a Step 3 trip, drop
    // it now — the user is back in the hub.
    _removeReturnToHubPill();
    // Notify the training tour that the user is (back) at the Build Draft hub,
    // so it can auto-advance after Step 2 / Step 3 complete. Fire-and-forget.
    try { if (eli.bus && eli.bus.emit) eli.bus.emit("build_draft:hub_shown", { completed: Object.assign({}, _bdCompleted) }); } catch (_e) {}

    // Skip the body+headers scan when oars_loader already scanned the
    // body on boot (the auto-launch path). v3 regression vs v2: v2 ran
    // the OARS check and the template-load in the same kernel function,
    // so the body text was read once. v3's offload had oars_loader scan
    // first then call build_draft, which used to scan again. Now: if
    // _footerFile.text has the OARS marker we reuse it — saves a full
    // Word.run + body.load("text") + 2 header loads on every boot.
    var cachedBodyText = (_footerFile && _footerFile.text && /\bOARS\b/i.test(_footerFile.text))
      ? _footerFile.text
      : null;
    var scanPromise = cachedBodyText
      ? Promise.resolve({ found: true, bodyText: cachedBodyText, headerText: "" })
      : _scanDocForOars();

    eli.events.safeAsync(scanPromise, "build_draft.oars_scan")
      .then(function (scan) {
        var input = {
          bodyText: (scan && scan.bodyText) || "",
          headerText: (scan && scan.headerText) || "",
          footerFile: _footerFile,
        };
        return eli.events.safeAsync(analyze(input, providers), "build_draft.analyze");
      })
      .then(function (result) {
        if (!result) return;
        // Track the auto-launch chain so we can emit oars:ready (kernel
        // overlay listener) only after template load completes — not just
        // after the hub renders. Null = no template-load chain in flight.
        var launchChain = null;
        // Surface the detected type into the OARS boot overlay even when
        // we won't auto-launch (e.g. persisted type already set). Lets
        // the user see what was detected immediately.
        if (eli.bus && result.detectedType) {
          try { eli.bus.emit("oars:status", { detectedType: result.detectedType }); }
          catch (e) {}
        } else if (eli.bus && result.hasOars && !result.detectedType) {
          try { eli.bus.emit("oars:status", { detectedType: null }); }
          catch (e) {}
        }
        // 2026-05-21: stash detected type for the skeleton resolver
        // (used by _resolveSkeleton when loading a skeleton template).
        if (result.detectedType) _setSkeletonVariant(result.detectedType);
        if (result.hasOars && result.detectedType && !(result.persisted && result.persisted.type)) {
          eli.events.safeAsync(
            _persistAgreementState("OARS DATA", result.detectedType, { fields: result.fields }),
            "build_draft.persist"
          );
          // Detection + template-load success are silent — the OARS
          // banner in the hub already shows type / name / field count,
          // so the toast cascade was redundant noise. Failure still
          // toasts so the user knows when something went wrong. The
          // boot-time overlay (rendered by oars_loader) gets a live
          // status feed via the oars:status bus event so the user sees
          // which template is being loaded.
          launchChain = eli.events.safeAsync(_findTemplateByType(result.detectedType), "build_draft.template_lookup")
            .then(function (tpl) {
              if (!tpl || !tpl.name || !tpl.content) {
                if (eli.bus) {
                  try { eli.bus.emit("oars:status", { templateState: "no-match" }); }
                  catch (e) {}
                }
                return;
              }
              if (eli.bus) {
                try { eli.bus.emit("oars:status", { templateState: "matched", templateName: tpl.name }); }
                catch (e) {}
              }
              // Stash active-draft meta for the audit + telemetry. The OARS
              // auto-load path used to skip this (only the manual picker set
              // it), so audit records showed the agreement type but "—" for
              // the template. Mirror the picker's meta-set and open the run.
              try {
                window._bdActiveDraftMeta = window._bdActiveDraftMeta || {};
                var _adm = window._bdActiveDraftMeta;
                _adm.draftType = tpl.agreementType || tpl.draftType || tpl.type || _adm.draftType || null;
                _adm.templateId = tpl.id || _adm.templateId || null;
                _adm.templateName = tpl.name || _adm.templateName || null;
                _adm.templateVersion = tpl.publishedAt || tpl.version || _adm.templateVersion || null;
                _adm.isCustomTemplate = !!tpl.userCustomized;
                if (typeof _bdAuditEnsureRun === "function") _bdAuditEnsureRun();
                if (typeof _bdAuditPersistRun === "function") _bdAuditPersistRun();
              } catch (_admErr) {}
              // Extracted load chain — runs on confirm, or immediately
              // when the kill switch is off (legacy silent behavior).
              // FROM v2 showAutoFillHub line 21224: auto-load when type
              // matches; 2026-05-19 v8 scrub fixes the "baked party +
              // placeholder doubling" bug on step 2 fill.
              function _doAutoLoad() {
                return eli.events.safeAsync(_loadTemplateToWord(tpl.content), "build_draft.template_load")
                  .then(function () { return _scrubOldPartyAsPlaceholder(tpl.party); })
                  .then(function () {
                    if (eli.get && typeof eli.get("oars", "setTemplateLoaded") === "function") {
                      eli.dispatch("oars", "setTemplateLoaded", true);
                    }
                  })
                  .catch(function (err) {
                    eli.log.event("tool", "build_draft_tpl_load_failed", { msg: err && err.message });
                    showToast("Template load failed: " + (err && err.message), "err");
                  });
              }
              var confirmOn = true;
              try { confirmOn = eli.settings.get("build_draft.confirmOarsAutoLoad") !== false; } catch (_e) {}
              if (!confirmOn) {
                return _doAutoLoad();
              }
              // Show the premium confirmation dialog. We DON'T return
              // the dialog promise — launchChain resolves now so the
              // kernel boot overlay dismisses and the user sees the
              // dialog cleanly. The load runs independently on confirm.
              _showOarsConfirmDialog(tpl, result.detectedType, {
                // Return the promise so the dialog can keep its loading
                // state up until the load settles, then auto-close.
                onConfirm: function () { return _doAutoLoad(); },
                onChoose: function () {
                  try { _openTemplatesPicker(); }
                  catch (e) { eli.log.event("tool", "build_draft_oars_picker_failed", { msg: e && e.message }); }
                },
                onSkip: function () {
                  if (eli.bus) {
                    try { eli.bus.emit("oars:status", { templateState: "skipped" }); }
                    catch (_e) {}
                  }
                },
              });
            });
        }
        // Emit oars:ready when the launch chain settles (or immediately
        // if no template load was kicked off). Kernel listens once per
        // overlay; subsequent emits are no-op.
        function _signalReady() {
          if (eli.bus) eli.bus.emit("oars:ready", { ts: Date.now() });
        }
        if (launchChain) launchChain.then(_signalReady, _signalReady);
        else _signalReady();
        // Resume: restore step state from the persisted audit record (once)
        // before the hub paints, so a reopened doc shows prior steps done +
        // their times. No-op for fresh builds (hydration flag already set).
        _bdHydrateFromAudit().then(function () {
        // Attach requester name from OARS state so the hub banner can show it.
        // OARS state doesn't carry requesterName directly — extract via _extractOarsMetadata.
        try {
          var _oSt = eli.dispatch ? eli.dispatch("oars", "getState") : null;
          if (_oSt) {
            var _hubMeta = _extractOarsMetadata(_oSt);
            if (_hubMeta && _hubMeta.requesterName) result.requesterName = _hubMeta.requesterName;
          }
        } catch (_e) {}
        var _guidedOn = false;
        try { _guidedOn = eli.settings.get("build_draft.guidedMode") === true; } catch (_e) {}
        renderHub({
          result: result,
          mount: mount,
          completedSteps: _bdCompleted,
          completedTimes: _bdHubStepTimes(),
          guidedMode: _guidedOn,
          onToggleGuided: function (on) {
            try { eli.settings.set("build_draft.guidedMode", !!on); } catch (_e) {}
            if (typeof showToast === "function") showToast(on ? "Guided mode ON" : "Guided mode OFF", "ok");
          },
          onClose: _goHome,
          onRunAll: eli.events.guard(function () {
            // Run All = Step 1 → Step 2 → preSave → Step 3. Wizard flag
            // makes each finished step auto-advance via setTimeout. If no
            // logic defs, skip Step 1 and jump to Step 2.
            _wizardMode = true;
            showToast("🚀 Starting Wizard…", "info");
            if (result.logicDefs && result.logicDefs.count) {
              _renderLogicPanel();
            } else {
              _runStep2();
            }
          }, "build_draft.run_all"),
          onTemplates: eli.events.guard(function () {
            // Folder button → premium nested picker. Gear / settings entry
            // (tile_settings dispatch) still routes to _renderTemplatesPanel
            // for save/import/export/file-name-pattern config.
            _openTemplatesPicker();
          }, "build_draft.templates"),
          onStep: eli.events.guard(function (id, step) {
            var handler = STEP_HANDLERS[id];
            if (handler) { handler(result, mount, opts, step); return; }
            renderStepStub && renderStepStub({
              mount: mount,
              step: step,
              onBack: function () { _show(opts); },
            });
          }, "build_draft.step"),
          // 2026-06-13: hub "Update Document Fields" button removed per user
          // request. _refreshAllFields() still runs via the post-Step-2
          // auto-refresh path (Settings → OTHER toggle).
          onClearOars: eli.events.guard(function () {
            eli.events.safeAsync(eli.ui.confirm({
              title: "Clear OARS data?",
              message: "Removes the OARS data from the footer AND from this document. The doc itself isn't modified.",
            }), "build_draft.clear-oars.confirm")
              .then(function (ok) {
                if (!ok) return null;
                // Single canonical clear: eli.dispatch("oars","clear")
                // handles state + Office settings + sentinel + bus +
                // toast. Falls back to the tool-local wipe if eli_oars
                // isn't installed (other team's deployment).
                if (eli.get && typeof eli.get("oars", "clear") === "function") {
                  eli.dispatch("oars", "clear");
                  return true;
                }
                return eli.events.safeAsync(_clearAgreementState(), "build_draft.clear-oars")
                  .then(function () {
                    if (eli.bus) eli.bus.emit(BUS_OARS_CLEARED, {});
                    return true;
                  });
              })
              .then(function (cleared) {
                if (!cleared) return; // user cancelled
                _footerFile = null;
                _bdCompleted = { logic: false, templates: false, error_review: false, save: false };
                try { eli.compat.lsRemove("_eli3_oars_loaded"); }
                catch (e) { eli.log.event("tool", "build_draft_lsremove_failed", { msg: e && e.message }); }
                showToast("🗑️ OARS data + file cleared.", "ok");
                _show(opts);
              })
              .catch(function (err) {
                eli.log.event("tool", "build_draft_clear_oars_failed", { msg: err && err.message });
                showToast("Clear failed: " + (err && err.message), "err");
              });
          }, "build_draft.clear-oars"),
        });
        }); // close _bdHydrateFromAudit().then(function(){
      })
      .catch(function (err) {
        eli.log.event("tool", "build_draft_show_failed", { msg: err && err.message });
        showToast("Build Draft load failed: " + (err && err.message), "err");
      });
  }

  // Bus: kernel boot hook fires "oars:detected" when active doc has OARS.
  if (eli.bus && eli.bus.on) {
    eli.bus.on(BUS_OARS_DETECTED, function (payload) {
      _show({ source: "oars", payload: payload || {} });
    });
    // Audit step 4 = the draft was SENT OUT, not merely saved. auto_emailer
    // emits this when the user clicks "Open Gmail draft". We bump only when
    // the emit carries the runId of the still-active build run (build_draft
    // seeds it into the compose dispatch), so a standalone emailer open
    // never stamps a stale run.
    eli.bus.on("build_draft:emailed", function (payload) {
      try {
        var rid = payload && payload.runId;
        var m = window._bdActiveDraftMeta;
        if (rid && m && m.auditRunId === rid) { _bdCompleted.save = true; m.auditEmailed = true; _bdStampStepTime("emailed"); _bdAuditBumpStep(4); }
      } catch (_e) {}
    });
  }

  // Stat helper: kernel's eli.stats.record writes to IDB only — no trophy
  // dependency — so this is safe whether or not trophy_gallery is installed.
  // Try/catch guards against any unexpected throw from the kernel module
  // (older kernels, IDB closed during shutdown, etc.) so a failed stat
  // never blocks the user-visible action.
  function _recordStatSafe(name) {
    try {
      if (eli.stats && typeof eli.stats.record === "function") {
        eli.stats.record(name);
      }
    } catch (e) {
      eli.log.event("tool", "build_draft_stat_failed", { stat: name, msg: e && e.message });
    }
  }

  eli.register({
    tile: { app_build_draft: function () {
      // FROM v2 renderAutoFillHubUI line 21255: stat tracking on hub open.
      _recordStatSafe("appOpenedDraft");
      _show({ source: "tile" });
    } },
    // Gear icon on the dashboard tile (and the Command Center Draft
    // Templates card) both dispatch here — single canonical entry to the
    // templates panel.
    tile_settings: { app_build_draft: function () {
      _recordStatSafe("appOpenedDraftTemplates");
      _renderTemplatesPanel();
    } },
    // Programmatic step-jumps for cross-tool callers (e.g. bd_template_tester
    // re-opens Step 1 after Reload Draft so the freshly-loaded doc gets
    // re-scanned and the logic-form dropdowns reappear). Each handler is
    // the same thing the hub's own buttons would call. Handlers return
    // `true` so callers can distinguish "channel exists + ran" from
    // "channel missing on older build_draft" (eli.dispatch returns
    // undefined for unregistered keys).
    build_draft: {
      logic:     eli.events.guard(function () { _renderLogicPanel();     return true; }, "build_draft.dispatch.logic"),
      templates: eli.events.guard(function () { _renderTemplatesPanel(); return true; }, "build_draft.dispatch.templates"),
      hub:       eli.events.guard(function () { _show({ source: "dispatch" }); return true; }, "build_draft.dispatch.hub"),
      // 2026-05-21: skeleton-aware template loaders for external callers
      // (Skeleton Workshop). loadTemplateRaw: bypasses the &[…] / #[…]
      // resolver so the template enters Word with markers intact for
      // editing. listTemplates: returns the bd_templates rows so the
      // workshop can render a picker without re-implementing storage
      // access. Both return Promises.
      listTemplates: eli.events.guard(function () {
        return _bdGetAll();
      }, "build_draft.dispatch.listTemplates"),
      // 2026-05-21: "Load + Resolve (keep variants)" — clauses get
      // inlined (so the user sees the full agreement in context) but
      // the &[…] variant markers stay visible. Used for clause-content
      // editing workflows where you want to read the rendered draft
      // and update individual clauses inline. Skeleton structure is
      // not preserved on the doc side — to save back as a skeleton,
      // use loadTemplateRaw + saveTemplateRaw instead.
      loadTemplateResolved: eli.events.guard(function (idOrContent) {
        var contentPromise;
        if (typeof idOrContent === "string" && idOrContent.indexOf("{") !== 0) {
          contentPromise = _bdGet(idOrContent).then(function (row) {
            if (!row) throw new Error("Template not found: " + idOrContent);
            // Stash the agreement type so the resolver picks the right
            // initial variant — same as the normal load path.
            if (row.agreementType) _setSkeletonVariant(row.agreementType);
            return row.content;
          });
        } else {
          contentPromise = Promise.resolve(idOrContent);
        }
        return contentPromise.then(function (content) {
          if (!content) throw new Error("Template has no content.");
          return _loadTemplateToWord(content, { keepVariantMarkers: true });
        });
      }, "build_draft.dispatch.loadTemplateResolved"),
      loadTemplateRaw: eli.events.guard(function (idOrContent) {
        // Accepts either a bd_templates row id (string) or a content
        // string. If id, fetch the row + load its content. Either way,
        // bypass skeleton resolution via opts.skipSkeleton.
        var contentPromise;
        if (typeof idOrContent === "string" && idOrContent.indexOf("{") !== 0) {
          contentPromise = _bdGet(idOrContent).then(function (row) {
            if (!row) throw new Error("Template not found: " + idOrContent);
            return row.content;
          });
        } else {
          contentPromise = Promise.resolve(idOrContent);
        }
        return contentPromise.then(function (content) {
          if (!content) throw new Error("Template has no content.");
          return _loadTemplateToWord(content, { skipSkeleton: true });
        });
      }, "build_draft.dispatch.loadTemplateRaw"),
      // 2026-05-21: round-trip companion to loadTemplateRaw. Captures
      // the current Word doc (body + per-section H/F via the same
      // pipeline normal save uses) and writes it back to the same
      // bd_templates row by id. Preserves name / agreementType / party
      // metadata and bumps modifiedAt. No OARS / counterparty prompts
      // — strictly "save the current doc back to this template id."
      // Used by Skeleton Workshop's "Save Back" button.
      saveTemplateRaw: eli.events.guard(function (templateId) {
        if (!templateId) return Promise.reject(new Error("templateId required"));
        return _bdGet(templateId).then(function (existing) {
          if (!existing) throw new Error("Template not found: " + templateId);
          return _captureActiveDocAsTemplate().then(function (captured) {
            existing.content = JSON.stringify(captured);
            existing.modifiedAt = new Date().toISOString();
            if (typeof existing.version === "number") existing.version += 1;
            return _bdPut(existing).then(function () {
              eli.log.event("tool", "build_draft_template_saved_back", {
                id: templateId, name: existing.name || null,
                bodyLen: (captured.body || "").length,
                sections: (captured.sections || []).length,
              });
              return { ok: true, name: existing.name || templateId };
            });
          });
        });
      }, "build_draft.dispatch.saveTemplateRaw"),
      // 2026-05-21: sharded-template CDN consumer side. Companion to
      // Template Manager's per-template publish. Three handlers:
      //   • fetchManifest()    — pull the manifest from CDN, cache in IDB
      //   • fetchTemplate(id)  — download a single template, write to bd_templates
      //   • listAvailableTemplates() — merge manifest + local IDB rows for UI
      //
      // No UI changes yet (Turn 2 task). These handlers are the wiring
      // that lets the picker, OARS pre-fetch hook, and core batch
      // downloader call into a stable CDN-aware API.
      fetchManifest: eli.events.guard(function () {
        var repo = (typeof localStorage !== "undefined" && localStorage.getItem("eli_github_repo")) || "apndrewn/eli-data";
        var branch = (typeof localStorage !== "undefined" && localStorage.getItem("eli_github_branch")) || "main";
        // 2026-05-22: switched manifest fetch from jsdelivr to raw.
        // The manifest is small (~3KB) and changes frequently — jsdelivr's
        // edge cache was lagging 5-15 min behind GitHub, so freshly pushed
        // templates didn't show up in consumer dispatch results even after
        // the push fully landed on GitHub. raw.githubusercontent.com has
        // zero caching → instant freshness. Per-template files (much bigger,
        // less churn) still use jsdelivr where the CDN benefit is real.
        var url = "https://raw.githubusercontent.com/" + repo + "/" + branch + "/bd-templates/bd-templates-manifest-v3.json?t=" + Date.now();
        return fetch(url, { cache: "no-store" }).then(function (r) {
          if (!r.ok) throw new Error("Manifest fetch failed: HTTP " + r.status);
          return r.json();
        }).then(function (manifest) {
          // Cache the manifest in IDB so OARS pre-fetch + picker can
          // read it synchronously without re-fetching every time.
          //
          // 2026-05-22 fix: STORE_CONFIG uses `key` as keyPath, not
          // `id` (matches the kernel's _manifest_cache pattern at
          // taskpane_v3.js line 6329). Using `id` triggered an IDB
          // DataError because IDB couldn't extract a key from the
          // object — the put silently failed and the manifest cache
          // was never persisted.
          return eli.storage.put("config", {
            key: "_bd_templates_manifest",
            manifest: manifest,
            cachedAt: new Date().toISOString(),
          }).then(function () { return manifest; });
        });
      }, "build_draft.dispatch.fetchManifest"),
      fetchTemplate: eli.events.guard(function (id) {
        if (!id) return Promise.reject(new Error("template id required"));
        var repo = (typeof localStorage !== "undefined" && localStorage.getItem("eli_github_repo")) || "apndrewn/eli-data";
        var branch = (typeof localStorage !== "undefined" && localStorage.getItem("eli_github_branch")) || "main";
        // 2026-05-22 v2: switched per-template fetch from jsdelivr to raw.
        // jsdelivr's edge cache for per-template files was serving STALE
        // content (old publishedAt) even after fresh pushes. Auto-sync
        // would detect the manifest's new lastUpdated, fetch the file,
        // write local with the OLD publishedAt baked into the cached
        // file's payload — and next sync would detect the same mismatch
        // and re-download forever. Raw eliminates the cache entirely.
        // At our user scale (~30 users) raw rate limits are fine.
        var url = "https://raw.githubusercontent.com/" + repo + "/" + branch + "/bd-templates/" + encodeURIComponent(id) + ".json?t=" + Date.now();
        return fetch(url, { cache: "no-store" }).then(function (r) {
          if (!r.ok) throw new Error("Template fetch failed: HTTP " + r.status);
          return r.json();
        }).then(function (payload) {
          // Payload is the envelope Template Manager wrote: { id, name,
          // agreementType, party, content|content_z, publishedAt, … }.
          // Translate into a bd_templates row + put.
          // 2026-05-22: handle dual-format content. New publishes use
          // `content_z` (base64-encoded pako deflate of UTF-8 bytes).
          // Old publishes use `content` (raw string). Detect + decode.
          // If a colleague hits a `content_z` payload without pako, we
          // throw a clear error rather than silently storing gibberish.
          var contentStr;
          if (payload.content_z) {
            if (!_bdPakoLoaded() || !_BD_TD) {
              throw new Error("Template '" + (payload.id || id) +
                "' was published with compression. Add " +
                "https://cdn.jsdelivr.net/npm/pako@2.1.0/dist/pako.min.js" +
                " to Script Lab Libraries tab and reload.");
            }
            try {
              var bytes = _bdB64ToBytes(payload.content_z);
              var u8    = window.pako.inflate(bytes);
              contentStr = _BD_TD.decode(u8);
            } catch (e) {
              throw new Error("Failed to decompress template '" + (payload.id || id) + "': " + (e && e.message || e));
            }
          } else {
            contentStr = payload.content || "";
          }
          var row = {
            id: payload.id || id,
            name: payload.name || payload.id || id,
            content: contentStr,
            party: payload.party || "",
            agreementType: payload.agreementType || "",
            modifiedAt: payload.publishedAt || new Date().toISOString(),
            core: !!payload.core,
            defaultForType: !!payload.defaultForType,
            audienceEmails: payload.audienceEmails || [],
            audienceGroups: payload.audienceGroups || [],
            aliases: payload.aliases || [],
            publishedAt: payload.publishedAt || null,
            publishedBy: payload.publishedBy || "",
            cachedFromCdn: true,
          };
          return _bdPut(row).then(function () {
            eli.log.event("tool", "build_draft_template_fetched", {
              id: row.id, publishedAt: row.publishedAt, size: (row.content || "").length,
            });
            return row;
          });
        });
      }, "build_draft.dispatch.fetchTemplate"),
      listAvailableTemplates: eli.events.guard(function () {
        // Merge cached manifest entries with local bd_templates rows.
        // Returns [{ ...manifestEntry, cached: bool, localRow: {...} }]
        // Audience filtering happens here so the picker doesn't need
        // to know — non-admin users never see templates not in their
        // audience.
        var userEmail = "";
        try {
          var id = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
          userEmail = String((id && id.email) || "").toLowerCase().trim();
        } catch (_e) {}
        return Promise.all([
          eli.storage.get("config", "_bd_templates_manifest").catch(function () { return null; }),
          _bdGetAll(),
        ]).then(function (results) {
          var cached = results[0];
          var localRows = results[1] || [];
          var manifest = (cached && cached.manifest) || { templates: [] };
          var localById = {};
          localRows.forEach(function (r) { if (r && r.id) localById[r.id] = r; });
          // Build map of manifest entries by id.
          var byId = {};
          (manifest.templates || []).forEach(function (e) {
            // Audience filter: empty audienceEmails = visible to all admins.
            // If list set, current user must be in it.
            if (e.audienceEmails && e.audienceEmails.length) {
              var emails = e.audienceEmails.map(function (s) { return String(s || "").toLowerCase().trim(); });
              if (emails.indexOf(userEmail) === -1) return;
            }
            byId[e.id] = {
              id: e.id, name: e.name, agreementType: e.agreementType,
              size: e.size, lastUpdated: e.lastUpdated,
              core: !!e.core, defaultForType: !!e.defaultForType,
              audienceEmails: e.audienceEmails || [],
              aliases: e.aliases || [],
              cached: !!localById[e.id],
              fromManifest: true,
            };
          });
          // Add any local-only rows (e.g. the user's own templates not
          // yet published) — these are always shown to their owner.
          localRows.forEach(function (r) {
            if (!byId[r.id]) {
              byId[r.id] = {
                id: r.id, name: r.name || r.id, agreementType: r.agreementType || "",
                size: (r.content || "").length,
                lastUpdated: r.modifiedAt,
                core: !!r.core, defaultForType: !!r.defaultForType,
                audienceEmails: r.audienceEmails || [],
                aliases: r.aliases || [],
                cached: true, fromManifest: false,
              };
            }
          });
          return Object.values(byId).sort(function (a, b) {
            return String(a.name).localeCompare(String(b.name));
          });
        });
      }, "build_draft.dispatch.listAvailableTemplates"),
      clearGuidedProgress: function () {
        try {
          eli.storage.delete("config", "_bd_guided_ring");
          eli.storage.delete("config", "_bd_guided_progress");
          var s = Office.context.document.settings;
          s.remove("BdGuidedProgress");
          if (typeof s.saveAsync === "function") s.saveAsync(function () {});
          if (typeof showToast === "function") showToast("Guided progress cleared", "ok");
        } catch (_e) {}
      },
    },
    // 2026-05-19: activity-feed restore for the Step 2 fill form. When
    // the entry's payload has a `phase: "step2-fill"` shape (saved by
    // _showStep2Form on entry + live-updated as the user types), this
    // re-renders the fill form with every value the user had filled in.
    // Falls back to opening the hub when payload is missing (e.g. an
    // older entry from before this restore handler existed).
    activity_restore: {
      "build-draft": function (payload) {
        try {
          // Step 1 guided — re-open guided mode (progress restored from doc settings)
          if (payload && payload.phase === "step1-guided") {
            _show({ source: "activity_restore" });
            setTimeout(function () { _renderLogicPanel(); }, 0);
            return;
          }
          if (payload && payload.phase === "step2-fill" && payload.scannedText) {
            _show({ source: "activity_restore" });
            setTimeout(function () {
              _showStep2Form(payload.scannedText, true, {
                prefillValues: payload.values || {},
                guidedIdx: payload.guidedIdx || 0,
                sourceText: payload.sourceText || "",
                sourceName: payload.sourceName || null,
              });
            }, 0);
            return;
          }
        } catch (_e) {}
        // Default fallback — just open the hub.
        _show({ source: "activity_restore" });
      },
    },
  });

  // 2026-05-22: ride-along on kernel's sync trigger. Whenever the
  // kernel's syncFromManifest fires (boot auto-check OR manual
  // "Check for Updates" button), refresh the template manifest in
  // parallel + surface any new templates the user can download.
  // No new polling timer — we reuse the kernel's existing cadence.
  // 2026-05-22: module-level race lock. Two sync triggers fire on boot
  // (kernel emit + build_draft's 2s fallback) — without this they raced,
  // each running its own download chain over the same missing rows.
  // Result: every template downloaded twice, and each chain's toast
  // reported ONLY its own count (3) even though 6 fetches happened.
  // The lock makes the second trigger skip if a sync is already in
  // flight. Re-armed when the in-flight sync resolves.
  var _syncInFlight = false;
  function _syncTemplatesFromCdn(opts) {
    opts = opts || {};
    var silent = !!opts.silent;
    if (_syncInFlight) {
      eli.log.event("tool", "build_draft_template_sync_skip_race", { silent: silent });
      return Promise.resolve(null);
    }
    _syncInFlight = true;
    var _release = function () { _syncInFlight = false; };
    return eli.dispatch("build_draft", "fetchManifest").then(function (manifest) {
      if (!manifest || !Array.isArray(manifest.templates)) return null;
      // Audience filter for current user.
      var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
      var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
      var visible = manifest.templates.filter(function (e) {
        if (!e.audienceEmails || !e.audienceEmails.length) return true; // empty = all users
        var emails = e.audienceEmails.map(function (s) { return String(s || "").toLowerCase().trim(); });
        return emails.indexOf(userEmail) !== -1;
      });
      return _bdGetAll().then(function (localRows) {
        var localById = {};
        (localRows || []).forEach(function (r) { if (r && r.id) localById[r.id] = r; });
        var missing = [], updated = [], localOnly = [], conflicted = [];
        visible.forEach(function (e) {
          var have = localById[e.id];
          if (!have) { missing.push(e); return; }
          var remoteTs = e.lastUpdated ? new Date(e.lastUpdated).getTime() : 0;
          var localTs  = have.publishedAt ? new Date(have.publishedAt).getTime() : 0;
          // 2026-05-22 v2: self-healing legacy-bundle migration +
          // local-edit protection. Three categories of rows without
          // publishedAt, distinguished by whether modifiedAt is set:
          //
          //   A. publishedAt missing + modifiedAt missing
          //      → LEGACY BUNDLE row (installed from the old monolithic
          //        __data_bd_templates blob, written by Build Draft Save
          //        which never set modifiedAt). Treat as missing and
          //        refresh from CDN. Self-heals on first sync after
          //        the user gets the new build_draft.
          //
          //   B. publishedAt missing + modifiedAt set
          //      → REAL LOCAL ROW (user authored via Template Manager
          //        and hasn't pushed yet, OR edited a CDN template via
          //        Build Draft Save panel which now also sets modifiedAt).
          //        Protect — never auto-overwrite user work.
          //
          //   C. publishedAt set
          //      → Normal sync flow: compare timestamps. If
          //        modifiedAt > publishedAt AND remote newer, conflict.
          if (!have.publishedAt) {
            if (!have.modifiedAt) {
              // Category A — legacy bundle row. Refresh from CDN.
              missing.push(e);
            } else {
              // Category B — real local row. Protect.
              localOnly.push(e);
            }
            return;
          }
          var localModTs = have.modifiedAt ? new Date(have.modifiedAt).getTime() : 0;
          if (localModTs > localTs && remoteTs > localTs) {
            conflicted.push({ entry: e, local: have });
            return;
          }
          if (remoteTs > localTs) updated.push({ entry: e, local: have });
        });
        eli.log.event("tool", "build_draft_template_sync", {
          visible: visible.length, missing: missing.length, updated: updated.length,
          localOnly: localOnly.length, conflicted: conflicted.length,
        });
        // Surface conflicts as a warning — local edits + remote edits
        // overlap, user must decide which wins.
        if (!silent && conflicted.length) {
          var names = conflicted.map(function (c) { return c.local.name || c.entry.id; }).slice(0, 3).join(", ");
          if (typeof showToast === "function") {
            showToast("⚠️ " + conflicted.length + " template" +
              (conflicted.length === 1 ? " has" : "s have") +
              " local edits + a newer CDN version (" + names +
              (conflicted.length > 3 ? ", …" : "") +
              "). Push to publish your edits, or delete locally to accept CDN.", "warn");
          }
        }
        // Auto-download rules — same regardless of silent vs explicit:
        //   • Missing + Core  → auto-fetch (new core templates)
        //   • Updated + cached → auto-fetch (refresh what user has)
        //   • Missing + Lazy  → NEVER auto-fetch (truly opt-in)
        //
        // 2026-05-22 v4: lazy means lazy — never auto-downloaded
        // anywhere. Lazy templates require explicit per-template
        // fetch (via OARS detection, the future picker UI, or a
        // manual eli.dispatch call). Manual "Check for Updates"
        // toasts about lazy availability but doesn't pull them.
        var coreMissing = missing.filter(function (e) { return !!e.core; });
        var lazyMissing = missing.filter(function (e) { return !e.core; });
        var cachedUpdated = updated.map(function (u) { return u.entry; });
        var toDownload = coreMissing.concat(cachedUpdated);
        if (!silent) {
          if (coreMissing.length || updated.length) {
            var parts = [];
            if (coreMissing.length) parts.push(coreMissing.length + " new core");
            if (updated.length) parts.push(updated.length + " updated");
            if (typeof showToast === "function") {
              showToast("🆕 Found " + parts.join(" + ") + " — downloading…", "info");
            }
          } else if (lazyMissing.length) {
            // Only lazy missing — surface as info but don't download.
            // User can install by flipping the row to Core in
            // Template Manager OR by fetching manually:
            //   eli.dispatch("build_draft", "fetchTemplate", "<id>")
            if (typeof showToast === "function") {
              showToast("ℹ️ " + lazyMissing.length + " lazy template" +
                (lazyMissing.length === 1 ? " is" : "s are") +
                " on CDN but not auto-downloaded. Flip to Core in Template Manager to install, or fetch manually.", "info");
            }
          } else if (visible.length) {
            if (typeof showToast === "function") showToast("✅ Templates in sync (" + visible.length + " on CDN, " + (Object.keys(localById).length) + " local).", "ok");
          } else {
            if (typeof showToast === "function") showToast("ℹ️ No templates on the CDN yet — publish from Template Manager first.", "info");
          }
        }
        if (!toDownload.length) return { missing: missing.length, updated: updated.length };
        return _coreDownloadChain(toDownload).then(function (downloaded) {
          if (downloaded > 0 && typeof showToast === "function") {
            var parts2 = [];
            if (coreMissing.length) parts2.push(coreMissing.length + " new core");
            if (cachedUpdated.length) parts2.push(cachedUpdated.length + " update" + (cachedUpdated.length === 1 ? "" : "s"));
            showToast("📥 Downloaded " + downloaded + " template" +
              (downloaded === 1 ? "" : "s") +
              (parts2.length ? " (" + parts2.join(" + ") + ")" : "") +
              ".", "ok");
          }
          return {
            missing: missing.length, updated: updated.length,
            coreDownloaded: downloaded,
          };
        });
      });
    }).catch(function (err) {
      // Manifest doesn't exist yet (no templates pushed), 404, or net
      // hiccup — silent fail. Don't toast on every boot for a non-error.
      eli.log.event("tool", "build_draft_template_sync_skip", { msg: err && err.message });
      return null;
    }).then(function (result) {
      _release(); // race lock released regardless of success/failure
      return result;
    }, function (err) {
      _release();
      throw err;
    });
  }
  function _coreDownloadChain(entries) {
    var chain = Promise.resolve();
    var count = 0;
    entries.forEach(function (e) {
      chain = chain.then(function () {
        return eli.dispatch("build_draft", "fetchTemplate", e.id)
          .then(function () { count++; })
          .catch(function (err) {
            eli.log.event("tool", "build_draft_template_fetch_failed", {
              id: e.id, msg: err && err.message,
            });
          });
      });
    });
    return chain.then(function () { return count; });
  }

  // Hook the bus event so manual "Check for Updates" + boot auto-check
  // both trigger the template manifest sync.
  if (eli.bus && eli.bus.on) {
    eli.bus.on("tools:sync_started", function (payload) {
      // Match the kernel's silent flag — boot auto-check is silent,
      // manual check shows toasts.
      _syncTemplatesFromCdn({ silent: !!(payload && payload.silent) });
    });
  }
  // Also fire once on tool init in case the kernel's sync ran BEFORE
  // build_draft loaded (boot race — build_draft is a preload-tier tool
  // but kernel sync could fire even earlier). Silent — boot path.
  setTimeout(function () { _syncTemplatesFromCdn({ silent: true }); }, 2000);

  eli.log.event("tool", "build_draft_initialized", {});
}

jsonTools.css:
/* build_draft tool styles. Injected as <style data-tool="build_draft">. */

._eli3_bd_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}
/* Standard tool-hub header — dark navy banner with gold accent rule.
   Matches the Save panel + cross-tool standard header style. */
._eli3_bd_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_bd_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_bd_back:hover { color: #f2d866; }
._eli3_bd_title {
  flex: 1; font: 800 16px/1.2 'Georgia', serif; color: #ffffff;
  letter-spacing: 0.2px;
}
._eli3_bd_bar_templates {
  background: rgba(255,255,255,0.10);
  border: 1px solid rgba(255,255,255,0.20);
  color: #f2d866;
  font-size: 14px; line-height: 1;
  padding: 6px 10px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_bar_templates:hover {
  background: rgba(201,162,39,0.25);
  border-color: rgba(201,162,39,0.6);
  transform: translateY(-1px);
}
/* Floating "← Back to Build Draft Hub" pill. Mounted on body when user
   leaves the hub for Step 3 (error_review tile takes over the panel).
   Fixed bottom-right so it stays visible across navigation; clicked or
   removed on hub re-entry. */
._eli3_bd_return_pill {
  position: fixed;
  bottom: 60px;
  right: 18px;
  z-index: 100;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border: 1px solid #c9a227;
  color: #f2d866;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  padding: 10px 16px;
  border-radius: 24px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.35), 0 0 0 3px rgba(201,162,39,0.15);
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_return_pill:hover {
  background: linear-gradient(135deg, #1b263b 0%, #2d3a52 100%);
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.4), 0 0 0 4px rgba(201,162,39,0.25);
  color: #ffd700;
}

/* Sub-label chip on the right of the bar (panel-specific count/state) */
._eli3_bd_overview {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #c9a227;
  background: rgba(201,162,39,0.15);
  border: 1px solid rgba(201,162,39,0.4);
  padding: 5px 10px;
  border-radius: 12px;
}

/* ── OARS data header — premium centered title-bar ───────────────────
   Re-cast from a paper-cream card into a flat, edge-to-edge header strip.
   No rounded corners, no shadow, no box-border — just a 2px gold rule at
   the bottom that visually seats it as "page furniture" rather than a
   clickable card. The card vocabulary read like a button next to the
   step rows below; the flat-strip vocabulary now clearly says "header."
     • Layout: grid [icon | centered text block | clear] so the title
       sits dead-center between the two edge elements.
     • Title row: agreement type as a Georgia serif headline (the
       primary identity — the user knows what kind of doc they're in).
     • Meta row: source label + requester + field count joined inline
       with middle dots — uppercase slate, recedes appropriately.
     • Bottom gold rule echoes the gold flow line in the step ribbons. */
._eli3_bd_oars_banner {
  position: relative;
  /* 2026-06-13 v3: a bare CENTERED header — no background, no border, no
     shadow, no box of any kind. Just the title + sub-line sitting on the
     page, centered. The previous versions kept reading as a button because
     they had a surrounding surface; this removes it entirely. The close ✕
     is pulled out of flow (absolute top-right) so it doesn't offset the
     centering. */
  display: block;
  text-align: center;
  margin: 2px 0 4px;
  padding: 3px 40px;          /* horizontal room so centered text clears the ✕ */
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
._eli3_bd_oars_icon {
  /* Bare glyph, centered above the title — no disc/box. */
  display: block;
  margin: 0 auto 1px;
  width: auto; height: auto;
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-size: 15px;
  color: #c9a227;
}
._eli3_bd_oars_main {
  min-width: 0;
  display: block;
  text-align: center;
}
._eli3_bd_oars_value {
  font: 700 18px/1.2 'Book Antiqua', 'Georgia', 'Times New Roman', serif;
  color: #0f1f3d;                       /* deep navy ink headline */
  letter-spacing: 0.01em;
  /* Single-line headline; truncate with ellipsis if a long filename is
     appended via the "type · filename" pattern. */
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_bd_oars_meta {
  font: 600 9.5px/1.3 'Inter', 'Segoe UI', sans-serif;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #64748b;                       /* slate-500 subline */
  margin-top: 2px;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_bd_oars_meta_lead {
  color: #b8901f;                       /* gold kicker (dark enough on light) */
}
._eli3_bd_oars_meta_sep {
  color: rgba(201,162,39,0.45);
  margin: 0 7px;
}
._eli3_bd_oars_clear {
  position: absolute;                   /* out of flow — keeps title centered */
  top: 4px; right: 6px;
  background: none; border: none; cursor: pointer;
  font: 700 14px/1 'Inter', sans-serif;
  color: #94a3b8;
  padding: 4px 6px;
  border-radius: 6px;
  transition: color .15s, background .15s;
}
._eli3_bd_oars_clear:hover {
  color: #b91c1c;
  background: rgba(239,68,68,0.06);
}

/* Empty state — a quiet dashed "waiting slot", clearly NOT rich. Inset
   like a card (not edge-bleed) so the absence of data reads as an
   empty socket rather than a failed header. */
/* Empty "no OARS data" state — also bare (no dashed box), just quiet
   centered grey text, matching the borderless header treatment. */
._eli3_bd_oars_banner_empty ._eli3_bd_oars_icon {
  filter: grayscale(1);
  opacity: 0.55;
}
._eli3_bd_oars_banner_empty ._eli3_bd_oars_value {
  font: 600 italic 14px/1.2 'Georgia', 'Times New Roman', serif;
  color: #64748b;
}
._eli3_bd_oars_banner_empty ._eli3_bd_oars_meta {
  color: #94a3b8;
  letter-spacing: 0.14em;
}

._eli3_bd_actions {
  display: flex; gap: 8px;
  padding: 14px 14px 0;
}
._eli3_bd_run_all {
  flex: 2;
  padding: 12px 14px;
  font: 800 12px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  transition: transform .12s, box-shadow .12s;
}
._eli3_bd_run_all:hover { transform: translateY(-1px); box-shadow: 0 4px 12px rgba(21,101,192,0.30); }
._eli3_bd_run_all_icon { font-size: 16px; }
._eli3_bd_templates {
  flex: 1;
  padding: 12px 12px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a;
  border: 1px solid #b0bec5;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_bd_templates:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); border-color: #90caf9; color: #1565c0; }
._eli3_bd_templates_icon { font-size: 14px; }

._eli3_bd_steps {
  flex: 1; overflow-y: auto;
  padding: 18px 14px 14px;
  display: flex; flex-direction: column; gap: 10px;
  position: relative;  /* anchor for the gold flow line */
}
/* ── Premium gold flow line ─────────────────────────────────────────
   A 4px vertical gold rail centered on the ribbon tabs, running from the
   top of the first step's ribbon to the bottom of the last step's. The
   step buttons (z-index:1) sit ABOVE the line and cover it across each
   row's body; the line is visible ONLY in the 10px gaps between rows.
   That creates the readable flow: step 1 → gold segment → step 2 →
   gold segment → step 3 → gold segment → step 4. Layered glow ties it
   to the ribbon tab's gold rule and the overall gold-accent vocabulary.  */
._eli3_bd_steps::before {
  content: "";
  position: absolute;
  /* 14px (parent's padding-left) + 30px (half of 60px ribbon) − 2px (half line width)
     = 42px → puts the 4px line centered on the ribbon tabs */
  left: 42px;
  top: 22px;       /* clip line behind first row */
  /* The bottom var is set in JS post-layout so the line terminates at
     step 4's bottom edge — without that, when the four rows don't fill
     the available vertical space, the line would bleed below step 4. */
  bottom: var(--_bd_gold_line_bottom, 18px);
  width: 4px;
  background: linear-gradient(180deg,
    #e6c84a 0%,
    #c9a227 50%,
    #b8860b 100%);
  border-radius: 3px;
  z-index: 0;
  /* Layered: inner darker edge + soft ambient bloom — same vocabulary
     as the gold rule inside the ribbon tab, so the eye reads them as
     the same accent system. */
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.18),
    0 0 0 1px rgba(184,134,11,0.30),
    0 0 8px rgba(201,162,39,0.55);
  pointer-events: none;
}
._eli3_bd_step {
  position: relative;
  z-index: 1;                       /* sit ABOVE the parent's gold flow line */
  display: flex; align-items: center; gap: 12px;
  padding: 16px 18px 16px 0;       /* no left padding — ribbon tab is the left edge */
  /* Refined gradient — three stops with a warm-tinted highlight at top.
     Reads like brushed paper rather than flat white. */
  background: linear-gradient(180deg, #ffffff 0%, #fbfcfe 55%, #f1f5f9 100%);
  border: 1px solid #d6dce4;
  border-radius: 12px;
  overflow: hidden;                 /* clips the ribbon tab's right edge to match card radius */
  cursor: pointer;
  text-align: left;
  font: 600 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  /* Layered shadow stack — premium UIs build depth from 3 layers:
     glass inset highlight + sharp contact shadow + diffuse ambient. */
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.85) inset,
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 4px 12px -2px rgba(15, 23, 42, 0.08);
  transition: border-color .18s, background .18s, box-shadow .18s,
              transform .12s cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* ── Vertical ribbon tab — "Step N" left-edge label ───────────────────
   Replaces the old circular numbered node + inter-row connector line.
   Each card now has a ~52px vertical ribbon on its left edge running the
   full card height. Inside (stacked, centered): tiny "Step" kicker, large
   serif numeral 1-4, thin gold rule. The numeral flips to a ✓ check on
   completion. The background changes with state:
     • upcoming → navy gradient
     • current  → blue gradient
     • done     → green gradient
   The ribbon's right edge is straight; the card's overflow:hidden + 12px
   border-radius clips its outer-left corners to match the card.            */
._eli3_bd_v4tab {
  flex: 0 0 60px;
  width: 60px;
  /* Bleed past the row's 16px top/bottom padding so the ribbon fills the
     ENTIRE button height edge-to-edge — not just the inner content box.
     The card's overflow:hidden + 12px radius clips it cleanly. */
  align-self: stretch;
  margin: -16px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: linear-gradient(180deg, #0f1f3a 0%, #1e2f4e 100%);
  color: #fff;
  /* Tiny inner highlight on the right edge for premium depth. */
  box-shadow:
    inset -1px 0 0 rgba(255,255,255,0.06),
    1px 0 0 rgba(15,23,42,0.10);
  transition: background .18s;
}
._eli3_bd_v4tab_word {
  font: 800 11px/1 'Inter', 'Segoe UI', sans-serif;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  opacity: 0.78;
  color: #fff;
}
._eli3_bd_v4tab_num {
  font: 900 30px/1 'Georgia', 'Times New Roman', serif;
  color: #fff;
  /* drop-shadow for legibility against gradient backgrounds */
  text-shadow: 0 1px 2px rgba(0,0,0,0.3);
}
._eli3_bd_v4tab_rule {
  width: 22px;
  height: 2px;
  background: #e6c84a;            /* gold — same accent as throughout the tool */
  border-radius: 2px;
  margin-top: 3px;
}
/* CURRENT state — blue ribbon. Slightly brighter so it pops against
   the gold-cream current-card background. */
._eli3_bd_step_current ._eli3_bd_v4tab {
  background: linear-gradient(180deg, #1e40af 0%, #2563eb 100%);
}
/* DONE state — green ribbon. Numeral becomes ✓ via the JS (we just style
   the same .num span — it now contains "✓" instead of "1"-"4"). Sans
   serif font reads better for the check glyph. */
._eli3_bd_step_done ._eli3_bd_v4tab {
  background: linear-gradient(180deg, #16a34a 0%, #15803d 100%);
}
._eli3_bd_step_done ._eli3_bd_v4tab_num {
  font: 900 30px/1 'Inter', 'Segoe UI', sans-serif;
}
/* SKIPPED state — muted slate tab so the row reads as "not in your path". */
._eli3_bd_step_skipped ._eli3_bd_v4tab {
  background: linear-gradient(180deg, #64748b 0%, #475569 100%);
  opacity: 0.85;
}

/* Legacy ::before connector line — superseded by the ribbon tab.
   Suppressed so it doesn't render as a stray vertical artifact. */
._eli3_bd_step::before { content: none; }

/* "You are here" live indicator — premium light-blue blinking square next
   to the current step's label text (e.g., "Customize Template ▪"). Color
   ties to the current state's blue ribbon tab so the cue stays inside one
   color family; gold is reserved for the broader card identity. Two-stop
   gradient + inset highlight reads as a chip, not a flat fill. The pulse
   combines scale + a halo bloom + a faint inner glow so it feels alive
   without being noisy. */
._eli3_bd_live_sq {
  display: inline-block;
  width: 11px; height: 11px;
  margin-left: 8px;
  vertical-align: middle;
  background: linear-gradient(180deg, #60a5fa 0%, #3b82f6 100%);
  border-radius: 2px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.6),
    inset 0 -1px 0 rgba(29,78,216,0.4),
    0 0 0 1px rgba(29,78,216,0.4),
    0 0 6px 0 rgba(59,130,246,0.55);
  animation: _eli3_bd_live_pulse 1.4s infinite ease-in-out;
}
@keyframes _eli3_bd_live_pulse {
  0%, 100% {
    transform: scale(1);
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.6),
      inset 0 -1px 0 rgba(29,78,216,0.4),
      0 0 0 1px rgba(29,78,216,0.4),
      0 0 6px 0 rgba(59,130,246,0.55);
  }
  50% {
    transform: scale(1.18);
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.75),
      inset 0 -1px 0 rgba(29,78,216,0.5),
      0 0 0 2px rgba(59,130,246,0.35),
      0 0 12px 2px rgba(96,165,250,0.7);
  }
}
._eli3_bd_step:hover {
  /* Hover — cool slate-blue tint, NOT gold. Gold is reserved for the
     "current step" state so the user always knows which row is live.
     Mixing a gold hover with a gold current state read as confusing in
     the wild (every hovered row looked active). The hover here is a
     strong cool wash + deep lift — clearly distinct from BOTH resting
     and current/done states. The 2px lift + 28px ambient shadow + a
     bright cool background shift add up to "obvious affordance". */
  border-color: #475569;
  background: linear-gradient(180deg, #ffffff 0%, #eef2f7 55%, #d8e1ec 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 1) inset,
    0 3px 6px rgba(15, 23, 42, 0.10),
    0 16px 28px -6px rgba(15, 23, 42, 0.24);
  transform: translateY(-2px);
}
/* Current row hover — preserve its gold-cream identity, just lift more
   and saturate the gold shadow. We do NOT want hover to repaint the
   current row in slate (that would erase the "you are here" cue). */
._eli3_bd_step_current:hover {
  border-color: #8a6c10;
  background: linear-gradient(180deg, #fffefa 0%, #fef5d8 55%, #fce8a8 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.95) inset,
    0 3px 6px rgba(184, 134, 11, 0.18),
    0 18px 36px -8px rgba(184, 134, 11, 0.42);
  transform: translateY(-2px);
}
/* Done row hover — preserve green identity, deeper lift + green shadow. */
._eli3_bd_step_done:hover {
  border-color: #15803d;
  background: linear-gradient(180deg, #f7fef9 0%, #d3f3df 55%, #a7e9c5 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 3px 6px rgba(22, 163, 74, 0.16),
    0 16px 28px -6px rgba(22, 163, 74, 0.32);
  transform: translateY(-2px);
}
._eli3_bd_step:active {
  transform: translateY(0);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 1px 2px rgba(15, 23, 42, 0.05);
}
._eli3_bd_step_n {
  position: relative;
  z-index: 1;              /* sit ABOVE the connector line */
  flex: 0 0 32px;
  height: 32px;
  display: flex; align-items: center; justify-content: center;
  font: 800 14px/1 'Georgia', serif;
  color: #94a3b8;
  background: #fff;
  border: 2px solid #cbd5e1;
  border-radius: 50%;        /* round — reads as a "node" on the line */
  box-shadow: 0 0 0 4px #fff, 0 1px 3px rgba(15,23,42,0.08);
  /* The 4px white outer halo masks the connector line where it would
     otherwise enter the circle — visual cleanliness without computing
     per-row gaps in JS. */
  transition: background .15s, border-color .15s, color .15s, box-shadow .15s;
}

/* Eyebrow — STEP N OF 4. Premium gold by default; shifts to green when
   the step is done. This is the headline-of-the-row signal that ties the
   whole "1 → 4 progression" together. */
._eli3_bd_step_eyebrow {
  font: 900 9px/1 'Inter', 'Segoe UI', sans-serif;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #94a3b8;          /* slate for upcoming */
  margin-bottom: 4px;
}
._eli3_bd_step_current ._eli3_bd_step_eyebrow { color: #b8860b; }
._eli3_bd_step_done ._eli3_bd_step_eyebrow    { color: #16a34a; }

/* Current step — gold node with white text, and a softer ambient halo
   so it reads as "the live one." Border swaps to deeper gold for
   contrast against the pale-gold row background. */
._eli3_bd_step_current ._eli3_bd_step_n {
  color: #fff;
  background: linear-gradient(180deg, #d4af3c 0%, #c9a227 100%);
  border-color: #b8860b;
  box-shadow: 0 0 0 4px #fef9e7, 0 0 0 6px rgba(201,162,39,0.35), 0 2px 4px rgba(184,134,11,0.3);
}
/* CURRENT step row — gold-tinted cream gradient with layered shadow.
   Sits visibly higher than peer rows so the user always sees where they
   are. The 3-layer shadow stack includes a warm gold-toned ambient
   instead of generic slate. */
._eli3_bd_step_current {
  border-color: #e6c84a; border-left-color: #b8901f;
  background: linear-gradient(180deg, #fffefa 0%, #fef9e7 55%, #fdf2c4 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.95) inset,
    0 2px 4px rgba(184, 134, 11, 0.10),
    0 12px 28px -8px rgba(184, 134, 11, 0.28);
}
._eli3_bd_step_dot {
  position: absolute;
  top: -2px; right: -6px;
  width: 9px; height: 9px;
  background: #ef4444;
  border: 2px solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(239,68,68,0.4);
  animation: _eli3_bd_dot_pulse 1.6s infinite ease-in-out;
}
@keyframes _eli3_bd_dot_pulse {
  0%, 100% { transform: scale(1);   box-shadow: 0 0 0 1px rgba(239,68,68,0.4); }
  50%      { transform: scale(1.15); box-shadow: 0 0 0 4px rgba(239,68,68,0.18); }
}

/* Completed steps — green check replaces the step number, row tinted
   green so the user sees their progress at a glance. */
/* DONE step row — layered mint→sage gradient + soft green shadow. The
   "DONE" watermark stays subtle in the corner — a quiet trophy, not a
   victory banner. */
._eli3_bd_step_done {
  border-color: #86efac; border-left-color: #16a34a;
  background: linear-gradient(180deg, #f7fef9 0%, #ecfdf3 55%, #d3f3df 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 1px 2px rgba(22, 163, 74, 0.06),
    0 6px 16px -4px rgba(22, 163, 74, 0.14);
  position: relative; overflow: hidden;
}
._eli3_bd_step_done::after {
  content: "DONE"; position: absolute; right: 32px; top: 50%; transform: translateY(-50%);
  font: 900 22px/1 'Inter', sans-serif; letter-spacing: .18em; text-transform: uppercase;
  color: rgba(22,163,74,.12); pointer-events: none;
}

/* PENDING watermark — symmetric to DONE, but applied to every row that
   ISN'T done and isn't skipped (skipped rows have their own "· skipped"
   inline cue). Slate-gray faint by default; tinted gold-warm on the
   current step so it harmonizes with the gold-cream card background and
   doesn't fight the blinking square or blue ribbon. */
._eli3_bd_step:not(._eli3_bd_step_done):not(._eli3_bd_step_skipped) {
  position: relative;
  /* overflow:hidden already set on parent; ensures the watermark clips
     within the rounded card edge. */
}
._eli3_bd_step:not(._eli3_bd_step_done):not(._eli3_bd_step_skipped)::after {
  content: "PENDING";
  position: absolute;
  right: 32px; top: 50%; transform: translateY(-50%);
  font: 900 22px/1 'Inter', sans-serif;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: rgba(100,116,139,0.12);    /* slate, very faint — same opacity as DONE */
  pointer-events: none;
}
/* Current step's PENDING reads gold-tinted so it matches the gold-cream
   card background instead of looking like a stray slate watermark. */
._eli3_bd_step_current::after {
  color: rgba(184,134,11,0.16) !important;
}
._eli3_bd_step_done ._eli3_bd_step_label,
._eli3_bd_step_done ._eli3_bd_step_desc { color: #166534; }
/* Done step's NODE — green-filled circle, replaces the slate node. The
   ::before connector goes gold/green here too via the done modifier above.
   This `_eli3_bd_step_check` styles the ✓ glyph inside the node. */
._eli3_bd_step_done ._eli3_bd_step_n {
  background: linear-gradient(180deg, #34d399 0%, #22c55e 100%);
  border-color: #16a34a;
  color: #fff;
  box-shadow: 0 0 0 4px #f0fdf4, 0 1px 3px rgba(22,163,74,0.25);
}
._eli3_bd_step_check {
  display: inline-flex; align-items: center; justify-content: center;
  width: 100%; height: 100%;
  color: #fff;
  font: 800 15px/1 'Inter', sans-serif;
}

/* Skipped steps — toned-down because the template has no work for
   this step, but DON'T mark as "done" (user hasn't actually
   completed anything yet — there was just nothing to do here). No
   green check, no celebratory color; just faded so the eye lands on
   the active step. */
._eli3_bd_step_skipped {
  opacity: 0.55;
}
._eli3_bd_step_skipped ._eli3_bd_step_n { color: #94a3b8; }
._eli3_bd_step_skipped ._eli3_bd_step_desc::after {
  content: " · skipped";
  color: #94a3b8;
  font-style: italic;
}
._eli3_bd_step_icon { font-size: 22px; flex: 0 0 auto; filter: drop-shadow(0 1px 2px rgba(15,23,42,0.08)); }
._eli3_bd_step_info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
/* Label — tighter tracking + slightly heavier than before for headline-
   weight presence. Serif fallback (Georgia) is intentional so legal-doc
   workflows feel typographically deliberate. */
._eli3_bd_step_label {
  font: 800 14px/1.2 'Inter', 'Segoe UI', sans-serif;
  color: #0f172a;
  letter-spacing: -.25px;
}
._eli3_bd_step_desc { font: 400 11.5px/1.45 'Inter', sans-serif; color: #64748b; }
/* Chevron — thin elegant glyph (›), color matches the eyebrow accent so
   the row reads as "go forward" without shouting. Gold on hover ties to
   the warming background. */
._eli3_bd_step_arrow {
  font: 300 22px/1 'Inter', 'Segoe UI', system-ui, sans-serif;
  color: #cbd5e1;
  flex: 0 0 auto;
  margin-right: 2px;
  transition: transform .2s cubic-bezier(0.2, 0.8, 0.2, 1), color .15s;
}
._eli3_bd_step:hover ._eli3_bd_step_arrow {
  transform: translateX(3px);
  color: #b8901f;
}
._eli3_bd_step_current ._eli3_bd_step_arrow { color: #b8901f; }
._eli3_bd_step_done    ._eli3_bd_step_arrow { color: #16a34a; }
._eli3_bd_step_done_at { font: 500 10px/1 'Inter', sans-serif; color: #16a34a; }
._eli3_bd_step_badge {
  display: inline-block;
  margin-left: 6px;
  padding: 2px 7px;
  font: 800 9px/1.2 'Inter', sans-serif;
  background: #fef3c7; color: #92400e;
  vertical-align: 1px;
}

/* Bracket Cleaner panel */
._eli3_bd_cleaner_intro {
  padding: 12px 14px;
  margin: 12px 14px 0;
  background: #fff7ed;
  border-left: 4px solid #f59e0b;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #5d4037;
}
._eli3_bd_cleaner_list {
  flex: 1; overflow-y: auto;
  padding: 12px 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_cleaner_empty {
  text-align: center; padding: 30px 0;
  font: 600 12px/1.4 'Inter', sans-serif; color: #94a3b8;
  font-style: italic;
}
._eli3_bd_cleaner_row {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #b0bec5;
}
._eli3_bd_cleaner_row:hover { border-left-color: #1565c0; }
._eli3_bd_cleaner_left { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; }
._eli3_bd_cleaner_right { display: flex; gap: 6px; flex: 0 0 auto; }
._eli3_bd_cleaner_tag {
  font: 800 10px/1 'Inter', sans-serif;
  color: #475569;
  background: #f1f5f9;
  padding: 3px 6px;
  flex: 0 0 auto;
}
._eli3_bd_cleaner_tag_money { background: #d1fae5; color: #065f46; }
._eli3_bd_cleaner_text {
  font: 600 12px/1.3 'JetBrains Mono', monospace;
  color: #0f172a;
  word-break: break-word;
}
._eli3_bd_action_btn {
  padding: 6px 10px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a; border: 1px solid #b0bec5;
  cursor: pointer;
  white-space: nowrap;
}
._eli3_bd_action_btn:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); border-color: #90caf9; color: #1565c0; }
._eli3_bd_action_help { color: #1565c0; }
._eli3_bd_cleaner_done { padding: 12px 14px; border-top: 1px solid #e2e8f0; }

/* SOW Helper modal */
._eli3_bd_sow_intro {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #475569;
  margin-bottom: 12px;
}
._eli3_bd_sow_options { display: flex; flex-direction: column; gap: 6px; }
._eli3_bd_sow_option {
  padding: 10px 12px;
  text-align: left;
  background: #fff;
  border: 1px solid #e2e8f0;
  cursor: pointer;
  display: flex; flex-direction: column; gap: 3px;
  transition: border-color .15s, background .15s;
}
._eli3_bd_sow_option:hover { border-color: #1565c0; background: #f8fafc; }
._eli3_bd_sow_option_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #1565c0;
  text-transform: uppercase; letter-spacing: 0.4px;
}
._eli3_bd_sow_option_desc {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #334155;
}

/* Dark-mode for cleaner + SOW */

._eli3_bd_foot {
  flex: 0 0 auto;
  padding: 8px 14px 12px;
  font: 400 10px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  text-align: center;
  border-top: 1px dashed #e2e8f0;
}

._eli3_bd_step_body { flex: 1; overflow-y: auto; padding: 24px 16px; }
._eli3_bd_step_pending { text-align: center; padding: 30px 12px; }
._eli3_bd_step_pending_icon { font-size: 42px; margin-bottom: 10px; }
._eli3_bd_step_pending_title { font: 800 16px/1.2 'Georgia', serif; color: #0f172a; margin-bottom: 6px; }
._eli3_bd_step_pending_desc { font: 400 12px/1.5 'Inter', sans-serif; color: #64748b; max-width: 360px; margin: 0 auto; }

/* Dark mode */

@media (max-width: 380px) {
  ._eli3_bd_run_all { font-size: 11px; padding: 10px 8px; }
  ._eli3_bd_templates { font-size: 10px; padding: 10px 8px; }
}

/* =====================================================================
   Step 1 — Logic Builder form  (premium chrome — gold accent, cream
   gradient, custom chevron on selects)
   ===================================================================== */
/* Header inherits the standard dark navy `_eli3_bd_bar` — no override. */
._eli3_bd_logic_form {
  flex: 1 1 auto;
  overflow-y: auto;
  /* 2026-05-20: compact spacing — gap 12→6, padding 16→10, so ~50%
     more questions fit before scrolling. */
  padding: 10px 10px 2px;
  display: flex; flex-direction: column; gap: 6px;
  background: linear-gradient(180deg, #ffffff 0%, #faf9ee 100%);
}
._eli3_bd_logic_group {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  /* 2026-05-20: tighter row padding + internal gap so the dropdown
     sits closer to its label without losing the gold rail. */
  padding: 7px 10px;
  display: flex; flex-direction: column; gap: 4px;
  box-shadow: 0 1px 0 rgba(15, 23, 42, 0.04);
  transition: box-shadow 0.15s, border-color 0.15s;
}
._eli3_bd_logic_group:hover {
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.08);
}
._eli3_bd_logic_label {
  display: flex; align-items: center; flex-wrap: wrap; gap: 6px;
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #475569;
}
/* 2026-05-22: 📘 GUIDANCE + 🔎 OARS buttons grouped + right-anchored.
   Same pattern as Step 2's _eli3_bd_fill_label_btns — the label-text
   stays left, the button cluster sits on the right side via margin-
   left:auto. Warning chip (if any) flows between, left-of-buttons. */
._eli3_bd_logic_label_btns {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  flex-shrink: 0;
}
._eli3_bd_logic_label_text { display: inline; }
._eli3_bd_logic_oars_lookup {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: linear-gradient(180deg, #fffdf5 0%, #fef3c7 100%);
  border: 1px solid #d6b347;
  font: 700 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #78451c;
  padding: 3px 7px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.85), 0 1px 2px rgba(120,69,28,0.08);
}
._eli3_bd_logic_oars_lookup:hover {
  background: linear-gradient(180deg, #fffdf5 0%, #fde68a 100%);
  border-color: #c9a227;
  color: #5a330f;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.95), 0 2px 5px rgba(201,162,39,0.22);
  transform: translateY(-1px);
}
._eli3_bd_logic_oars_lookup:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 2px rgba(120,69,28,0.12);
}
/* 2026-05-21: GUIDANCE button on Step 1 DEF questions. Blue accent
   differentiates from OARS LOOKUP gold. Click opens a premium dialog
   showing the guidance text. Only renders when the DEF tag has a
   `| guidance:` segment. */
._eli3_bd_logic_guidance {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border: 1px solid #60a5fa;
  font: 700 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #1e40af;
  padding: 3px 7px;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.85), 0 1px 2px rgba(30,64,175,0.08);
}
._eli3_bd_logic_guidance:hover {
  background: linear-gradient(180deg, #eff6ff 0%, #bfdbfe 100%);
  border-color: #1d4ed8;
  color: #1e3a8a;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.95), 0 2px 5px rgba(30,64,175,0.22);
  transform: translateY(-1px);
}
._eli3_bd_logic_guidance:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 2px rgba(30,64,175,0.14);
}
._eli3_bd_logic_warning {
  font: 500 9.5px/1.2 'Inter', sans-serif;
  color: #b45309; background: #fef3c7;
  padding: 2px 6px;
  text-transform: none; letter-spacing: 0;
}
._eli3_bd_logic_hint {
  font: 400 10px/1.25 'Inter', sans-serif;
  color: #64748b; font-style: italic;
}
._eli3_bd_logic_input {
  width: 100%;
  /* 2026-05-20: 9/11px padding → 5/9px, font 13→12 for shorter rows. */
  padding: 5px 9px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 12px/1.25 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_bd_logic_input:focus {
  border-color: #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.18);
}
/* 2026-05-20: free-text inputs render visually distinct from dropdowns —
   cream-amber tinted background, deeper gold border, leading ✍️ icon
   inside the field. Stays premium (no dashed/scratchy treatment) while
   signaling "type here, this isn't a pick list." */
._eli3_bd_logic_text_wrap {
  position: relative;
  display: block;
}
._eli3_bd_logic_text_icon {
  position: absolute;
  left: 9px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 13px;
  line-height: 1;
  pointer-events: none;
  opacity: 0.75;
  filter: saturate(0.85);
}
._eli3_bd_logic_input_text {
  padding-left: 30px;
  background: linear-gradient(180deg, #fffdf5 0%, #fef6dc 100%);
  border-color: #d6b347;
  color: #1f1606;
  font-family: 'Georgia', serif;
  /* 2026-05-22: removed font-style:italic from the input itself — that
     italicized the user's typed answer, which read as placeholder
     text not real content. Placeholder italics (below) stay so empty
     fields still look prompt-like. */
  font-style: normal;
  font-weight: 500;
}
._eli3_bd_logic_input_text:focus {
  background: linear-gradient(180deg, #fffefa 0%, #fef0c2 100%);
  border-color: #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.28);
}
._eli3_bd_logic_input_text::placeholder {
  color: #b8961f;
  font-style: italic;
  opacity: 0.7;
}
/* Custom chrome on the native <select> — strip the platform arrow,
   draw a gold chevron via inline SVG. Open dropdown menu stays
   browser-rendered (can't fully restyle <option>), but the closed
   state matches the rest of the premium chrome. */
select._eli3_bd_logic_input {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  padding-right: 32px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='%23c9a227' d='M0 0l5 6 5-6z'/></svg>");
  background-repeat: no-repeat;
  background-position: right 12px center;
  cursor: pointer;
}
._eli3_bd_logic_actions {
  flex: 0 0 auto;
  display: flex; gap: 8px;
  padding: 14px 16px;
  border-top: 1px solid #fde68a;
  background: linear-gradient(180deg, #faf9ee 0%, #f5f1d9 100%);
}
._eli3_bd_logic_empty {
  flex: 1 1 auto;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 40px 24px;
  text-align: center;
  gap: 12px;
}
._eli3_bd_logic_empty_icon { font-size: 48px; opacity: 0.6; }
._eli3_bd_logic_empty_title { font: 800 14px/1.2 'Inter', sans-serif; color: #0f172a; letter-spacing: 0.4px; }
._eli3_bd_logic_empty_desc { font: 500 12px/1.5 'Inter', sans-serif; color: #64748b; max-width: 320px; }
._eli3_bd_logic_empty_desc code {
  font: 600 11px/1 monospace;
  background: #f1f5f9; padding: 2px 5px;
  color: #1565c0;
}
/* Override .__eli3_bd_run_all's `flex:2` so the OARS button in the
   empty-state column doesn't stretch to fill the whole panel
   vertically. Natural size only, modest padding, centered. */
._eli3_bd_logic_oars_btn {
  flex: 0 0 auto;
  align-self: center;
  margin-top: 12px;
  min-width: 200px;
  padding: 10px 18px;
  font-size: 11px;
}

/* =====================================================================
   Step 2 — Template Fill form
   ===================================================================== */
/* Header keeps the standard dark navy banner (no override). */
._eli3_bd_fill_loaded_wrap {
  margin: 12px 14px;
}
._eli3_bd_fill_loaded {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  /* Premium light-slate background with a subtle green accent stripe on
     the left to signal "loaded" without saturating the whole box. */
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  border-left: 4px solid #10b981;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
._eli3_bd_fill_loaded_main { min-width: 0; }
._eli3_bd_fill_loaded_label {
  font: 800 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #047857;
}
._eli3_bd_fill_loaded_name {
  font: 700 13px/1.3 'Georgia', serif;
  color: #0f172a; margin-top: 3px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* 2026-05-27: requester row, optional middle slot between LOADED SOURCE
   label and the source filename. Subtle teal accent on the value so it
   reads as a secondary fact, not competing with the filename. */
._eli3_bd_fill_loaded_requester {
  font: 600 11px/1.3 'Inter', sans-serif;
  color: #475569; margin-top: 3px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
._eli3_bd_fill_loaded_requester > span {
  color: #0f172a; font-weight: 700;
}

/* 2026-05-27: Email Requester per-card checkbox (hidden until card is
   _bd_missing post-autofill). Small inline pill next to the 📍 locate
   pin. Red accent ties it to the "missing" state. */
._eli3_bd_fill_email_chk {
  display: inline-flex; align-items: center; gap: 4px;
  margin-left: 6px;
  padding: 2px 8px;
  border: 1px solid #fecaca;
  background: #fef2f2;
  border-radius: 999px;
  font: 700 9.5px/1 'Inter', sans-serif;
  color: #991b1b;
  letter-spacing: 0.5px;
  cursor: pointer;
  user-select: none;
}
._eli3_bd_fill_email_chk:hover {
  background: #fee2e2;
  border-color: #fca5a5;
}
._eli3_bd_fill_email_chk > input[type="checkbox"] {
  margin: 0;
  cursor: pointer;
  accent-color: #b91c1c;
}

/* Email Requester bar above FILL ALL FIELDS. Hidden default; revealed
   in JS when count > 0. Red gradient to signal it's a "fix what's
   broken" action vs the gold APPLY button. */
._eli3_bd_email_bar {
  margin-bottom: 8px;
  display: flex; justify-content: center;
}
._eli3_bd_email_btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 18px;
  border: 1px solid #b91c1c;
  background: linear-gradient(180deg, #ef4444, #b91c1c);
  color: #fff;
  border-radius: 6px;
  font: 700 12.5px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(185, 28, 28, 0.25);
  transition: transform 0.1s ease, box-shadow 0.15s ease;
}
._eli3_bd_email_btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(185, 28, 28, 0.35);
}
._eli3_bd_email_btn:active {
  transform: translateY(0);
}
._eli3_bd_email_btn_icon { font-size: 14px; }
._eli3_bd_email_count {
  display: inline-block;
  min-width: 18px;
  padding: 0 4px;
  background: rgba(255, 255, 255, 0.25);
  border-radius: 999px;
  font-weight: 800;
}
._eli3_bd_fill_autofill_btn {
  /* Fixed width so the button stays exactly where it is when the label
     changes from "AUTO-FILL" → "Filling…" (icon + label tokens swap
     in place; the box never resizes or shifts). */
  width: 150px;
  flex: 0 0 150px;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  /* Premium dark-navy gradient with gold accent border — matches the
     kernel header / Save panel / cross-tool standard. */
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #f2d866;
  border: 1px solid #c9a227;
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(13, 27, 42, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}
._eli3_bd_fill_autofill_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1b263b 0%, #2d3a52 100%);
  color: #ffd700;
  box-shadow: 0 4px 12px rgba(13, 27, 42, 0.35), 0 0 0 3px rgba(201, 162, 39, 0.18);
  transform: translateY(-1px);
}
._eli3_bd_fill_autofill_btn:disabled {
  opacity: 0.85;
  cursor: progress;
}
._eli3_bd_fill_autofill_btn_filling {
  background: linear-gradient(135deg, #1e293b 0%, #334155 100%);
  color: #cbd5e1;
  border-color: rgba(201, 162, 39, 0.6);
}
._eli3_bd_fill_autofill_icon { font-size: 12px; line-height: 1; }
._eli3_bd_fill_autofill_label { white-space: nowrap; }
._eli3_bd_fill_status {
  margin: 8px 14px 0;
  padding: 8px 12px;
  font: 600 11px/1.4 'Inter', sans-serif;
  color: #047857;
  background: #ecfdf5;
  border-left: 3px solid #10b981;
}
/* Override the outer-wrap margin when status is its sibling — the
   wrap already provides the 14px horizontal margin via _eli3_bd_fill_loaded_wrap. */
._eli3_bd_fill_loaded_wrap > ._eli3_bd_fill_status {
  margin: 8px 0 0;
}

/* ─── Step 2 working states (2026-06-12) ─────────────────────────────
   Double-click guard UX. While a scan / AI fill / apply is in flight the
   trigger control disables and animates:
   _eli3_bd_apply_working — apply buttons (classic + guided)
   _eli3_bd_step_working  — hub Step 2 row during the placeholder scan
   _eli3_bd_ai_working*   — guided-mode AI auto-fill screen */
._eli3_bd_apply_working {
  position: relative;
  overflow: hidden;
  pointer-events: none;
  cursor: progress;
}
._eli3_bd_apply_working::after {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: -60%;
  width: 50%;
  background: linear-gradient(110deg, transparent 0%, rgba(255, 255, 255, 0.35) 50%, transparent 100%);
  animation: _eli3_bd_work_sweep 1.4s ease-in-out infinite;
}
@keyframes _eli3_bd_work_sweep { to { left: 110%; } }
._eli3_bd_work_spin {
  display: inline-block;
  width: 14px; height: 14px;
  flex: 0 0 14px;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #fff;
  border-radius: 50%;
  animation: _eli3_bd_save_spin 0.7s linear infinite;
}
._eli3_bd_work_phrase { display: inline-block; }
._eli3_bd_work_phrase_in { animation: _eli3_bd_guided_fadein 0.35s ease; }

._eli3_bd_step_working {
  position: relative;
  overflow: hidden;
  pointer-events: none;
}
._eli3_bd_step_working::after {
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: -60%;
  width: 50%;
  background: linear-gradient(110deg, transparent 0%, rgba(201, 162, 39, 0.16) 50%, transparent 100%);
  animation: _eli3_bd_work_sweep 1.6s ease-in-out infinite;
}
._eli3_bd_step_working ._eli3_bd_step_desc { color: #b45309; font-weight: 600; }
._eli3_bd_workdots span {
  opacity: 0.2;
  animation: _eli3_bd_work_dot 1.2s infinite;
}
._eli3_bd_workdots span:nth-child(2) { animation-delay: 0.2s; }
._eli3_bd_workdots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes _eli3_bd_work_dot { 0%, 80%, 100% { opacity: 0.2; } 40% { opacity: 1; } }

._eli3_bd_ai_working {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 14px;
  padding: 48px 24px;
  text-align: center;
}
._eli3_bd_ai_working_ring {
  position: relative;
  width: 64px; height: 64px;
  display: flex; align-items: center; justify-content: center;
  font-size: 26px;
}
._eli3_bd_ai_working_ring::before {
  content: "";
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  border-radius: 50%;
  border: 3px solid #f1f5f9;
  border-top-color: #c9a227;
  border-right-color: #dbb846;
  animation: _eli3_bd_save_spin 0.9s linear infinite;
}
._eli3_bd_ai_working_title { font: 700 16px/1.2 'Inter', sans-serif; color: #0f172a; }
._eli3_bd_ai_working_phrase {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #64748b;
  max-width: 260px;
  min-height: 18px;
}
._eli3_bd_ai_working_bar {
  width: 140px; height: 4px;
  background: #e2e8f0;
  border-radius: 2px;
  overflow: hidden;
}
._eli3_bd_ai_working_bar::after {
  content: "";
  display: block;
  height: 100%; width: 40%;
  border-radius: 2px;
  background: linear-gradient(90deg, #c9a227, #dbb846);
  animation: _eli3_bd_work_slide 1.2s ease-in-out infinite alternate;
}
@keyframes _eli3_bd_work_slide { from { margin-left: 0; } to { margin-left: 60%; } }
._eli3_bd_fill_drop {
  margin: 12px 14px;
  padding: 24px 16px;
  border: 2px dashed #cbd5e1;
  background: #f8fafc;
  text-align: center;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_bd_fill_drop:hover {
  border-color: #1565c0;
  background: #eff6ff;
}
._eli3_bd_fill_drop_icon { font-size: 36px; }
._eli3_bd_fill_drop_title {
  font: 700 12px/1.2 'Inter', sans-serif;
  color: #0f172a; margin-top: 6px;
  text-transform: uppercase; letter-spacing: 0.4px;
}
._eli3_bd_fill_drop_desc {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #64748b; margin-top: 4px;
}
._eli3_bd_fill_form {
  flex: 1 1 auto;
  overflow-y: auto;
  /* 2026-05-20: compact spacing — gap 10→5, vertical pads tighter so
     ~50% more placeholder fields fit before scrolling. Matches Step 1
     compact pass. */
  padding: 2px 10px 4px;
  display: flex; flex-direction: column; gap: 5px;
}
._eli3_bd_fill_field {
  background: #fff;
  border: 1px solid #e2e8f0;
  /* 2026-05-20: row padding 10/12 → 5/9, internal gap 4 → 2. */
  padding: 5px 9px;
  display: flex; flex-direction: column; gap: 2px;
}
._eli3_bd_fill_label {
  display: flex; align-items: center; justify-content: space-between; gap: 6px;
  font: 700 10px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_bd_fill_label_btns {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
/* 2026-05-20: inline label text + helper button sit together on the
   LEFT side of the label row (the action buttons stay grouped on the
   right via _eli3_bd_fill_label_btns + the parent's space-between). */
._eli3_bd_fill_label_text {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 0 1 auto;
}
._eli3_bd_fill_locate {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  /* 2026-05-22: icon-only pin (📍), inline with the label text. Tighter
     padding + larger glyph than the old text version. No letter-spacing
     since there's no text to space out. */
  font: 700 11px/1 'Inter', sans-serif;
  color: #475569;
  padding: 1px 5px;
  border-radius: 3px;
  cursor: pointer;
  display: inline-flex; align-items: center;
  transition: all 0.15s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.8), 0 1px 2px rgba(0,0,0,0.05);
}
._eli3_bd_fill_locate:hover {
  background: linear-gradient(180deg, #fff 0%, #e0f2fe 100%);
  border-color: #0284c7;
  color: #0369a1;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), 0 2px 4px rgba(2,132,199,0.15);
  transform: translateY(-1px);
}
._eli3_bd_fill_locate:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.1);
}
/* 2026-05-20: OARS LOOKUP — gold accent (matches ⚡ auto-fill theme).
   Same dimensions as LOCATE IN DOC, distinct color so the user can
   tell at a glance which jumps to the doc vs which opens OARS. */
._eli3_bd_fill_oars {
  background: linear-gradient(180deg, #fffdf5 0%, #fef3c7 100%);
  border: 1px solid #d6b347;
  font: 700 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #78451c;
  padding: 3px 8px;
  border-radius: 3px;
  cursor: pointer;
  display: inline-flex; align-items: center; gap: 3px;
  transition: all 0.15s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.85), 0 1px 2px rgba(120,69,28,0.08);
}
._eli3_bd_fill_oars:hover {
  background: linear-gradient(180deg, #fffdf5 0%, #fde68a 100%);
  border-color: #c9a227;
  color: #5a330f;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.95), 0 2px 5px rgba(201,162,39,0.22);
  transform: translateY(-1px);
}
._eli3_bd_fill_oars:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 2px rgba(120,69,28,0.12);
}
/* 2026-05-20: Payment Helper — emerald gradient signals "money / dollars."
   Field also gets a subtle left-rail accent (_eli3_bd_fill_field_payment)
   so the user knows which fields can use the helper at a glance. */
._eli3_bd_fill_field_payment {
  border-left: 3px solid #047857;
}
._eli3_bd_fill_payment {
  /* 2026-05-21: switched green→blue so the button stands out against
     the green-bordered payment input field. Same blue family used by
     the kernel's primary action buttons (linear-gradient navy). */
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border: 1px solid #3b82f6;
  font: 700 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #1e3a8a;
  padding: 3px 8px;
  border-radius: 3px;
  cursor: pointer;
  display: inline-flex; align-items: center; gap: 3px;
  transition: all 0.15s;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.85), 0 1px 2px rgba(30,58,138,0.12);
}
._eli3_bd_fill_payment:hover {
  background: linear-gradient(180deg, #eff6ff 0%, #bfdbfe 100%);
  border-color: #1d4ed8;
  color: #1e3a8a;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.95), 0 2px 5px rgba(30,58,138,0.22);
  transform: translateY(-1px);
}
._eli3_bd_fill_payment:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 2px rgba(30,58,138,0.18);
}
._eli3_bd_fill_input {
  width: 100%;
  /* 2026-05-20: min-height 32→24, padding 8/12 → 4/9, font 13→12 to
     match compact pass. Lower min-height lets single-line filled
     values sit shorter; auto-resize (set in JS) still expands for
     longer text. */
  min-height: 24px;
  padding: 4px 9px;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  background: #fff;
  font: 500 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
  resize: none;
  overflow: hidden;
  transition: border-color 0.18s, background 0.18s, box-shadow 0.18s;
}
._eli3_bd_fill_input:focus {
  border-color: #1565c0;
  border-left-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
/* AI auto-fill state markers — applied after each fill attempt.
   Filled cells now use a green left-bar + soft mint background so
   populated fields read at a glance. Missing cells get a red left-bar
   + light red wash. Both states win over base styling.            */
._eli3_bd_fill_input._bd_filled {
  border-color: #86efac;
  border-left: 3px solid #16a34a;
  background: linear-gradient(180deg, #f0fdf4 0%, #ecfdf5 100%);
  color: #14532d;
  font-weight: 600;
}
._eli3_bd_fill_input._bd_missing {
  border-color: #fca5a5;
  border-left: 3px solid #dc2626;
  background: #fef2f2;
}
/* 2026-05-20: premium empty-state for the placeholder-fill view. Hero
   icon + eyebrow + title + 2x2 marker-syntax card + tip + diagnostics.
   Centered hero block, gold accent rail at the bottom to match other
   Build Draft chrome. Whole block is a fixed-width column on a soft
   cream-to-white gradient background. */
